        status: 'running',
      });

      // Wait for coordination to complete
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Check task status
      const statusResponse = await app.request(`/api/ai-coordination/tasks/${result.data.id}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${authToken}`,
