        organizationId: mockOrganizationId,
        userId: mockUserId
      });

      // Mock streaming response with tool call
      const mockStream = {
        async *[Symbol.asyncIterator]() {
          yield { content: 'I\'ll analyze', done: false };
          yield { 
            content: '',
            metadata: {
              toolCalls: [{
                function: {
                  name: 'analyze_data',
                  arguments: JSON.stringify({
                    data: [1, 2, 3, 4, 5],
                    analysisType: 'statistical'
                  })
                }
              }]
            },
            done: false 
