  });
});

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import app from '../../hono';
import { getDb } from '../../db/connection';

/**
 * Integration Tests for Authentication Routes
 * Tests the full flow from API request to database interaction
 */

describe('Auth Integration Tests', () => {
  let db: any;

  beforeAll(() => {
    db = getDb();
    console.log('🧪 Starting auth integration tests');
  });

  afterAll(() => {
    console.log('✅ Auth integration tests completed');
  });

  describe('POST /auth/register', () => {
    it('should register a new user with valid credentials', async () => {
      const response = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email: `test-${Date.now()}@example.com`,
          password: 'SecurePassword123!',
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(201);
      const data = await response.json();
      expect(data).toHaveProperty('userId');
      expect(data).toHaveProperty('email');
    });

    it('should reject duplicate email addresses', async () => {
      const email = `duplicate-${Date.now()}@example.com`;
      
      // First registration
      await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({ email, password: 'Password123!', firstName: 'Test', lastName: 'User' }),
        headers: { 'Content-Type': 'application/json' },
      });

      // Attempt duplicate
      const response = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({ email, password: 'Password123!', firstName: 'Test', lastName: 'User' }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(409);
      const data = await response.json();
      expect(data.error).toContain('already exists');
    });

    it('should validate email format', async () => {
      const response = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email: 'invalid-email',
          password: 'Password123!',
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(400);
      const data = await response.json();
      if (typeof data.error === 'string') {
        expect(data.error).toContain('email');
      } else {
        expect(data.error).toHaveProperty('code');
        expect(data.error).toHaveProperty('details');
        expect(String(data.error.code)).toContain('VALIDATION');
        expect(JSON.stringify(data.error.details)).toContain('email');
      }
    });

    it('should enforce password requirements', async () => {
      const response = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email: `test-${Date.now()}@example.com`,
          password: 'weak', // Too short, no special chars
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(400);
      const data = await response.json();
      if (typeof data.error === 'string') {
        expect(data.error).toContain('password');
      } else {
        expect(data.error).toHaveProperty('details');
        expect(JSON.stringify(data.error.details)).toContain('password');
      }
    });
  });

  describe('POST /auth/login', () => {
    let testEmail: string;
    let testPassword: string = 'TestPassword123!';

    beforeAll(async () => {
      // Create test user
      testEmail = `login-test-${Date.now()}@example.com`;
      await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email: testEmail,
          password: testPassword,
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });
    });

    it('should login with correct credentials', async () => {
      const response = await app.request('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email: testEmail, password: testPassword }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(200);
      const data = await response.json();
      expect(data).toHaveProperty('token');
      expect(data).toHaveProperty('userId');
    });

    it('should reject incorrect password', async () => {
      const response = await app.request('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email: testEmail, password: 'WrongPassword123!' }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(401);
      const data = await response.json();
      expect(data.error).toContain('Invalid credentials');
    });

    it('should reject non-existent user', async () => {
      const response = await app.request('/auth/login', {
        method: 'POST',
        body: JSON.stringify({
          email: `nonexistent-${Date.now()}@example.com`,
          password: testPassword,
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(401);
    });

    it('should enforce rate limiting after 5 failed attempts', async () => {
      const email = `ratelimit-${Date.now()}@example.com`;
      
      // Make 5 failed login attempts
      for (let i = 0; i < 5; i++) {
        await app.request('/auth/login', {
          method: 'POST',
          body: JSON.stringify({ email, password: 'WrongPassword' }),
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // 6th attempt should be rate limited
      const response = await app.request('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email, password: 'WrongPassword' }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(429);
      const data = await response.json();
      expect(data.error).toContain('too many');
    });
  });

  describe('POST /auth/logout', () => {
    it('should invalidate session token', async () => {
      // Setup: Create user and get token
      const email = `logout-test-${Date.now()}@example.com`;
      const password = 'TestPassword123!';
      
      await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({ email, password, firstName: 'Test', lastName: 'User' }),
        headers: { 'Content-Type': 'application/json' },
      });

      const loginRes = await app.request('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email, password }),
        headers: { 'Content-Type': 'application/json' },
      });

      const { token } = await loginRes.json();

      // Logout
      const logoutRes = await app.request('/auth/logout', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` },
      });

      expect(logoutRes.status).toBe(200);

      // Verify token is now invalid (should fail on protected route)
      const protectedRes = await app.request('/api/mfa/status', {
        method: 'GET',
        headers: { 'Authorization': `Bearer ${token}` },
      });

      expect(protectedRes.status).toBe(401);
    });
  });

  describe('POST /auth/verify-email', () => {
    it('should verify email with correct verification code', async () => {
      const email = `verify-${Date.now()}@example.com`;
      
      // Register user (email not verified yet)
      const registerRes = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email,
          password: 'TestPassword123!',
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      const { userId, verificationCode } = await registerRes.json();

      // Verify email
      const verifyRes = await app.request('/auth/verify-email', {
        method: 'POST',
        body: JSON.stringify({ userId, verificationCode }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(verifyRes.status).toBe(200);
      const data = await verifyRes.json();
      expect(data.verified).toBe(true);
    });

    it('should reject incorrect verification code', async () => {
      const email = `verify-fail-${Date.now()}@example.com`;
      
      const registerRes = await app.request('/auth/register', {
        method: 'POST',
        body: JSON.stringify({
          email,
          password: 'TestPassword123!',
          firstName: 'Test',
          lastName: 'User',
        }),
        headers: { 'Content-Type': 'application/json' },
      });

      const { userId } = await registerRes.json();

      const verifyRes = await app.request('/auth/verify-email', {
        method: 'POST',
        body: JSON.stringify({ userId, verificationCode: 'WRONG-CODE' }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(verifyRes.status).toBe(400);
      const data = await verifyRes.json();
      expect(data.error).toContain('Invalid');
    });
  });

  describe('POST /auth/reset-password', () => {
    it('should enforce stricter rate limiting on password reset', async () => {
      const email = `reset-${Date.now()}@example.com`;

      // Make 3 password reset requests
      for (let i = 0; i < 3; i++) {
        await app.request('/auth/reset-password', {
          method: 'POST',
          body: JSON.stringify({ email }),
          headers: { 'Content-Type': 'application/json' },
        });
      }

      // 4th attempt should be rate limited (stricter than login)
      const response = await app.request('/auth/reset-password', {
        method: 'POST',
        body: JSON.stringify({ email }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(429);
    });
  });

  describe('CSRF Protection', () => {
    it('should require CSRF token for POST requests', async () => {
      const response = await app.request('/api/trpc/auth.logout', {
        method: 'POST',
        body: JSON.stringify({ name: 'New Name' }),
        headers: { 'Content-Type': 'application/json' },
      });

      expect(response.status).toBe(403);
      const data = await response.json();
      expect(data.error).toContain('CSRF');
    });

    it('should accept valid CSRF token', async () => {
      // Get CSRF token
      const tokenRes = await app.request('/csrf-token', {
        method: 'POST',
        headers: { 'x-session-id': 'test-session' },
      });

      const { csrfToken } = await tokenRes.json();

      // Use CSRF token in protected request
      const response = await app.request('/api/trpc/auth.logout', {
        method: 'POST',
        body: JSON.stringify({ name: 'New Name' }),
        headers: {
          'Content-Type': 'application/json',
          'x-csrf-token': csrfToken,
          'x-session-id': 'test-session',
        },
      });

      expect(response.status).not.toBe(403);
    });
  });
});

/**
 * Consolidated Services Integration Tests
 * Tests the integration between consolidated alerting, rate limiting, and CSRF systems
 */

import request from 'supertest';
import { Hono } from 'hono';
import { alertingSystem, AlertSeverity, AlertStatus } from '../../lib/alerting-system';
import { checkRateLimit, resetRateLimit, RateLimitPresets } from '../../lib/unified-rate-limiting';
import { generateCSRFToken, verifyCSRFToken } from '../../lib/unified-csrf';

describe('Consolidated Services Integration', () => {
  let app: Hono;
  let userId: string;
  let sessionId: string;

  beforeAll(async () => {
    // Initialize test application with consolidated middleware
    app = new Hono();

    // Setup CSRF protection
    app.get('/csrf-token', async (c) => {
      const token = generateCSRFToken(userId);
      return c.json({ csrfToken: token });
    });

    // Setup protected route with rate limiting
    app.post('/protected-action', async (c) => {
      const authHeader = c.req.header('authorization');
      const csrfToken = c.req.header('x-csrf-token');

      // Simulate authentication check
      if (!authHeader?.startsWith('Bearer test-token')) {
        return c.json({ error: 'Unauthorized' }, 401);
      }

      // CSRF validation
      if (!verifyCSRFToken(csrfToken || '', sessionId)) {
        return c.json({ error: 'Invalid CSRF token' }, 403);
      }

      // Rate limiting check
      const rateLimitResult = checkRateLimit(userId, RateLimitPresets.MODERATE);
      if (!rateLimitResult.allowed) {
        return c.json({ 
          error: 'Rate limit exceeded',
          retryAfter: Math.ceil((rateLimitResult.resetAt - Date.now()) / 1000)
        }, 429);
      }

      // Trigger an alert for testing
      const alert = alertingSystem.createAlert({
        name: 'Protected Action Alert',
        description: 'User performed protected action',
        severity: AlertSeverity.MEDIUM,
        status: AlertStatus.FIRING,
        source: 'integration-test',
        labels: { userId, action: 'protected-action' },
        annotations: { timestamp: new Date().toISOString() },
        channels: ['email'],
        message: `User ${userId} performed protected action`,
      });

      return c.json({ 
        success: true, 
        alertId: alert.id,
        rateLimitRemaining: rateLimitResult.remaining 
      });
    });

    // Setup alert management endpoints
    app.get('/alerts', async (c) => {
      const alerts = alertingSystem.getAlerts();
      return c.json({ alerts });
    });

    app.post('/alerts/:alertId/acknowledge', async (c) => {
      const alertId = c.req.param('alertId');
      const success = alertingSystem.acknowledgeAlert(alertId);
      return c.json({ success });
    });

    app.post('/alerts/:alertId/resolve', async (c) => {
      const alertId = c.req.param('alertId');
      const success = alertingSystem.resolveAlert(alertId);
      return c.json({ success });
    });

    // Setup test data
    userId = 'test-user-123';
    sessionId = 'test-session-456';
    resetRateLimit(userId);
  });

  beforeEach(() => {
    // Clear alerts before each test
    const alerts = alertingSystem.getAlerts();
    for (const alert of alerts) {
      alertingSystem.resolveAlert(alert.id);
    }
    resetRateLimit(userId);
  });

  describe('CSRF + Rate Limiting + Alerting Integration', () => {
    it('should successfully process protected action with valid CSRF and within rate limits', async () => {
      // Get CSRF token
      const csrfResponse = await request(app.toString())
        .get('/csrf-token')
        .expect(200);

      const { csrfToken } = csrfResponse.body;
      expect(csrfToken).toBeDefined();

      // Perform protected action
      const response = await request(app.toString())
        .post('/protected-action')
        .set('Authorization', 'Bearer test-token')
        .set('x-csrf-token', csrfToken)
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.alertId).toBeDefined();
      expect(response.body.rateLimitRemaining).toBe(29); // 30 - 1

      // Verify alert was created
      const alertsResponse = await request(app.toString())
        .get('/alerts')
        .expect(200);

      expect(alertsResponse.body.alerts).toHaveLength(1);
      expect(alertsResponse.body.alerts[0].name).toBe('Protected Action Alert');
      expect(alertsResponse.body.alerts[0].labels.userId).toBe(userId);
    });

    it('should reject requests with invalid CSRF token', async () => {
      const response = await request(app.toString())
        .post('/protected-action')
        .set('Authorization', 'Bearer test-token')
        .set('x-csrf-token', 'invalid-token')
        .expect(403);

      expect(response.body.error).toBe('Invalid CSRF token');

      // No alert should be created
      const alertsResponse = await request(app.toString())
        .get('/alerts')
        .expect(200);

      expect(alertsResponse.body.alerts).toHaveLength(0);
    });

    it('should reject requests without CSRF token', async () => {
      const response = await request(app.toString())
        .post('/protected-action')
        .set('Authorization', 'Bearer test-token')
        .expect(403);

      expect(response.body.error).toBe('Invalid CSRF token');
    });

    it('should rate limit requests after threshold is exceeded', async () => {
      // Get CSRF token
      const csrfResponse = await request(app.toString())
        .get('/csrf-token')
        .expect(200);

      const { csrfToken } = csrfResponse.body;

      // Make requests up to the limit
      for (let i = 0; i < 30; i++) {
        await request(app.toString())
          .post('/protected-action')
