      const mockDatasets = platforms.map(platform => ({
        records: Array.from({ length: 1000 }, (_, i) => ({
          id: `${platform}-${i}`,
          name: `${platform} Record ${i}`
        }))
      }));

      const mockClient = {
        get: jest.fn().mockImplementation((url: string) => {
