      );

      // Step 4: Verify sanitization was logged
      expect(mockLogAudit).toHaveBeenCalledWith(
        expect.objectContaining({
          action: 'SENSITIVE_DATA_SANITIZED',
          resource: 'platform_data',
          status: 'success'
        })
      );
    });
  });
});

