      const batchData = [
        {
          organizationId: 'org-123',
          userId: 'user-1',
          action: 'action.1',
          resource: 'test',
          severity: 'info' as const,
          status: 'success' as const
        },
        {
          organizationId: 'org-123',
          userId: 'user-2',
          action: 'action.2',
          resource: 'test',
          severity: 'info' as const,
          status: 'success' as const
        }
      ];

      mockDb.execute.mockResolvedValue({});

      const result = await auditService.createBatchAuditLogs(batchData);

