import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { CircuitBreaker, CircuitBreakerOpenError, circuitBreakerRegistry } from '../circuit-breaker';

describe('CircuitBreaker', () => {
  let circuitBreaker: CircuitBreaker;
  let mockService: jest.MockedFunction<() => Promise<string>>;

  beforeEach(() => {
    mockService = jest.fn();
    circuitBreaker = new CircuitBreaker('test-service', {
      failureThreshold: 3,
      recoveryTimeout: 1000,
      operationTimeout: 500,
    });
  });

  afterEach(() => {
    circuitBreakerRegistry.reset('test-service');
    jest.clearAllMocks();
  });

  describe('Basic Functionality', () => {
    it('should execute operation successfully', async () => {
      mockService.mockResolvedValue('success');

      const result = await circuitBreaker.execute(mockService);

      expect(result).toBe('success');
      expect(mockService).toHaveBeenCalledTimes(1);
    });

    it('should handle operation failure', async () => {
      const error = new Error('Service error');
      mockService.mockRejectedValue(error);

      await expect(circuitBreaker.execute(mockService)).rejects.toThrow('Service error');
      expect(mockService).toHaveBeenCalledTimes(1);
    });

    it('should timeout operation if it takes too long', async () => {
      mockService.mockImplementation(() => new Promise(resolve => setTimeout(resolve, 1000)));

      await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      expect(mockService).toHaveBeenCalledTimes(1);
    });
  });

  describe('Circuit Breaking Logic', () => {
    it('should open circuit after failure threshold is reached', async () => {
      mockService.mockRejectedValue(new Error('Service error'));

      // Fail 3 times to reach threshold
      for (let i = 0; i < 3; i++) {
        await expect(circuitBreaker.execute(mockService)).rejects.toThrow('Service error');
      }

      // Circuit should now be open
      expect(circuitBreaker.getState()).toBe('open');
    });

    it('should reject immediately when circuit is open', async () => {
      // Open the circuit
      mockService.mockRejectedValue(new Error('Service error'));
      for (let i = 0; i < 3; i++) {
        await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      }

      // Should reject immediately without calling service
      await expect(circuitBreaker.execute(mockService)).rejects.toThrow(CircuitBreakerOpenError);
      expect(mockService).toHaveBeenCalledTimes(3); // Not called when circuit is open
    });

    it('should transition to half-open after recovery timeout', async () => {
      // Open the circuit
      mockService.mockRejectedValue(new Error('Service error'));
      for (let i = 0; i < 3; i++) {
        await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      }

      expect(circuitBreaker.getState()).toBe('open');

      // Wait for recovery timeout
      await new Promise(resolve => setTimeout(resolve, 1100));

      // Should be in half-open state now
      expect(circuitBreaker.getState()).toBe('half-open');
    });

    it('should close circuit on successful operation in half-open state', async () => {
      // Open the circuit
      mockService.mockRejectedValue(new Error('Service error'));
      for (let i = 0; i < 3; i++) {
        await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      }

      // Wait for recovery timeout
      await new Promise(resolve => setTimeout(resolve, 1100));

      // Successful operation should close circuit
      mockService.mockResolvedValue('success');
      const result = await circuitBreaker.execute(mockService);

      expect(result).toBe('success');
      expect(circuitBreaker.getState()).toBe('closed');
    });

    it('should reopen circuit on failure in half-open state', async () => {
      // Open the circuit
      mockService.mockRejectedValue(new Error('Service error'));
      for (let i = 0; i < 3; i++) {
        await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      }

      // Wait for recovery timeout
      await new Promise(resolve => setTimeout(resolve, 1100));

      // Failure in half-open should reopen circuit
      await expect(circuitBreaker.execute(mockService)).rejects.toThrow();
      expect(circuitBreaker.getState()).toBe('open');
    });
  });

  describe('Metrics and Monitoring', () => {
    it('should track operation metrics', async () => {
      mockService.mockResolvedValue('success');

      await circuitBreaker.execute(mockService);

      const metrics = circuitBreaker.getMetrics();
      expect(metrics.totalOperations).toBe(1);
      expect(metrics.successfulOperations).toBe(1);
      expect(metrics.failedOperations).toBe(0);
      expect(metrics.successRate).toBe(100);
    });

    it('should track failure metrics', async () => {
      mockService.mockRejectedValue(new Error('Service error'));

      await expect(circuitBreaker.execute(mockService)).rejects.toThrow();

      const metrics = circuitBreaker.getMetrics();
      expect(metrics.totalOperations).toBe(1);
      expect(metrics.successfulOperations).toBe(0);
      expect(metrics.failedOperations).toBe(1);
      expect(metrics.successRate).toBe(0);
    });

    it('should calculate success rate correctly', async () => {
      // 2 successes, 1 failure
      mockService.mockResolvedValue('success');
      await circuitBreaker.execute(mockService);
      await circuitBreaker.execute(mockService);

      mockService.mockRejectedValue(new Error('Service error'));
      await expect(circuitBreaker.execute(mockService)).rejects.toThrow();

      const metrics = circuitBreaker.getMetrics();
      expect(metrics.successRate).toBe(66.67); // 2/3 * 100
    });
  });

  describe('Registry Management', () => {
    it('should register circuit breaker in registry', () => {
      const cb = new CircuitBreaker('registry-test');
      const registered = circuitBreakerRegistry.get('registry-test');

      expect(registered).toBe(cb);
    });

    it('should get all metrics from registry', () => {
      const cb1 = new CircuitBreaker('service-1');
      const cb2 = new CircuitBreaker('service-2');

      const allMetrics = circuitBreakerRegistry.getAllMetrics();

      expect(allMetrics).toHaveProperty('service-1');
      expect(allMetrics).toHaveProperty('service-2');
    });

    it('should reset circuit breaker', () => {
      const cb = new CircuitBreaker('reset-test');

      // Simulate some operations
      cb.getMetrics();

      circuitBreakerRegistry.reset('reset-test');

      const metrics = cb.getMetrics();
      expect(metrics.totalOperations).toBe(0);
    });
  });

  describe('Decorator Support', () => {
    it('should support decorator pattern', () => {
      class TestService {
        @CircuitBreaker.decorate('decorator-test', {
          failureThreshold: 2,
          recoveryTimeout: 500,
        })
        async testMethod(): Promise<string> {
          return 'decorated-success';
        }
      }

      const service = new TestService();
      expect(service.testMethod).toBeDefined();
    });
  });

  describe('Edge Cases', () => {
    it('should handle concurrent operations', async () => {
      mockService.mockResolvedValue('success');

      // Execute multiple operations concurrently
      const promises = Array(10).fill(null).map(() => circuitBreaker.execute(mockService));
      const results = await Promise.all(promises);

      expect(results).toHaveLength(10);
      expect(results.every(result => result === 'success')).toBe(true);
      expect(mockService).toHaveBeenCalledTimes(10);
    });

    it('should handle zero failure threshold', () => {
      expect(() => {
        new CircuitBreaker('zero-threshold', { failureThreshold: 0 });
      }).toThrow();
    });

    it('should handle negative recovery timeout', () => {
      expect(() => {
        new CircuitBreaker('negative-timeout', { recoveryTimeout: -1 });
      }).toThrow();
    });
  });
});

import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { RateLimiter, RateLimitExceededError } from '../rate-limiter';

describe('RateLimiter', () => {
  let rateLimiter: RateLimiter;
  let mockStore: Map<string, { count: number; resetTime: number }>;

  beforeEach(() => {
    mockStore = new Map();
    rateLimiter = new RateLimiter({
      windowMs: 60000, // 1 minute
      maxRequests: 10,
      store: mockStore as any,
    });
  });

  afterEach(() => {
    jest.clearAllMocks();
    mockStore.clear();
  });

  describe('Basic Rate Limiting', () => {
    it('should allow requests within limit', async () => {
      const identifier = 'user123';

      for (let i = 0; i < 5; i++) {
        const result = await rateLimiter.checkLimit(identifier);
        expect(result.allowed).toBe(true);
        expect(result.remaining).toBe(10 - i - 1);
        expect(result.resetTime).toBeGreaterThan(Date.now());
      }
    });

    it('should block requests exceeding limit', async () => {
      const identifier = 'user123';

      // Use up all allowed requests
      for (let i = 0; i < 10; i++) {
        await rateLimiter.checkLimit(identifier);
      }

      // Next request should be blocked
      const result = await rateLimiter.checkLimit(identifier);
      expect(result.allowed).toBe(false);
      expect(result.remaining).toBe(0);
      expect(result.resetTime).toBeGreaterThan(Date.now());
    });

    it('should reset after window expires', async () => {
      const identifier = 'user123';

      // Use up all requests
      for (let i = 0; i < 10; i++) {
        await rateLimiter.checkLimit(identifier);
      }

      // Should be blocked
      let result = await rateLimiter.checkLimit(identifier);
      expect(result.allowed).toBe(false);

      // Mock time passing (window expired)
      const pastTime = Date.now() + 61000; // 61 seconds later
      jest.spyOn(Date, 'now').mockReturnValue(pastTime);

      // Should be allowed again
      result = await rateLimiter.checkLimit(identifier);
      expect(result.allowed).toBe(true);
      expect(result.remaining).toBe(9);

      // Restore Date.now
      jest.restoreAllMocks();
    });

    it('should handle different identifiers separately', async () => {
      const user1 = 'user1';
      const user2 = 'user2';

      // User1 uses up all requests
      for (let i = 0; i < 10; i++) {
        await rateLimiter.checkLimit(user1);
      }

      // User1 should be blocked
      const result1 = await rateLimiter.checkLimit(user1);
      expect(result1.allowed).toBe(false);

      // User2 should still be allowed
      const result2 = await rateLimiter.checkLimit(user2);
      expect(result2.allowed).toBe(true);
      expect(result2.remaining).toBe(9);
    });
  });

  describe('Custom Configuration', () => {
    it('should use custom window and limit', async () => {
      const customLimiter = new RateLimiter({
        windowMs: 30000, // 30 seconds
        maxRequests: 5,
        store: mockStore as any,
      });

      const identifier = 'user123';

      // Should allow 5 requests
      for (let i = 0; i < 5; i++) {
        const result = await customLimiter.checkLimit(identifier);
        expect(result.allowed).toBe(true);
        expect(result.remaining).toBe(5 - i - 1);
      }

      // 6th request should be blocked
      const result = await customLimiter.checkLimit(identifier);
      expect(result.allowed).toBe(false);
    });

    it('should handle skipSuccessfulRequests option', async () => {
      const customLimiter = new RateLimiter({
        windowMs: 60000,
        maxRequests: 10,
        skipSuccessfulRequests: true,
        store: mockStore as any,
      });

      const identifier = 'user123';

      // Should not count successful requests
      for (let i = 0; i < 15; i++) {
        const result = await customLimiter.checkLimit(identifier, { success: true });
        expect(result.allowed).toBe(true);
        expect(result.remaining).toBe(9); // Always 9 remaining
      }
    });

    it('should handle skipFailedRequests option', async () => {
      const customLimiter = new RateLimiter({
        windowMs: 60000,
        maxRequests: 10,
        skipFailedRequests: true,
        store: mockStore as any,
      });

      const identifier = 'user123';

      // Should not count failed requests
      for (let i = 0; i < 15; i++) {
        const result = await customLimiter.checkLimit(identifier, { success: false });
        expect(result.allowed).toBe(true);
        expect(result.remaining).toBe(9); // Always 9 remaining
      }
    });
  });

  describe('Store Operations', () => {
    it('should increment counter correctly', async () => {
      const identifier = 'user123';

      await rateLimiter.checkLimit(identifier);
      const storeData = mockStore.get(identifier);

      expect(storeData).toBeDefined();
      expect(storeData!.count).toBe(1);
      expect(storeData!.resetTime).toBeGreaterThan(Date.now());
    });

    it('should update existing counter', async () => {
      const identifier = 'user123';

      await rateLimiter.checkLimit(identifier);
      await rateLimiter.checkLimit(identifier);

      const storeData = mockStore.get(identifier);
      expect(storeData!.count).toBe(2);
    });

    it('should clean up expired entries', async () => {
      const identifier = 'user123';

      // Add an expired entry
      const pastTime = Date.now() - 61000; // 61 seconds ago
      mockStore.set(identifier, {
        count: 5,
        resetTime: pastTime,
      });

      // Should reset the counter
      const result = await rateLimiter.checkLimit(identifier);
      expect(result.allowed).toBe(true);
      expect(result.remaining).toBe(9);

      const storeData = mockStore.get(identifier);
      expect(storeData!.count).toBe(1);
      expect(storeData!.resetTime).toBeGreaterThan(Date.now());
    });
  });

  describe('Error Handling', () => {
    it('should handle store errors gracefully', async () => {
      const errorStore = {
        get: jest.fn().mockRejectedValue(new Error('Store error')),
        set: jest.fn().mockRejectedValue(new Error('Store error')),
      };

      const errorLimiter = new RateLimiter({
        windowMs: 60000,
        maxRequests: 10,
        store: errorStore as any,
      });

      // Should allow requests when store fails (fail-open)
      const result = await errorLimiter.checkLimit('user123');
      expect(result.allowed).toBe(true);
    });

    it('should handle invalid identifiers', async () => {
      const result = await rateLimiter.checkLimit('');
      expect(result.allowed).toBe(true);
    });

    it('should handle null/undefined identifiers', async () => {
      const result1 = await rateLimiter.checkLimit(null as any);
      const result2 = await rateLimiter.checkLimit(undefined as any);

      expect(result1.allowed).toBe(true);
      expect(result2.allowed).toBe(true);
    });
  });

  describe('RateLimitExceededError', () => {
    it('should create error with correct properties', () => {
      const error = new RateLimitExceededError('Rate limit exceeded', {
        limit: 10,
        remaining: 0,
        resetTime: Date.now() + 60000,
        retryAfter: 60,
      });

      expect(error.message).toBe('Rate limit exceeded');
      expect(error.limit).toBe(10);
      expect(error.remaining).toBe(0);
      expect(error.resetTime).toBeGreaterThan(Date.now());
      expect(error.retryAfter).toBe(60);
    });

    it('should be instance of Error', () => {
      const error = new RateLimitExceededError('Rate limit exceeded');

      expect(error).toBeInstanceOf(Error);
      expect(error).toBeInstanceOf(RateLimitExceededError);
    });
  });

  describe('Middleware Integration', () => {
    it('should work as middleware function', async () => {
      const mockNext = jest.fn();
      const mockReq = { ip: '192.168.1.1' };
      const mockRes = { locals: {} };

      // Create a rate limiter that works as middleware
      const middlewareLimiter = new RateLimiter({
        windowMs: 60000,
        maxRequests: 5,
        keyGenerator: (req) => req.ip,
        store: mockStore as any,
      });

      // Should allow first few requests
      for (let i = 0; i < 5; i++) {
        await middlewareLimiter.middleware(mockReq as any, mockRes as any, mockNext);
        expect(mockNext).toHaveBeenCalledTimes(i + 1);
      }

      // Should block next request
      await expect(
        middlewareLimiter.middleware(mockReq as any, mockRes as any, mockNext)
      ).rejects.toThrow(RateLimitExceededError);
    });
  });

  describe('Performance', () => {
    it('should handle high request volume efficiently', async () => {
      const startTime = Date.now();
      const requests = 1000;

      for (let i = 0; i < requests; i++) {
        await rateLimiter.checkLimit(`user${i % 100}`); // 100 different users
      }

      const endTime = Date.now();
      const duration = endTime - startTime;

      // Should handle 1000 requests quickly (less than 1 second)
      expect(duration).toBeLessThan(1000);
    });

    it('should handle concurrent requests', async () => {
      const identifier = 'concurrent-user';
      const promises = Array(20).fill(null).map(() => 
        rateLimiter.checkLimit(identifier)
      );

      const results = await Promise.all(promises);

      // First 10 should be allowed, next 10 should be blocked
      const allowedCount = results.filter(r => r.allowed).length;
      const blockedCount = results.filter(r => !r.allowed).length;

      expect(allowedCount).toBe(10);
      expect(blockedCount).toBe(10);
    });
  });

  describe('Memory Management', () => {
    it('should not leak memory', async () => {
      const initialSize = mockStore.size;

      // Create many different identifiers
      for (let i = 0; i < 100; i++) {
        await rateLimiter.checkLimit(`user${i}`);
      }

      expect(mockStore.size).toBe(initialSize + 100);

      // Clean up expired entries
      const pastTime = Date.now() - 61000;
      jest.spyOn(Date, 'now').mockReturnValue(pastTime);

      // Trigger cleanup by making a request
      await rateLimiter.checkLimit('new-user');

      jest.restoreAllMocks();

      // Store should be cleaned up (implementation dependent)
      expect(mockStore.size).toBeGreaterThanOrEqual(1);
    });
  });
});

