const REQUIRED_VARS = [
  'JWT_SECRET',
  'JWT_REFRESH_SECRET',
  'ENCRYPTION_KEY',
  'DATABASE_URL',
  'PORT',
  'NODE_ENV',
  'ALLOWED_ORIGINS',
] as const;

const REQUIRED_IN_PRODUCTION = [
  'INTERNAL_API_SECRET',
  'PLATFORM_WEBHOOK_SECRET',
  'FIELD_ENCRYPTION_KEY',
] as const;

const OPTIONAL_VARS = [
  'RABBITMQ_URL',
  'REDIS_URL',
  'OPENAI_API_KEY',
  'ANTHROPIC_API_KEY',
  'ELEVEN_LABS_API_KEY',
  'GOOGLE_GEMINI_API_KEY',
  'GROQ_API_KEY',
  'COHERE_API_KEY',
