/**
 * OpenTelemetry Configuration
 * Distributed tracing with Jaeger backend
 */

import { NodeSDK } from '@opentelemetry/sdk-node';
import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { OTLPTraceExporter } from '@opentelemetry/exporter-otlp-grpc';
import { SimpleSpanProcessor, BatchSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { trace, SpanStatusCode, SpanKind } from '@opentelemetry/api';
import { logger } from './production-logger';

// Configuration from environment
const config = {
  serviceName: process.env.OTEL_SERVICE_NAME || 'kaytx-backend',
  environment: process.env.NODE_ENV || 'development',
  jaegerEndpoint: process.env.JAEGER_ENDPOINT || 'http://localhost:14268/api/traces',
  otlpEndpoint: process.env.OTEL_EXPORTER_OTLP_ENDPOINT || 'http://localhost:4317',
  enableTracing: process.env.OTEL_ENABLE_TRACING !== 'false',
  samplingProbability: parseFloat(process.env.OTEL_SAMPLING_PROBABILITY || '1.0'),
};

/**
 * Initialize OpenTelemetry SDK
 */
export function initializeOpenTelemetry(): NodeSDK {
  if (!config.enableTracing) {
    logger.info('[OpenTelemetry] Tracing disabled');
    return new NodeSDK();
  }

  // Create resource with service information
  const resource = new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: config.serviceName,
    [SemanticResourceAttributes.SERVICE_VERSION]: process.env.DEPLOYMENT_VERSION || '1.0.0',
    [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: config.environment,
    [SemanticResourceAttributes.PROCESS_PID]: process.pid,
    [SemanticResourceAttributes.HOST_NAME]: require('os').hostname(),
  });

  // Configure exporters
  const exporters = [];

  // Jaeger exporter (primary)
  const jaegerExporter = new JaegerExporter({
    endpoint: config.jaegerEndpoint,
    headers: {},
  });

  // OTLP exporter (for collectors like Tempo, etc.)
  const otlpExporter = new OTLPTraceExporter({
    url: config.otlpEndpoint,
  });

  exporters.push(jaegerExporter);
  exporters.push(otlpExporter);

  // Initialize SDK
  const sdk = new NodeSDK({
    resource,
    instrumentations: [getNodeAutoInstrumentations()],
    traceExporter: jaegerExporter, // Primary exporter
    spanProcessors: [
      new BatchSpanProcessor(jaegerExporter, {
        maxExportBatchSize: 512,
        scheduledDelayMillis: 5000,
        exportTimeoutMillis: 30000,
      }),
      new SimpleSpanProcessor(otlpExporter), // Secondary exporter
    ],
    sampler: {
      // Sample based on probability
      shouldSample: (context, traceId, spanName, spanKind, attributes) => {
        return Math.random() < config.samplingProbability;
      },
    },
  });

  // Initialize the SDK
  sdk.start();

  logger.info('[OpenTelemetry] Initialized with config', {
    serviceName: config.serviceName,
    environment: config.environment,
    jaegerEndpoint: config.jaegerEndpoint,
    samplingProbability: config.samplingProbability,
  });

  return sdk;
}

/**
 * Create a custom span with attributes
 */
export function createSpan(name: string, kind: SpanKind = SpanKind.INTERNAL) {
  const tracer = trace.getTracer(config.serviceName);
  return tracer.startSpan(name, { kind });
}

/**
 * Wrap a function with tracing
 */
export function withTracing<T extends (...args: any[]) => Promise<any> | any>(
  name: string,
  fn: T,
  options?: {
    kind?: SpanKind;
    attributes?: Record<string, string | number | boolean>;
    onError?: (error: Error, span: any) => void;
  }
): T {
  return (async (...args: Parameters<T>) => {
    const span = createSpan(name, options?.kind);
    
    // Add attributes
    if (options?.attributes) {
      Object.entries(options.attributes).forEach(([key, value]) => {
        span.setAttribute(key, value);
      });
    }

    try {
      const result = await fn(...args);
      span.setStatus({ code: SpanStatusCode.OK });
      return result;
    } catch (error) {
      span.recordException(error as Error);
      span.setStatus({ 
        code: SpanStatusCode.ERROR, 
        message: error instanceof Error ? error.message : String(error) 
      });
      
      if (options?.onError) {
        options.onError(error as Error, span);
      }
      
      throw error;
    } finally {
      span.end();
    }
  }) as T;
}

/**
 * Add custom attributes to current span
 */
export function addSpanAttributes(attributes: Record<string, string | number | boolean>) {
  const span = trace.getActiveSpan();
  if (span) {
    Object.entries(attributes).forEach(([key, value]) => {
      span.setAttribute(key, value);
    });
  }
}

/**
 * Add event to current span
 */
export function addSpanEvent(name: string, attributes?: Record<string, string | number | boolean>) {
  const span = trace.getActiveSpan();
  if (span) {
    span.addEvent(name, attributes);
  }
}

/**
 * Set span status
 */
export function setSpanStatus(code: SpanStatusCode, message?: string) {
  const span = trace.getActiveSpan();
  if (span) {
    span.setStatus({ code, message });
  }
}

/**
 * Get current trace context
 */
export function getTraceContext() {
  const span = trace.getActiveSpan();
  if (!span) {
    return null;
  }

  const spanContext = span.spanContext();
  return {
    traceId: spanContext.traceId,
    spanId: spanContext.spanId,
    traceFlags: spanContext.traceFlags,
  };
}

/**
 * Inject trace context into headers
 */
export function injectTraceContext(headers: Record<string, string> = {}) {
  const tracer = trace.getTracer(config.serviceName);
  const span = trace.getActiveSpan();
  
  if (span) {
    tracer.inject(
      trace.setSpanContext(trace.active(), span.spanContext()),
      'http_headers',
      headers
    );
  }
  
  return headers;
}

/**
 * Extract trace context from headers
 */
export function extractTraceContext(headers: Record<string, string>) {
  const tracer = trace.getTracer(config.serviceName);
  return tracer.extract('http_headers', headers);
}

/**
 * Middleware for Hono to add tracing
 */
export function createTracingMiddleware() {
  return async (c: any, next: any) => {
    const tracer = trace.getTracer(config.serviceName);
    const span = tracer.startSpan(`${c.req.method} ${c.req.path}`, {
      kind: SpanKind.SERVER,
      attributes: {
        'http.method': c.req.method,
        'http.target': c.req.path,
        'http.url': c.req.url,
        'http.host': c.req.header('host'),
        'user_agent.original': c.req.header('user-agent'),
        'http.scheme': c.req.url.startsWith('https') ? 'https' : 'http',
      },
    });

    try {
      // Extract trace context from incoming headers
      const extractedContext = extractTraceContext(c.req.header());
      if (extractedContext) {
        trace.setActiveSpan(extractedContext);
      }

      await next();

      // Add response attributes
      span.setAttribute('http.status_code', c.res.status);
      
      if (c.res.status >= 400) {
        span.setStatus({ 
          code: SpanStatusCode.ERROR, 
          message: `HTTP ${c.res.status}` 
        });
      } else {
        span.setStatus({ code: SpanStatusCode.OK });
      }
    } catch (error) {
      span.recordException(error as Error);
      span.setStatus({ 
        code: SpanStatusCode.ERROR, 
        message: error instanceof Error ? error.message : String(error) 
      });
      throw error;
    } finally {
      span.end();
    }
  };
}

/**
 * Database operation tracing helper
 */
export function traceDatabaseOperation<T>(
  operation: string,
  table: string,
  fn: () => Promise<T>
): Promise<T> {
  return withTracing(`db.${operation}`, fn, {
    kind: SpanKind.CLIENT,
    attributes: {
      'db.operation': operation,
      'db.table': table,
      'db.system': 'postgresql',
    },
  })();
}

/**
 * External API call tracing helper
 */
export function traceExternalCall<T>(
  service: string,
  operation: string,
  fn: () => Promise<T>
): Promise<T> {
  return withTracing(`external.${service}.${operation}`, fn, {
    kind: SpanKind.CLIENT,
    attributes: {
      'external.service': service,
      'external.operation': operation,
    },
  })();
}

/**
 * AI service call tracing helper
 */
export function traceAICall<T>(
  provider: string,
  model: string,
  operation: string,
  fn: () => Promise<T>
): Promise<T> {
  return withTracing(`ai.${provider}.${operation}`, fn, {
    kind: SpanKind.CLIENT,
    attributes: {
      'ai.provider': provider,
      'ai.model': model,
      'ai.operation': operation,
    },
    onError: (error, span) => {
      span.setAttribute('ai.error.type', error.constructor.name);
      span.setAttribute('ai.error.message', error.message);
    },
  })();
}

export default {
  initializeOpenTelemetry,
  createSpan,
  withTracing,
  addSpanAttributes,
  addSpanEvent,
  setSpanStatus,
  getTraceContext,
  injectTraceContext,
  extractTraceContext,
  createTracingMiddleware,
  traceDatabaseOperation,
  traceExternalCall,
  traceAICall,
};

/**
 * Production Logger Utility
 * Replaces console.log statements with structured logging for production
 * Supports multiple log levels and destinations
 */

export enum LogLevel {
  DEBUG = 'debug',
  INFO = 'info',
  WARN = 'warn',
  ERROR = 'error',
}

export interface LogEntry {
  timestamp: string;
  level: LogLevel;
  message: string;
  service?: string;
  context?: Record<string, unknown>;
  error?: Error;
}

export type LogHandler = (entry: LogEntry) => void;

export class ProductionLogger {
  private static instance: ProductionLogger;
  private handlers: LogHandler[] = [];
  private minLevel: LogLevel = LogLevel.INFO;
  private serviceName: string = 'kaytx';

  private constructor() {
    // Add default console handler (will be filtered by level)
    this.addHandler((entry) => {
      const prefix = `[${entry.timestamp}] [${entry.level.toUpperCase()}]`;
      const service = entry.service ? `[${entry.service}]` : '';
      const context = entry.context ? ` ${JSON.stringify(entry.context)}` : '';
      
      switch (entry.level) {
        case LogLevel.DEBUG:
          console.debug(`${prefix}${service} ${entry.message}${context}`);
          break;
        case LogLevel.INFO:
          console.info(`${prefix}${service} ${entry.message}${context}`);
          break;
        case LogLevel.WARN:
          console.warn(`${prefix}${service} ${entry.message}${context}`);
          break;
        case LogLevel.ERROR:
          console.error(`${prefix}${service} ${entry.message}${context}`, entry.error || '');
          break;
      }
    });

    // In production, add remote logging handler here
    if (process.env.NODE_ENV === 'production') {
      const logExportEndpoint = process.env.LOG_EXPORT_ENDPOINT;
      const logExportApiKey = process.env.LOG_EXPORT_API_KEY;

      if (logExportEndpoint && logExportApiKey) {
        this.addHandler((entry) => {
          const axios = require('axios');
          axios.post(logExportEndpoint, entry, {
            headers: { 'X-API-Key': logExportApiKey }
          }).catch((err: any) => console.error('Remote logging failed:', err.message));
        });
      }
    }
  }

  static getInstance(): ProductionLogger {
    if (!ProductionLogger.instance) {
      ProductionLogger.instance = new ProductionLogger();
    }
    return ProductionLogger.instance;
  }

  setServiceName(name: string): void {
    this.serviceName = name;
  }

  setMinLevel(level: LogLevel): void {
    this.minLevel = level;
  }

  addHandler(handler: LogHandler): void {
    this.handlers.push(handler);
  }

  private shouldLog(level: LogLevel): boolean {
    const levels = [LogLevel.DEBUG, LogLevel.INFO, LogLevel.WARN, LogLevel.ERROR];
    return levels.indexOf(level) >= levels.indexOf(this.minLevel);
  }

  private formatMessage(message: string, service?: string): string {
    return service ? `${message} [${service}]` : message;
  }

  private createEntry(
    level: LogLevel,
    message: string,
    context?: Record<string, unknown>,
    error?: Error
  ): LogEntry {
    return {
      timestamp: new Date().toISOString(),
      level,
      message: this.formatMessage(message),
      service: this.serviceName,
      context,
      error,
    };
  }

  debug(message: string, context?: Record<string, unknown>): void {
    if (this.shouldLog(LogLevel.DEBUG)) {
      const entry = this.createEntry(LogLevel.DEBUG, message, context);
      this.handlers.forEach(h => h(entry));
    }
  }

  info(message: string, context?: Record<string, unknown>): void {
    if (this.shouldLog(LogLevel.INFO)) {
      const entry = this.createEntry(LogLevel.INFO, message, context);
      this.handlers.forEach(h => h(entry));
    }
  }

  warn(message: string, context?: Record<string, unknown>): void {
    if (this.shouldLog(LogLevel.WARN)) {
      const entry = this.createEntry(LogLevel.WARN, message, context);
      this.handlers.forEach(h => h(entry));
    }
  }

  error(message: string, error?: Error, context?: Record<string, unknown>): void {
    if (this.shouldLog(LogLevel.ERROR)) {
      const entry = this.createEntry(LogLevel.ERROR, message, context, error);
      this.handlers.forEach(h => h(entry));
    }
  }

  // Convenience method for service-specific logging
  service(serviceName: string): ProductionLogger {
    const logger = ProductionLogger.getInstance();
    const originalService = this.serviceName;
    this.serviceName = serviceName;
    
    // Return a proxy that resets the service name
    const serviceLogger = {
      debug: (message: string, context?: Record<string, unknown>) => {
        logger.debug(message, { ...context, service: serviceName });
      },
      info: (message: string, context?: Record<string, unknown>) => {
        logger.info(message, { ...context, service: serviceName });
      },
      warn: (message: string, context?: Record<string, unknown>) => {
        logger.warn(message, { ...context, service: serviceName });
      },
      error: (message: string, error?: Error, context?: Record<string, unknown>) => {
        logger.error(message, error, { ...context, service: serviceName });
      },
    };
    
    return serviceLogger as unknown as ProductionLogger;
  }
}

// Export singleton instance
export const logger = ProductionLogger.getInstance();

// Export class for creating service-specific loggers
export function createLogger(serviceName: string): ProductionLogger {
  const logger = ProductionLogger.getInstance();
  logger.setServiceName(serviceName);
  return logger;
}

// Helper to safely replace console.log in existing code
export function replaceConsoleLog(
  serviceName: string,
  level: LogLevel = LogLevel.INFO
): void {
  const logger = createLogger(serviceName);
  console.log = (message: string, ...args: unknown[]) => {
    if (args.length > 0) {
      logger.info(message, { args });
    } else {
      logger.info(message);
    }
  };
  console.debug = (message: string, ...args: unknown[]) => {
    if (args.length > 0) {
      logger.debug(message, { args });
    } else {
      logger.debug(message);
    }
  };
  console.info = (message: string, ...args: unknown[]) => {
    if (args.length > 0) {
      logger.info(message, { args });
    } else {
      logger.info(message);
    }
  };
  console.warn = (message: string, ...args: unknown[]) => {
    if (args.length > 0) {
      logger.warn(message, { args });
    } else {
      logger.warn(message);
    }
  };
  console.error = (message: string, ...args: unknown[]) => {
    if (args.length > 0) {
      logger.error(message, args[0] as Error, { args: args.slice(1) });
    } else {
      logger.error(message);
    }
  };
}

