        details: {
          homeserver: this.matrixConfig.homeserver,
          userId: this.matrixConfig.userId,
          deviceId: this.matrixConfig.deviceId,
          rooms: this.rooms.size,
        },
      };

      this.setState(state);
      this.emitEvent({ type: 'connected', data: state, timestamp: Date.now() });

      return state;
    } catch (error) {
      const errorState: BridgeConnectionState = {
        status: 'error',
        error: error instanceof Error ? error.message : 'Connection failed',
      };
      this.setState(errorState);
      throw error;
    }
  }

  async disconnect(): Promise<BridgeConnectionState> {
    console.log(`[MatrixBridge:${this.config.id}] Disconnecting`);

    this.syncRunning = false;
    this.syncToken = null;
    this.rooms.clear();

    await this.logout();

    const state: BridgeConnectionState = { status: 'disconnected' };
    this.setState(state);
    this.emitEvent({ type: 'disconnected', data: state, timestamp: Date.now() });

    return state;
  }

  async sendMessage(message: BridgeMessage): Promise<boolean> {
    if (this.state.status !== 'connected') {
      console.warn(`[MatrixBridge:${this.config.id}] Not connected`);
      return false;
    }

    try {
      console.log(`[MatrixBridge:${this.config.id}] Sending message to room ${message.to}`);
      
      const eventId = `$${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      
      console.log(`[MatrixBridge:${this.config.id}] Message sent with event ID: ${eventId}`);
      return true;
    } catch (error) {
      console.error(`[MatrixBridge:${this.config.id}] Send error:`, error);
      this.emitEvent({ type: 'error', data: error, timestamp: Date.now() });
      return false;
    }
  }

  async receiveMessage(): Promise<BridgeMessage | null> {
    return new Promise((resolve) => {
      const timeout = setTimeout(() => resolve(null), 5000);

      this.once('message', (message: BridgeMessage) => {
        clearTimeout(timeout);
        resolve(message);
      });
    });
  }

  private async login(): Promise<void> {
    if (this.matrixConfig.accessToken) {
      console.log(`[MatrixBridge:${this.config.id}] Using existing access token`);
      return;
    }

    console.log(`[MatrixBridge:${this.config.id}] Logging in...`);
    
    this.matrixConfig.accessToken = `mock_token_${Date.now()}`;
    this.matrixConfig.userId = `@user:${this.matrixConfig.homeserver}`;
    this.matrixConfig.deviceId = `DEVICE_${Date.now()}`;
  }

  private async logout(): Promise<void> {
    if (!this.matrixConfig.accessToken) return;

    console.log(`[MatrixBridge:${this.config.id}] Logging out...`);
    
    this.matrixConfig.accessToken = undefined;
    this.matrixConfig.userId = undefined;
    this.matrixConfig.deviceId = undefined;
  }

  private async startSync(): Promise<void> {
    this.syncRunning = true;
    this.performSync();
  }

  private async performSync(): Promise<void> {
    if (!this.syncRunning || this.state.status !== 'connected') {
      return;
    }

    try {
      console.log(`[MatrixBridge:${this.config.id}] Syncing...`);
      
      const mockEvents = this.generateMockSyncEvents();
      this.processSyncEvents(mockEvents);

      this.syncToken = `s${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      setTimeout(() => this.performSync(), this.matrixConfig.syncTimeout || 30000);
    } catch (error) {
      console.error(`[MatrixBridge:${this.config.id}] Sync error:`, error);
      this.emitEvent({ type: 'error', data: error, timestamp: Date.now() });
      
      setTimeout(() => this.performSync(), 5000);
    }
  }

  private generateMockSyncEvents(): any[] {
    return [];
  }

  private processSyncEvents(events: any[]): void {
    for (const event of events) {
      if (event.type === 'm.room.message') {
        const message: BridgeMessage = {
          id: event.event_id,
          from: event.sender,
          to: event.room_id,
          type: event.content.msgtype || 'm.text',
          content: event.content.body,
          timestamp: event.origin_server_ts,
          metadata: {
            msgtype: event.content.msgtype,
            format: event.content.format,
          },
        };

        this.emitEvent({ type: 'message', data: message, timestamp: Date.now() });
        this.emit('message', message);
      }
    }
  }

  async joinRoom(roomId: string): Promise<void> {
    console.log(`[MatrixBridge:${this.config.id}] Joining room ${roomId}`);
    this.rooms.set(roomId, { id: roomId, joinedAt: Date.now() });
  }

  async leaveRoom(roomId: string): Promise<void> {
    console.log(`[MatrixBridge:${this.config.id}] Leaving room ${roomId}`);
    this.rooms.delete(roomId);
  }

  getRooms(): string[] {
    return Array.from(this.rooms.keys());
  }
}

/**
 * Kaytx MCP Client SDK
 * 
 * Client-side SDK for connecting to Kaytx MCP Server
 * Enables applications to interact with Kaytx AI agents via MCP
 */

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { SSEClientTransport } from '@modelcontextprotocol/sdk/client/sse.js';
import {
  ListToolsResult,
  CallToolResult,
  ListResourcesResult,
  ReadResourceResult,
} from '@modelcontextprotocol/sdk/types.js';

export interface KaytxMCPClientConfig {
  transport: 'stdio' | 'sse';
  // For stdio transport
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  // For SSE transport
  url?: string;
}

export interface AgentTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

export interface AgentResource {
  uri: string;
  name: string;
  description: string;
  mimeType: string;
}

export interface AgentExecutionOptions {
  streamResponse?: boolean;
  maxTokens?: number;
  temperature?: number;
  requireApproval?: boolean;
}

export interface AgentExecutionContext {
  userId?: string;
  organizationId?: string;
  sessionId?: string;
  previousMessages?: string[];
}

export interface AgentExecutionRequest {
  query: string;
  context?: AgentExecutionContext;
  options?: AgentExecutionOptions;
}

export interface AgentExecutionResponse {
  text: string;
  isError?: boolean;
}

/**
 * Kaytx MCP Client
 * 
 * Client for interacting with Kaytx AI agents via MCP protocol
 */
export class KaytxMCPClient {
  private client: Client;
  private transport: StdioClientTransport | SSEClientTransport | null = null;
  private config: KaytxMCPClientConfig;

  constructor(config: KaytxMCPClientConfig) {
    this.config = config;

    this.client = new Client(
      {
        name: 'kaytx-mcp-client',
        version: '2.0.0',
      },
      {
        capabilities: {},
      }
    );
  }

  /**
   * Connect to MCP server
   */
  async connect(): Promise<void> {
    if (this.config.transport === 'stdio') {
      this.transport = new StdioClientTransport({
        command: this.config.command || 'kaytx-mcp-server',
        args: this.config.args || [],
        env: this.config.env || {},
      });
    } else {
      this.transport = new SSEClientTransport(
        new URL(this.config.url || 'http://localhost:3001/sse')
      );
    }

    await this.client.connect(this.transport);
  }

  /**
   * Disconnect from MCP server
   */
  async disconnect(): Promise<void> {
    await this.client.close();
    this.transport = null;
  }

  /**
   * List all available agent tools
   */
  async listAgentTools(): Promise<AgentTool[]> {
    const result: ListToolsResult = await this.client.listTools();

    return result.tools.map((tool) => ({
      name: tool.name,
      description: tool.description || '',
      inputSchema: tool.inputSchema as Record<string, unknown>,
    }));
  }

  /**
   * Execute an agent tool
   */
  async executeAgent(
    agentName: string,
    request: AgentExecutionRequest
  ): Promise<AgentExecutionResponse> {
    const result: CallToolResult = await this.client.callTool({
      name: agentName,
      arguments: {
        query: request.query,
        context: request.context || {},
        options: request.options || {},
      },
    });

    const textContent = result.content.find((c) => c.type === 'text');

    return {
      text: textContent?.text || '',
      isError: result.isError,
    };
  }

  /**
   * List all available agent resources
   */
  async listAgentResources(): Promise<AgentResource[]> {
    const result: ListResourcesResult = await this.client.listResources();

    return result.resources.map((resource) => ({
      uri: resource.uri,
      name: resource.name,
      description: resource.description || '',
      mimeType: resource.mimeType || 'application/json',
    }));
  }

  /**
   * Get agent resource content
   */
  async getAgentResource(uri: string): Promise<string> {
    const result: ReadResourceResult = await this.client.readResource({
      uri,
    });

    const textContent = result.contents.find(
      (c): c is { uri: string; mimeType: string; text: string } => 
        'text' in c && typeof c.text === 'string'
    );

    return textContent?.text || '';
  }

  /**
   * Quick execute - list tools and execute in one call
   */
  async quickExecute(
    query: string,
    agentName?: string,
    options?: AgentExecutionOptions,
    context?: AgentExecutionContext
  ): Promise<AgentExecutionResponse> {
    // If agent name not specified, find best matching agent
    if (!agentName) {
      const tools = await this.listAgentTools();

      // Simple keyword matching - in production, use embeddings
      const keywords = query.toLowerCase().split(' ');
      const scored = tools.map((tool) => {
        const score = keywords.filter((kw) => 
          tool.name.includes(kw) || 
          tool.description.toLowerCase().includes(kw)
        ).length;
        return { tool, score };
      });

      scored.sort((a, b) => b.score - a.score);

      if (scored.length === 0 || scored[0].score === 0) {
        throw new Error('No matching agent found for query');
      }

      agentName = scored[0].tool.name;
    }

    return this.executeAgent(agentName, {
      query,
      options,
      context,
    });
  }
}

export default KaytxMCPClient;

/**
 * MCP Integration React Hook
 * 
 * Hook for integrating kaytx MCP Server with React applications
 * Enables direct agent interaction from frontend components
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { KaytxMCPClient, AgentTool, AgentExecutionResponse } from './client-sdk';

export interface UseMCPAgentsOptions {
  transport: 'stdio' | 'sse';
  url?: string;
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  autoConnect?: boolean;
}

export interface UseMCPAgentsReturn {
  // Connection state
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;

  // Agent tools
  agentTools: AgentTool[];
  isLoadingTools: boolean;

  // Actions
  connect: () => Promise<void>;
  disconnect: () => Promise<void>;
  refreshTools: () => Promise<void>;
  executeAgent: (
    agentName: string,
    query: string,
    options?: {
      streamResponse?: boolean;
      maxTokens?: number;
      temperature?: number;
      context?: {
        userId?: string;
        organizationId?: string;
        sessionId?: string;
      };
    }
  ) => Promise<AgentExecutionResponse>;
  quickExecute: (
    query: string,
    options?: {
      agentName?: string;
      maxTokens?: number;
      temperature?: number;
      context?: {
        userId?: string;
        organizationId?: string;
        sessionId?: string;
      };
    }
  ) => Promise<AgentExecutionResponse>;
}

/**
 * React hook for kaytx MCP integration
 */
export function useMCPAgents(options: UseMCPAgentsOptions): UseMCPAgentsReturn {
  const clientRef = useRef<KaytxMCPClient | null>(null);

  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [agentTools, setAgentTools] = useState<AgentTool[]>([]);
  const [isLoadingTools, setIsLoadingTools] = useState(false);

  // Initialize client
  useEffect(() => {
    clientRef.current = new KaytxMCPClient({
      transport: options.transport,
      url: options.url,
      command: options.command,
      args: options.args,
      env: options.env,
    });

    return () => {
      if (clientRef.current) {
        clientRef.current.disconnect().catch(console.error);
      }
    };
  }, [options.transport, options.url, options.command]);

  // Auto-connect if enabled
  useEffect(() => {
    if (options.autoConnect && !isConnected && !isConnecting) {
      connect();
    }
  }, [options.autoConnect]);

  const connect = useCallback(async () => {
    if (!clientRef.current) return;

    setIsConnecting(true);
    setError(null);

    try {
      await clientRef.current.connect();
      setIsConnected(true);

      // Load available tools
      await refreshTools();
    } catch (err) {
      setError((err as Error).message);
      setIsConnected(false);
    } finally {
      setIsConnecting(false);
    }
  }, []);

  const disconnect = useCallback(async () => {
    if (!clientRef.current) return;

    try {
      await clientRef.current.disconnect();
      setIsConnected(false);
      setAgentTools([]);
    } catch (err) {
      setError((err as Error).message);
    }
  }, []);

  const refreshTools = useCallback(async () => {
    if (!clientRef.current || !isConnected) return;

    setIsLoadingTools(true);

    try {
      const tools = await clientRef.current.listAgentTools();
      setAgentTools(tools);
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setIsLoadingTools(false);
    }
  }, [isConnected]);

  const executeAgent = useCallback(async (
    agentName: string,
    query: string,
    options?: {
      streamResponse?: boolean;
      maxTokens?: number;
      temperature?: number;
      context?: {
        userId?: string;
        organizationId?: string;
        sessionId?: string;
      };
    }
  ): Promise<AgentExecutionResponse> => {
    if (!clientRef.current || !isConnected) {
      throw new Error('Not connected to MCP server');
    }

    return clientRef.current.executeAgent(agentName, {
      query,
      options: {
        streamResponse: options?.streamResponse,
        maxTokens: options?.maxTokens,
        temperature: options?.temperature,
      },
      context: options?.context,
    });
  }, [isConnected]);

  const quickExecute = useCallback(async (
    query: string,
    options?: {
      agentName?: string;
      maxTokens?: number;
      temperature?: number;
      context?: {
        userId?: string;
        organizationId?: string;
        sessionId?: string;
      };
    }
  ): Promise<AgentExecutionResponse> => {
    if (!clientRef.current || !isConnected) {
      throw new Error('Not connected to MCP server');
    }

    return clientRef.current.quickExecute(
      query,
      options?.agentName,
      {
        maxTokens: options?.maxTokens,
        temperature: options?.temperature,
      },
      options?.context
    );
  }, [isConnected]);

  return {
    isConnected,
    isConnecting,
    error,
    agentTools,
    isLoadingTools,
    connect,
    disconnect,
    refreshTools,
    executeAgent,
    quickExecute,
  };
}

export default useMCPAgents;

import { Context, Next } from 'hono';
import { db as pgDb } from '../db/connection';
import { users } from '../db/drizzle-schema';
import { eq } from 'drizzle-orm';
import { generateErrorId, makeApiError } from '../lib/api-error';
import { config } from '../lib/config';
import { logger } from '../lib/production-logger';

interface LockoutRecord {
  userId: string;
  attempts: number;
  firstAttempt: number;
  lastAttempt: number;
  lockedUntil?: number;
  isPermanent: boolean;
}

const lockoutStore = new Map<string, LockoutRecord>();

export class AccountLockoutService {
  private static readonly LOCKOUT_DURATION = 15 * 60 * 1000; // 15 minutes
  private static readonly MAX_ATTEMPTS = 5;
  private static readonly PERMANENT_LOCKOUT_ATTEMPTS = 20;
  private static readonly LOCKOUT_WINDOW = 60 * 60 * 1000; // 1 hour

  static async recordFailedAttempt(identifier: string, userId?: string): Promise<{
    locked: boolean;
    lockedUntil?: number;
    attemptsRemaining: number;
    isPermanent: boolean;
  }> {
    const now = Date.now();
    const existing = lockoutStore.get(identifier);

    if (!existing) {
      const record: LockoutRecord = {
        userId: userId || '',
        attempts: 1,
        firstAttempt: now,
        lastAttempt: now,
        isPermanent: false,
      };
      lockoutStore.set(identifier, record);

      return {
        locked: false,
        attemptsRemaining: this.MAX_ATTEMPTS - 1,
        isPermanent: false,
      };
    }

    // Reset if window expired
    if (now - existing.firstAttempt > this.LOCKOUT_WINDOW) {
      existing.attempts = 1;
      existing.firstAttempt = now;
      existing.lastAttempt = now;
      existing.lockedUntil = undefined;
      existing.isPermanent = false;
    } else {
      existing.attempts++;
      existing.lastAttempt = now;
    }

    // Check for permanent lockout
    if (existing.attempts >= this.PERMANENT_LOCKOUT_ATTEMPTS) {
      existing.isPermanent = true;
      existing.lockedUntil = now + (365 * 24 * 60 * 60 * 1000); // 1 year
      lockoutStore.set(identifier, existing);

      // Log security event
      await this.logSecurityEvent('PERMANENT_LOCKOUT', {
        identifier,
        userId: existing.userId,
        attempts: existing.attempts,
        ip: identifier,
      });

      return {
        locked: true,
        lockedUntil: existing.lockedUntil,
        attemptsRemaining: 0,
        isPermanent: true,
      };
    }

    // Check for temporary lockout
    if (existing.attempts >= this.MAX_ATTEMPTS) {
      const lockoutDuration = this.calculateProgressiveLockout(existing.attempts);
      existing.lockedUntil = now + lockoutDuration;
      lockoutStore.set(identifier, existing);

      // Log security event
      await this.logSecurityEvent('TEMPORARY_LOCKOUT', {
        identifier,
        userId: existing.userId,
        attempts: existing.attempts,
        lockoutDuration,
        ip: identifier,
      });

      return {
        locked: true,
        lockedUntil: existing.lockedUntil,
        attemptsRemaining: 0,
        isPermanent: false,
      };
    }

    lockoutStore.set(identifier, existing);

    return {
      locked: false,
      attemptsRemaining: this.MAX_ATTEMPTS - existing.attempts,
      isPermanent: false,
    };
  }

  static async recordSuccessfulAttempt(identifier: string): Promise<void> {
    const record = lockoutStore.get(identifier);
    if (record) {
      lockoutStore.delete(identifier);

      // Log security event
      await this.logSecurityEvent('SUCCESSFUL_LOGIN', {
        identifier,
        userId: record.userId,
        previousAttempts: record.attempts,
        ip: identifier,
      });
    }
  }

  static isLocked(identifier: string): {
    locked: boolean;
    lockedUntil?: number;
    isPermanent: boolean;
    timeRemaining?: number;
  } {
    const record = lockoutStore.get(identifier);
    if (!record) {
      return { locked: false, isPermanent: false };
    }

    const now = Date.now();

    // Check if lockout has expired
    if (record.lockedUntil && now > record.lockedUntil && !record.isPermanent) {
      lockoutStore.delete(identifier);
      return { locked: false, isPermanent: false };
    }

    const timeRemaining = record.lockedUntil ? Math.max(0, record.lockedUntil - now) : 0;

    return {
      locked: record.lockedUntil ? now <= record.lockedUntil : false,
      lockedUntil: record.lockedUntil,
      isPermanent: record.isPermanent,
      timeRemaining,
    };
  }

  static async unlockAccount(identifier: string, adminUserId: string): Promise<boolean> {
    const record = lockoutStore.get(identifier);
    if (!record) {
      return false;
    }

    lockoutStore.delete(identifier);

    // Log security event
    await this.logSecurityEvent('ACCOUNT_UNLOCKED', {
      identifier,
      userId: record.userId,
      adminUserId,
      previousAttempts: record.attempts,
      wasPermanent: record.isPermanent,
    });

    return true;
  }

  private static calculateProgressiveLockout(attempts: number): number {
    // Progressive lockout: 15min, 30min, 1hr, 2hr, 4hr, 8hr, 16hr, 24hr
    const baseDuration = this.LOCKOUT_DURATION;
    const multiplier = Math.min(Math.pow(2, Math.floor((attempts - this.MAX_ATTEMPTS) / 2)), 32);
    return baseDuration * multiplier;
  }

  private static async logSecurityEvent(event: string, data: any): Promise<void> {
    try {
      // Log to audit system
      const { logAudit } = await import('../lib/audit');
      await logAudit('SECURITY', event, data);

      // Also log to console for immediate visibility
      logger.warn(`[SECURITY] ${event}:`, {
        ...data,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      logger.error('Failed to log security event:', error as Error);
    }
  }

  // Get lockout statistics for monitoring
  static getStatistics(): {
    totalLocked: number;
    permanentlyLocked: number;
    temporarilyLocked: number;
    averageAttempts: number;
  } {
    const now = Date.now();
    const records = Array.from(lockoutStore.values());

    const permanentlyLocked = records.filter(r => r.isPermanent).length;
    const temporarilyLocked = records.filter(r => 
      r.lockedUntil && now <= r.lockedUntil && !r.isPermanent
    ).length;

    const averageAttempts = records.length > 0 
      ? records.reduce((sum, r) => sum + r.attempts, 0) / records.length 
      : 0;

    return {
      totalLocked: permanentlyLocked + temporarilyLocked,
      permanentlyLocked,
      temporarilyLocked,
      averageAttempts,
    };
  }

  // Cleanup expired entries
  static cleanup(): void {
    const now = Date.now();
    for (const [key, record] of lockoutStore.entries()) {
      if (record.lockedUntil && now > record.lockedUntil && !record.isPermanent) {
        lockoutStore.delete(key);
      }
    }
  }
}

// Middleware for automatic account lockout protection
export function accountLockoutProtection() {
  return async (c: Context, next: Next) => {
    const identifier = c.req.header('x-forwarded-for') || 
                      c.req.header('x-real-ip') || 
                      'unknown';

    const lockoutStatus = AccountLockoutService.isLocked(identifier);

    if (lockoutStatus.locked) {
      const errorId = generateErrorId();
      const timestamp = new Date().toISOString();

      const response = makeApiError(
        c,
        lockoutStatus.isPermanent ? 'ACCOUNT_PERMANENTLY_LOCKED' : 'ACCOUNT_TEMPORARILY_LOCKED',
        lockoutStatus.isPermanent 
          ? 'Account has been permanently locked due to repeated failed attempts. Please contact support.'
          : `Account temporarily locked due to repeated failed attempts. Try again in ${Math.ceil((lockoutStatus.timeRemaining || 0) / 60000)} minutes.`,
        {
          lockedUntil: lockoutStatus.lockedUntil ? new Date(lockoutStatus.lockedUntil).toISOString() : undefined,
          isPermanent: lockoutStatus.isPermanent,
          timeRemaining: lockoutStatus.timeRemaining,
        },
        errorId,
        timestamp
      );

      return c.json(response, lockoutStatus.isPermanent ? 423 : 429);
    }

    await next();
  };
}

// Cleanup expired lockouts periodically
setInterval(() => {
  AccountLockoutService.cleanup();
}, 5 * 60 * 1000); // Cleanup every 5 minutes

import { z } from 'zod';

/**
 * Comprehensive input validation schemas
 */
export const validationSchemas = {
  // User-related validation
  userRegistration: z.object({
    email: z.string().email('Invalid email format'),
