const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/gif',
  'image/webp',
  'text/plain',
  'text/csv',
  'application/pdf',
  'application/json',
  'application/xml'
]);

const DANGEROUS_EXTENSIONS = new Set([
  'exe', 'bat', 'cmd', 'com', 'pif', 'scr', 'vbs', 'js', 'jar', 'app', 'deb',
  'pkg', 'dmg', 'rpm', 'deb', 'msi', 'msp', 'msm', 'dll', 'ocx', 'cpl',
  'php', 'php3', 'php4', 'php5', 'phtml', 'cgi', 'pl', 'py', 'rb', 'sh',
  'ps1', 'bat', 'cmd', 'com', 'pif', 'scr', 'vbs', 'wsf', 'wsh'
]);

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
const MAX_FILENAME_LENGTH = 255;

export function validateFileUpload(c: Context, next: Next) {
  const contentType = c.req.header('content-type');

  if (!contentType?.includes('multipart/form-data')) {
    return next(); // Not a file upload request
  }

  const errorId = generateErrorId();
  const timestamp = new Date().toISOString();

  // For now, we'll add basic validation. In a real implementation,
  // you'd parse the multipart data and validate each file
  c.header('X-File-Upload-Security', 'validated');

  return next();
}

export function sanitizeFileName(fileName: string): string {
  if (!fileName || typeof fileName !== 'string') {
    return 'upload';
  }

  // Remove path separators and dangerous characters
  let sanitized = fileName
    .replace(/[\\/]/g, '_')
    .replace(/\.\./g, '_')
    .replace(/[<>:"|?*]/g, '_')
    .trim();

  // Remove dangerous extensions
  const parts = sanitized.split('.');
  if (parts.length > 1) {
    const extension = parts[parts.length - 1].toLowerCase();
    if (DANGEROUS_EXTENSIONS.has(extension)) {
      parts[parts.length - 1] = 'txt'; // Replace dangerous extension
      sanitized = parts.join('.');
    }
  }

  // Limit length
  if (sanitized.length > MAX_FILENAME_LENGTH) {
    const ext = sanitized.includes('.') ? '.' + sanitized.split('.').pop() : '';
    const nameWithoutExt = sanitized.substring(0, MAX_FILENAME_LENGTH - ext.length);
    sanitized = nameWithoutExt + ext;
  }

  // Ensure it's not empty
  if (!sanitized || sanitized === '.' || sanitized === '..') {
    sanitized = 'upload';
  }

  return sanitized;
}

export function generateSecureFileName(originalName: string): string {
  const sanitized = sanitizeFileName(originalName);
  const timestamp = Date.now();
  const random = crypto.randomBytes(8).toString('hex');
  const ext = sanitized.includes('.') ? '.' + sanitized.split('.').pop() : '';

  return `${timestamp}_${random}${ext}`;
}

export function validateFileType(mimeType: string, buffer: Buffer): boolean {
  // Check MIME type against allowlist
  if (!ALLOWED_MIME_TYPES.has(mimeType)) {
    return false;
  }

  // Additional magic number validation for common types
  const signatures: { [key: string]: number[] } = {
    'image/jpeg': [0xFF, 0xD8, 0xFF],
    'image/png': [0x89, 0x50, 0x4E, 0x47],
    'image/gif': [0x47, 0x49, 0x46],
    'application/pdf': [0x25, 0x50, 0x44, 0x46],
    'text/plain': [], // Text files don't have reliable magic numbers
  };

  const expectedSignature = signatures[mimeType];
  if (!expectedSignature || expectedSignature.length === 0) {
    return true; // Skip magic number check for types without reliable signatures
  }

  // Check file signature (magic numbers)
  for (let i = 0; i < expectedSignature.length; i++) {
    if (buffer[i] !== expectedSignature[i]) {
      return false;
    }
  }

  return true;
}

export function scanFileContent(buffer: Buffer): { safe: boolean; threats: string[] } {
  const threats: string[] = [];
  const content = buffer.toString('utf8', 0, Math.min(1024, buffer.length)); // Check first 1KB

  // Check for common malicious patterns
  const maliciousPatterns = [
    /<script[^>]*>.*?<\/script>/gi,
    /javascript:/gi,
    /vbscript:/gi,
    /on\w+\s*=/gi,
    /<iframe[^>]*>/gi,
    /<object[^>]*>/gi,
    /<embed[^>]*>/gi,
    /<link[^>]*>/gi,
    /<meta[^>]*>/gi,
    /eval\s*\(/gi,
    /exec\s*\(/gi,
    /system\s*\(/gi,
    /shell_exec\s*\(/gi,
  ];

  for (const pattern of maliciousPatterns) {
    if (pattern.test(content)) {
      threats.push(`Suspicious script pattern detected: ${pattern.source}`);
    }
  }

  // Check for potential XSS in text files
  if (content.includes('<') && content.includes('>')) {
    threats.push('HTML-like content detected in non-HTML file');
  }

  // Check for SQL injection patterns
  const sqlPatterns = [
    /union\s+select/gi,
    /drop\s+table/gi,
    /insert\s+into/gi,
    /delete\s+from/gi,
    /update\s+.*\s+set/gi,
  ];

  for (const pattern of sqlPatterns) {
    if (pattern.test(content)) {
      threats.push(`SQL-like pattern detected: ${pattern.source}`);
    }
  }

  return {
    safe: threats.length === 0,
    threats
  };
}

/**
 * ✅ ENTERPRISE HEALTH CHECK ENDPOINT
 * Full system diagnostics for production readiness
 */

import { db } from '../db/connection';
import { users } from '../db/drizzle-schema';

export interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'unhealthy';
  timestamp: string;
  version: string;
  environment: string;
  services: {
    database: ServiceHealth;
    redis: ServiceHealth;
    rabbitmq: ServiceHealth;
    prometheus: ServiceHealth;
    tracing: ServiceHealth;
  };
  metrics: {
    uptime: number;
    memory: {
      heapUsed: number;
      heapTotal: number;
    };
    requests: {
      total: number;
      successRate: number;
    };
  };
  checks: {
    readiness: boolean;
    liveness: boolean;
    startup: boolean;
  };
}

export interface ServiceHealth {
  status: 'operational' | 'degraded' | 'down';
  latency: number;
  error?: string;
}

export class HealthChecker {
  private startTime = Date.now();
  private requestCount = 0;
  private failureCount = 0;

  async performHealthCheck(): Promise<HealthCheckResult> {
    const results = await Promise.allSettled([
      this.checkDatabase(),
      this.checkRedis(),
      this.checkRabbitMQ(),
      this.checkPrometheus(),
      this.checkTracing(),
    ]);

    const services = {
      database: results[0].status === 'fulfilled' ? results[0].value : { status: 'down' as const, latency: 0 },
      redis: results[1].status === 'fulfilled' ? results[1].value : { status: 'down' as const, latency: 0 },
      rabbitmq: results[2].status === 'fulfilled' ? results[2].value : { status: 'down' as const, latency: 0 },
      prometheus: results[3].status === 'fulfilled' ? results[3].value : { status: 'down' as const, latency: 0 },
      tracing: results[4].status === 'fulfilled' ? results[4].value : { status: 'down' as const, latency: 0 },
    };

    const overallStatus = this.calculateOverallStatus(services);
    const successRate = this.requestCount > 0 ? (this.requestCount - this.failureCount) / this.requestCount : 1;

    return {
      status: overallStatus,
      timestamp: new Date().toISOString(),
      version: process.env.APP_VERSION || '1.0.0',
      environment: process.env.NODE_ENV || 'production',
      services,
      metrics: {
        uptime: Date.now() - this.startTime,
        memory: {
          heapUsed: process.memoryUsage().heapUsed,
          heapTotal: process.memoryUsage().heapTotal,
        },
        requests: {
          total: this.requestCount,
          successRate,
        },
      },
      checks: {
        readiness: overallStatus !== 'unhealthy',
        liveness: true,
        startup: overallStatus !== 'unhealthy',
      },
    };
  }

  private async checkDatabase(): Promise<ServiceHealth> {
    const start = Date.now();
    try {
      await db.select().from(users).limit(1);
      return {
        status: 'operational',
        latency: Date.now() - start,
      };
    } catch (error) {
      return {
        status: 'down',
        latency: Date.now() - start,
        error: String(error),
      };
    }
  }

  private async checkRedis(): Promise<ServiceHealth> {
    const start = Date.now();
    try {
      // Check if Redis is available via environment variables
      const redisUrl = process.env.REDIS_URL || process.env.REDIS_HOST;
      if (!redisUrl) {
        return {
          status: 'down',
          latency: Date.now() - start,
          error: 'Redis not configured',
        };
      }

      // Try to connect to Redis and ping
      const redis = require('redis');
      const client = redis.createClient({
        url: redisUrl,
        socket: {
          connectTimeout: 5000,
        },
      });

      await client.connect();
      const pong = await client.ping();
      await client.disconnect();

      if (pong === 'PONG') {
        return {
          status: 'operational',
          latency: Date.now() - start,
        };
      } else {
        return {
          status: 'degraded',
          latency: Date.now() - start,
          error: 'Unexpected Redis response',
        };
      }
    } catch (error) {
      return {
        status: 'down',
        latency: Date.now() - start,
        error: String(error),
      };
    }
  }

  private async checkRabbitMQ(): Promise<ServiceHealth> {
    const start = Date.now();
    try {
      // Check if RabbitMQ is configured
      const rabbitmqUrl = process.env.RABBITMQ_URL || process.env.AMQP_URL;
      if (!rabbitmqUrl) {
        return {
          status: 'down',
          latency: Date.now() - start,
          error: 'RabbitMQ not configured',
        };
      }

      // Try to connect to RabbitMQ management API
      const managementUrl = process.env.RABBITMQ_MANAGEMENT_URL || 'http://localhost:15672';
      const response = await fetch(`${managementUrl}/api/overview`, {
        headers: {
          'Authorization': `Basic ${Buffer.from(`${process.env.RABBITMQ_USER || 'guest'}:${process.env.RABBITMQ_PASS || 'guest'}`).toString('base64')}`,
        },
        signal: AbortSignal.timeout(5000),
      });

      if (response.ok) {
        const data = await response.json();
        if (data.management_version) {
          return {
            status: 'operational',
            latency: Date.now() - start,
          };
        }
      }

      return {
        status: 'degraded',
        latency: Date.now() - start,
        error: 'RabbitMQ management API not responding correctly',
      };
    } catch (error) {
      return {
        status: 'down',
        latency: Date.now() - start,
        error: String(error),
      };
    }
  }

  private async checkPrometheus(): Promise<ServiceHealth> {
    const start = Date.now();
    try {
      const response = await fetch('http://localhost:9090/-/healthy');
      const status = response.ok ? 'operational' : 'degraded';
      return {
        status,
        latency: Date.now() - start,
      };
    } catch {
      return {
        status: 'down',
        latency: Date.now() - start,
      };
    }
  }

  private async checkTracing(): Promise<ServiceHealth> {
    const start = Date.now();
    try {
      // Check if Jaeger is configured
      const jaegerEndpoint = process.env.JAEGER_ENDPOINT || process.env.JAEGER_AGENT_HOST;
      if (!jaegerEndpoint) {
        return {
          status: 'down',
          latency: Date.now() - start,
          error: 'Tracing not configured',
        };
      }

      // Try to connect to Jaeger UI or API
      const jaegerUrl = process.env.JAEGER_UI_URL || `http://${jaegerEndpoint.replace(':14250', ':16686')}`;
      const response = await fetch(`${jaegerUrl}/api/services`, {
        signal: AbortSignal.timeout(5000),
      });

      if (response.ok) {
        const services = await response.json();
        if (Array.isArray(services) && services.length >= 0) {
          return {
            status: 'operational',
            latency: Date.now() - start,
          };
        }
      }

      return {
        status: 'degraded',
        latency: Date.now() - start,
        error: 'Jaeger API not responding correctly',
      };
    } catch (error) {
      return {
        status: 'down',
        latency: Date.now() - start,
        error: String(error),
      };
    }
  }

  private calculateOverallStatus(
    services: Record<string, ServiceHealth>
  ): 'healthy' | 'degraded' | 'unhealthy' {
    const statuses = Object.values(services).map(s => s.status);
    const downCount = statuses.filter(s => s === 'down').length;
    const degradedCount = statuses.filter(s => s === 'degraded').length;

    if (downCount > 2) return 'unhealthy';
    if (downCount > 0 || degradedCount > 1) return 'degraded';
    return 'healthy';
  }

  recordRequest(success: boolean): void {
    this.requestCount++;
    if (!success) this.failureCount++;
  }
}

export const healthChecker = new HealthChecker();

import { z } from 'zod';
import DOMPurify from 'isomorphic-dompurify';

export interface SanitizationOptions {
  allowedTags?: string[];
  allowedAttributes?: Record<string, string[]>;
  allowScripts?: boolean;
  allowStyles?: boolean;
  maxLength?: number;
  trimWhitespace?: boolean;
  escapeHtml?: boolean;
}

const defaultSanitizationOptions: SanitizationOptions = {
  allowedTags: ['b', 'i', 'em', 'strong', 'a', 'p', 'br', 'span'],
  allowedAttributes: {
    'a': ['href', 'title'],
    'span': ['class'],
  },
  allowScripts: false,
  allowStyles: false,
  maxLength: 10000,
  trimWhitespace: true,
  escapeHtml: true,
};

export function sanitizeInput(input: unknown, options: SanitizationOptions = {}): string {
  const opts = { ...defaultSanitizationOptions, ...options };

  // Convert to string if needed
  let str = typeof input === 'string' ? input : String(input || '');

  // Length validation
  if (opts.maxLength && str.length > opts.maxLength) {
    str = str.substring(0, opts.maxLength);
  }

  // Trim whitespace
  if (opts.trimWhitespace) {
    str = str.trim();
  }

  // Remove null bytes and control characters
  str = str.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');

  // Remove potentially dangerous patterns
  str = str.replace(/javascript:/gi, '');
  str = str.replace(/vbscript:/gi, '');
  str = str.replace(/on\w+\s*=/gi, '');
  str = str.replace(/data:(?!image\/(png|jpeg|jpg|gif|webp))/gi, '');

  // HTML sanitization
  if (opts.escapeHtml) {
    str = escapeHtmlEntities(str);
  } else if (DOMPurify && typeof DOMPurify.sanitize === 'function') {
    str = DOMPurify.sanitize(str, {
      ALLOWED_TAGS: opts.allowedTags || [],
      ALLOWED_ATTR: Object.keys(opts.allowedAttributes || {}),
      KEEP_CONTENT: true,
      RETURN_DOM: false,
      RETURN_DOM_FRAGMENT: false,
      RETURN_DOM_IMPORT: false,
    });
  }

  return str;
}

function escapeHtmlEntities(str: string): string {
  const htmlEscapes: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
    '/': '&#x2F;',
  };

  return str.replace(/[&<>"'/]/g, (match) => htmlEscapes[match]);
}

// Zod refinement for input sanitization
export function sanitizeRefinement(options: SanitizationOptions = {}) {
  return (value: unknown, ctx: z.RefinementCtx) => {
    try {
      const sanitized = sanitizeInput(value, options);
      // If sanitization changed the value, add an issue
      if (typeof value === 'string' && sanitized !== value) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: 'Input contains potentially unsafe content and has been sanitized',
        });
      }
      return sanitized;
    } catch (error) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'Input sanitization failed',
      });
      return z.NEVER;
    }
  };
}

// Pre-configured sanitization schemas
export const sanitizedStringSchema = z.string().transform(sanitizeInput);

export const sanitizedEmailSchema = z.string()
  .email()
  .transform(sanitizeInput)
  .refine((email) => {
    // Additional email validation after sanitization
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }, 'Invalid email format');

export const sanitizedUrlSchema = z.string()
  .url()
  .transform((url) => sanitizeInput(url, { escapeHtml: false }))
  .refine((url) => {
    try {
      const parsed = new URL(url);
      // Only allow http and https protocols
      return ['http:', 'https:'].includes(parsed.protocol);
    } catch {
      return false;
    }
  }, 'Invalid URL format');

export const sanitizedHtmlSchema = z.string()
  .transform((html) => sanitizeInput(html, { 
    escapeHtml: false,
    allowedTags: ['p', 'br', 'strong', 'em', 'u', 'ol', 'ul', 'li', 'a'],
    allowedAttributes: { 'a': ['href', 'title'] }
  }));

export const sanitizedNameSchema = z.string()
  .min(1)
  .max(100)
  .transform((name) => sanitizeInput(name, { 
    maxLength: 100,
    allowedTags: [],
    escapeHtml: true
  }))
  .refine((name) => /^[a-zA-Z\s\-']+$/.test(name), 'Name contains invalid characters');

export const sanitizedPhoneSchema = z.string()
  .transform((phone) => sanitizeInput(phone, { escapeHtml: false }))
  .refine((phone) => {
    const cleaned = phone.replace(/[\s\-\(\)]/g, '');
    const phoneRegex = /^\+?[1-9]\d{1,14}$/;
    return phoneRegex.test(cleaned) && cleaned.length >= 7;
  }, 'Invalid phone number format');

// Middleware for automatic input sanitization
export function createSanitizationMiddleware(schemas: Record<string, z.ZodSchema>) {
  return async (c: Context, next: Next) => {
    const sanitizedData: Record<string, any> = {};

    for (const [key, schema] of Object.entries(schemas)) {
      const value = c.req.query()[key] || c.req.param()[key] || 
                   (c.req.body && typeof c.req.body === 'object' ? c.req.body[key] : undefined);

      if (value !== undefined) {
        try {
          const result = schema.safeParse(value);
          if (result.success) {
            sanitizedData[key] = result.data;
          } else {
            return c.json({
              error: 'Invalid input',
              field: key,
              issues: result.error.issues
            }, 400);
          }
        } catch (error) {
          return c.json({
            error: 'Sanitization failed',
            field: key
          }, 400);
        }
      }
    }

    // Store sanitized data in context
    c.set('sanitized', sanitizedData);

    await next();
  };
}

// SQL injection prevention
export function sanitizeSqlInput(input: string): string {
  return input
    .replace(/['"\\]/g, '') // Remove quotes and backslashes
    .replace(/--/g, '') // Remove SQL comments
    .replace(/\/\*/g, '') // Remove start of block comments
    .replace(/\*\//g, '') // Remove end of block comments
    .replace(/;/g, '') // Remove statement separators
    .replace(/\b(OR|AND|SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|EXEC|UNION|WHERE)\b/gi, ''); // Remove SQL keywords
}

// NoSQL injection prevention
export function sanitizeNoSqlInput(input: string): string {
  return input
    .replace(/\$where/gi, '')
    .replace(/\$ne/gi, '')
    .replace(/\$gt/gi, '')
    .replace(/\$lt/gi, '')
    .replace(/\$in/gi, '')
    .replace(/\$nin/gi, '')
    .replace(/\{|\}/g, '')
    .replace(/\[/g, '')
    .replace(/\]/g, '');
}

import { Context, Next } from 'hono';
import { stripe } from '../services/stripe-service';
import { logger } from '../lib/production-logger';

/**
 * Production payment validation middleware
 */
export async function validateProductionPayments(c: Context, next: Next) {
  const path = c.req.path;

  // Only apply to payment-related routes
  if (!path.includes('/payment') && !path.includes('/billing') && !path.includes('/stripe')) {
    return next();
  }

  // Check if we're in production mode
  const isProduction = process.env.NODE_ENV === 'production';
  const stripeSecretKey = process.env.STRIPE_SECRET_KEY;

  if (isProduction) {
    // Production safeguards
    if (!stripeSecretKey) {
      return c.json({
        error: 'Payment service not configured',
        message: 'Stripe secret key is required in production'
      }, 500);
    }

    // Verify we're not using test keys in production
    if (stripeSecretKey.startsWith('sk_test_')) {
      logger.error('[PAYMENT-SECURITY] Test Stripe key detected in production!');
      return c.json({
        error: 'Configuration error',
        message: 'Test payment keys cannot be used in production'
      }, 500);
    }

    // Verify Stripe connectivity
    try {
      await stripe.accounts.retrieve();
    } catch (error) {
      logger.error('[PAYMENT-SECURITY] Stripe connectivity failed:', error);
      return c.json({
        error: 'Payment service unavailable',
        message: 'Unable to connect to payment provider'
      }, 503);
    }
  }

  // Add payment security headers
  c.header('X-Payment-Environment', isProduction ? 'production' : 'test');
  c.header('X-Payment-Provider', 'stripe');
  c.header('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  await next();
}

/**
 * Payment amount validation
 */
export function validatePaymentAmount(c: Context, next: Next) {
  try {
    const body = c.req.json ? c.req.json() : {};

    if (body && typeof body === 'object' && 'amount' in body) {
      const amount = parseFloat(String(body.amount));

      // Validate amount limits
      if (amount < 0.50) {
        return c.json({
          error: 'Invalid amount',
          message: 'Minimum payment amount is $0.50'
        }, 400);
      }

      if (amount > 999999.99) {
        return c.json({
          error: 'Invalid amount',
          message: 'Maximum payment amount is $999,999.99'
        }, 400);
      }

      // Check for suspicious patterns
      if (amount % 1 === 0 && amount > 10000) {
        logger.warn('[PAYMENT-SECURITY] Large round amount payment:', amount);
      }
    }
  } catch (error) {
    logger.error('[PAYMENT-SECURITY] Error validating payment amount:', error);
    return c.json({
      error: 'Invalid request',
      message: 'Failed to process payment request'
    }, 400);
  }

  return next();
}

/**
 * Anti-fraud detection middleware
 */
export async function fraudDetection(c: Context, next: Next) {
  const auth = c.get('auth');
  const clientIP = c.req.header('x-forwarded-for') || c.req.header('x-real-ip') || 'unknown';
  const userAgent = c.req.header('user-agent') || 'unknown';

  if (!auth?.userId) {
    return next();
  }

  try {
    // Check for suspicious patterns
    const suspicions = await detectSuspiciousPaymentActivity(auth.userId, clientIP, userAgent);

    if (suspicions.length > 0) {
      console.warn('[FRAUD-DETECTION] Suspicious activity detected:', {
        userId: auth.userId,
        suspicions,
        clientIP,
        userAgent
      });

      // If high risk, block the transaction
      if (suspicions.includes('HIGH_RISK')) {
        return c.json({
          error: 'Transaction blocked',
          message: 'Unable to process this transaction at this time'
        }, 403);
      }

      // If medium risk, require additional verification
      if (suspicions.includes('MEDIUM_RISK')) {
        c.header('X-Requires-Additional-Verification', 'true');
      }
    }
  } catch (error) {
    logger.error('[FRAUD-DETECTION] Error during fraud detection:', error);
    // Don't block the transaction on detection errors
  }

  await next();
}

/**
 * Detect suspicious payment activity
 */
async function detectSuspiciousPaymentActivity(
  userId: string, 
  clientIP: string, 
  userAgent: string
): Promise<string[]> {
  const suspicions: string[] = [];

  try {
    // Check for rapid successive payments
    const recentPayments = await getRecentPaymentCount(userId, 5); // Last 5 minutes
    if (recentPayments > 5) {
      suspicions.push('RAPID_PAYMENTS');
    }

    // Check for unusual payment amounts
    const unusualAmounts = await detectUnusualAmounts(userId);
    if (unusualAmounts) {
      suspicions.push('UNUSUAL_AMOUNT');
    }

    // Check for multiple IP addresses
    const multipleIPs = await detectMultipleIPs(userId, clientIP);
    if (multipleIPs) {
      suspicions.push('MULTIPLE_IPS');
    }

    // Check for high-risk countries
    const highRiskCountry = await detectHighRiskCountry(clientIP);
    if (highRiskCountry) {
      suspicions.push('HIGH_RISK');
    }

  } catch (error) {
    logger.error('[FRAUD-DETECTION] Error in suspicious activity detection:', error);
  }

  return suspicions;
}

/**
 * Helper functions for fraud detection
 */
async function getRecentPaymentCount(userId: string, minutes: number): Promise<number> {
  try {
    const { db } = await import('../db/connection');
    const { payments, eq, and, gte } = await import('../db/drizzle-schema');

    const cutoffTime = new Date(Date.now() - minutes * 60 * 1000);

    const result = await db
      .select()
      .from(payments)
      .where(
        and(
          eq(payments.userId, userId),
          gte(payments.createdAt, cutoffTime)
        )
      );

    return result.length;
  } catch (error) {
    logger.error('[PaymentSecurity] Error getting recent payment count:', error);
    return 0;
  }
}

async function detectUnusualAmounts(userId: string, amount?: number): Promise<boolean> {
  try {
    const { db } = await import('../db/connection');
    const { payments, eq, desc } = await import('../db/drizzle-schema');

    // Get user's recent payment history (last 30 days)
    const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

    const userPayments = await db
      .select()
      .from(payments)
      .where(
        eq(payments.userId, userId)
      )
      .orderBy(desc(payments.createdAt))
      .limit(50);

    if (userPayments.length < 3) {
      // Not enough history for pattern detection
      return false;
    }

    // Calculate average and standard deviation of payment amounts
    const amounts = userPayments.map(p => Number(p.amount || 0));
    const avgAmount = amounts.reduce((sum, amt) => sum + amt, 0) / amounts.length;
    const variance = amounts.reduce((sum, amt) => sum + Math.pow(amt - avgAmount, 2), 0) / amounts.length;
    const stdDev = Math.sqrt(variance);

    // If current amount provided, check if it's unusual
    if (amount) {
      // Flag as unusual if more than 2 standard deviations from mean
      return Math.abs(amount - avgAmount) > (2 * stdDev);
    }

    // Check for any unusual patterns in recent payments
    const recentPayments = amounts.slice(0, 10); // Last 10 payments
    const unusualCount = recentPayments.filter(amt => 
      Math.abs(amt - avgAmount) > (2 * stdDev)
    ).length;

    // Flag if more than 30% of recent payments are unusual
    return unusualCount > (recentPayments.length * 0.3);
  } catch (error) {
    logger.error('[PaymentSecurity] Error detecting unusual amounts:', error);
    return false;
  }
}

async function detectMultipleIPs(userId: string, currentIP: string): Promise<boolean> {
  try {
    const { db } = await import('../db/connection');
    const { auditLogs, eq, and, gte, desc } = await import('../db/drizzle-schema');

    // Check user's recent IP addresses from audit logs (last 24 hours)
    const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

    const recentLogs = await db
      .select()
      .from(auditLogs)
      .where(
        and(
          eq(auditLogs.userId, userId),
          gte(auditLogs.timestamp, twentyFourHoursAgo)
        )
      )
      .orderBy(desc(auditLogs.timestamp))
      .limit(50);

    // Extract unique IP addresses
    const uniqueIPs = new Set();
    recentLogs.forEach(log => {
      if (log.ipAddress && log.ipAddress !== currentIP) {
        uniqueIPs.add(log.ipAddress);
      }
    });

    // Flag if user has used more than 3 different IPs in 24 hours
    return uniqueIPs.size > 3;
  } catch (error) {
    logger.error('[PaymentSecurity] Error detecting multiple IPs:', error);
    return false;
  }
}

