  logger.info('SIGTERM received, shutting down gracefully')
  otelSDK.shutdown()
    .then(() => logger.info('OpenTelemetry shut down'))
    .catch((err) => logger.error('Error shutting down OpenTelemetry', err))
    .finally(() => process.exit(0))
})

