  private async createRecurringPattern(
    scheduleId: string,
    recurrence: NonNullable<ScheduleConfig['recurrence']>
  ): Promise<void> {
    await db.insert(agentRecurringSchedules).values({
      id: crypto.randomUUID(),
      scheduleId,
      pattern: recurrence.pattern,
