const logger = createLogger(__filename.split('/').pop()?.replace('.ts', '') || 'Service');

// Base interfaces for service layer
export interface ServiceResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  metadata?: {
    total?: number;
    page?: number;
    limit?: number;
    hasMore?: boolean;
  };
}

export interface PaginationOptions {
  page?: number;
  limit?: number;
  offset?: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
}

export interface FilterOptions {
  search?: string;
  status?: string | string[];
  dateRange?: {
    start: Date;
    end: Date;
  };
  userId?: string;
  organizationId?: string;
}

export interface ServiceContext {
  userId: string;
  organizationId?: string;
  role: string;
  ipAddress?: string;
  userAgent?: string;
}

// Base Service Class
export abstract class BaseService {
  protected db = pgDb;
  protected context?: ServiceContext;

  constructor(context?: ServiceContext) {
    this.context = context;
  }

  // Common pagination logic
  protected buildPaginationQuery(options: PaginationOptions = {}) {
    const page = Math.max(1, options.page || 1);
    const limit = Math.min(100, Math.max(1, options.limit || 20));
    const offset = options.offset || ((page - 1) * limit);

    return {
      limit,
      offset,
      page,
      hasMore: false, // Will be updated after query
    };
  }

  // Common filtering logic
  protected buildFilterConditions(
    table: any,
    filters: FilterOptions = {},
    searchFields: string[] = []
  ) {
    const conditions = [];

    // Organization filtering (for multi-tenant)
    if (this.context.organizationId && table.organizationId) {
      conditions.push(eq(table.organizationId, this.context.organizationId));
    }

    // User filtering
    if (filters.userId && table.userId) {
      conditions.push(eq(table.userId, filters.userId));
    }

    // Status filtering
    if (filters.status) {
      if (Array.isArray(filters.status)) {
        conditions.push(inArray(table.status, filters.status));
      } else if (table.status) {
        conditions.push(eq(table.status, filters.status));
      }
    }

    // Date range filtering
    if (filters.dateRange) {
      if (table.createdAt) {
        conditions.push(
          and(
            // @ts-ignore
            table.createdAt >= filters.dateRange.start,
            // @ts-ignore
            table.createdAt <= filters.dateRange.end
          )
        );
      }
    }

    // Search filtering
    if (filters.search && searchFields.length > 0) {
      const searchConditions = searchFields.map(field => 
        ilike(table[field], `%${filters.search}%`)
      );
      conditions.push(or(...searchConditions));
    }

    return conditions;
  }

  // Common sorting logic
  protected buildSortingQuery(options: PaginationOptions = {}) {
    const sortBy = options.sortBy || 'createdAt';
    const sortOrder = options.sortOrder || 'desc';

    return sortOrder === 'asc' ? asc(sortBy) : desc(sortBy);
  }

  // Error handling wrapper
  protected async handleServiceOperation<T>(
    operation: () => Promise<T>,
    operationName: string,
    resourceType: string,
    resourceId?: string
  ): Promise<ServiceResponse<T>> {
    try {
      const startTime = Date.now();
      const data = await operation();
      const duration = Date.now() - startTime;

      // Log successful operation
      logAudit({
        userId: this.context?.userId || 'system',
        organizationId: this.context?.organizationId,
        action: `${operationName?.toUpperCase?.() || 'OPERATION'}` as any,
        resource: resourceType,
        resourceId,
        ipAddress: this.context?.ipAddress,
        userAgent: this.context?.userAgent,
        metadata: { duration },
        status: 'success',
      });

      return {
        success: true,
        data,
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';

      // Log failed operation
      logAudit({
        userId: this.context?.userId || 'system',
        organizationId: this.context?.organizationId,
        action: `${operationName?.toUpperCase?.() || 'OPERATION'}_FAILED` as any,
        resource: resourceType,
        resourceId,
        ipAddress: this.context?.ipAddress,
        userAgent: this.context?.userAgent,
        metadata: { error: errorMessage },
        status: 'failure',
      });

      return {
        success: false,
        error: errorMessage,
      };
    }
  }

  // Validation helper
  protected validateRequired(data: Record<string, any>, requiredFields: string[]): string[] {
    const missing: string[] = [];

    for (const field of requiredFields) {
      if (!data[field] || data[field] === '') {
        missing.push(field);
      }
    }

    return missing;
  }

  // Permission checking helper with RBAC integration
  protected hasPermission(permission: string): boolean {
    try {
      // Import RBAC service dynamically to avoid circular dependencies
      const { RBACService } = require('../lib/rbac');

      // Create RBAC service instance with current context
      const rbacService = new RBACService(this.context);

      // Check permission using RBAC service
      return rbacService.hasPermission(permission);
    } catch (error) {
      logger.warn('RBAC permission check failed, allowing by default:', error);
      // Fallback to role-based check for backward compatibility
      return this.fallbackPermissionCheck(permission);
    }
  }

  // Fallback permission check for backward compatibility
  private fallbackPermissionCheck(permission: string): boolean {
    const rolePermissions = {
      'super_admin': ['*'], // All permissions
      'admin': ['read:*', 'write:*', 'delete:*'],
      'manager': ['read:*', 'write:own_data', 'delete:own_data'],
      'user': ['read:own_data', 'write:own_data'],
      'guest': ['read:public_data'],
    };

    const userPermissions = rolePermissions[this.context.role as keyof typeof rolePermissions] || [];

    // Check for wildcard permissions
    if (userPermissions.includes('*')) {
      return true;
    }

    // Check for exact match or wildcard patterns
    return userPermissions.some(perm => {
      if (perm === permission) return true;

      // Handle wildcard patterns like 'read:*'
      if (perm.includes('*')) {
        const pattern = perm.replace('*', '.*');
        const regex = new RegExp(`^${pattern}$`);
        return regex.test(permission);
      }

      return false;
    });
  }

  // Resource ownership check
  protected async checkOwnership(
    table: any,
    resourceId: string,
    userIdField: string = 'userId'
  ): Promise<boolean> {
    try {
      const [resource] = await this.db
        .select()
        .from(table)
        .where(eq(table.id, resourceId))
        .limit(1);

      if (!resource) {
        return false;
      }

      // Super admins can access any resource
      if (this.context.role === 'super_admin') {
        return true;
      }

      // Check if user owns the resource
      return resource[userIdField] === this.context.userId;
    } catch {
      return false;
    }
  }

  // Soft delete helper
  protected async softDelete(
    table: any,
    resourceId: string,
    deletedByField: string = 'deletedBy'
  ): Promise<boolean> {
    try {
      await this.db
        .update(table)
        .set({
          deletedAt: new Date(),
          [deletedByField]: this.context.userId,
        })
        .where(eq(table.id, resourceId));

      return true;
    } catch {
      return false;
    }
  }

  // Generate unique slug helper
  protected async generateUniqueSlug(
    table: any,
    baseSlug: string,
    slugField: string = 'slug'
  ): Promise<string> {
    let slug = baseSlug;
    let counter = 1;

    while (true) {
      const [existing] = await this.db
        .select()
        .from(table)
        .where(eq(table[slugField], slug))
        .limit(1);

      if (!existing) {
        return slug;
      }

      slug = `${baseSlug}-${counter}`;
      counter++;
    }
  }

  // Redis-based cache implementation
  protected async cacheGet<T>(key: string): Promise<T | null> {
    try {
      // Import Redis client dynamically to avoid circular dependencies
      const { getRedisClient } = await import('../lib/redis');
      const redis = getRedisClient();

      if (!redis) {
        return null;
      }

      const cached = await redis.get(key);
      return cached ? JSON.parse(cached) : null;
    } catch (error) {
      logger.warn('Cache get error:', error);
      return null;
    }
  }

  protected async cacheSet(key: string, value: any, ttl: number = 3600): Promise<void> {
    try {
      const { getRedisClient } = await import('../lib/redis');
      const redis = getRedisClient();

      if (!redis) {
        return;
      }

      await redis.setex(key, ttl, JSON.stringify(value));
    } catch (error) {
      logger.warn('Cache set error:', error);
    }
  }

  protected async cacheDelete(key: string): Promise<void> {
    try {
      const { getRedisClient } = await import('../lib/redis');
      const redis = getRedisClient();

      if (!redis) {
        return;
      }

      await redis.del(key);
    } catch (error) {
      logger.warn('Cache delete error:', error);
    }
  }

  // Redis-based rate limiting implementation
  protected async checkRateLimit(
    key: string,
    limit: number,
    windowMs: number
  ): Promise<{ allowed: boolean; remaining: number; resetTime: number }> {
    try {
      const { getRedisClient } = await import('../lib/redis');
      const redis = getRedisClient();

      if (!redis) {
        // Fallback to memory-based rate limiting
        return this.memoryRateLimit(key, limit, windowMs);
      }

      const now = Date.now();
      const window = Math.ceil(windowMs / 1000); // Convert to seconds
      const redisKey = `rate_limit:${key}`;

      const pipeline = redis.pipeline();
      pipeline.incr(redisKey);
      pipeline.expire(redisKey, window);

      const results = await pipeline.exec();
      const currentCount = results?.[0]?.[1] as number || 0;

      const allowed = currentCount <= limit;
      const remaining = Math.max(0, limit - currentCount);
      const resetTime = now + windowMs;

      return { allowed, remaining, resetTime };
    } catch (error) {
      logger.warn('Rate limit error:', error);
      // Fallback to memory-based rate limiting
      return this.memoryRateLimit(key, limit, windowMs);
    }
  }

  // Memory-based fallback for rate limiting
  private memoryRateLimitStore = new Map<string, { count: number; resetTime: number }>();

  private memoryRateLimit(key: string, limit: number, windowMs: number): { allowed: boolean; remaining: number; resetTime: number } {
    const now = Date.now();
    const stored = this.memoryRateLimitStore.get(key);

    if (!stored || now > stored.resetTime) {
      this.memoryRateLimitStore.set(key, {
        count: 1,
        resetTime: now + windowMs,
      });
      return {
        allowed: true,
        remaining: limit - 1,
        resetTime: now + windowMs,
      };
    }

    const newCount = stored.count + 1;
    stored.count = newCount;

    return {
      allowed: newCount <= limit,
      remaining: Math.max(0, limit - newCount),
      resetTime: stored.resetTime,
    };
  }

  // Abstract methods that must be implemented by child services
  abstract create(data: any): Promise<ServiceResponse>;
  abstract findById(id: string): Promise<ServiceResponse>;
  abstract update(id: string, data: any): Promise<ServiceResponse>;
  abstract delete(id: string): Promise<ServiceResponse>;
  abstract list(options: { pagination?: PaginationOptions; filters?: FilterOptions }): Promise<ServiceResponse<any[]>>;
}

// Service factory for dependency injection
export class ServiceFactory {
  private static services: Map<string, any> = new Map();

  static register<T>(name: string, serviceClass: new (context: ServiceContext) => T): void {
    this.services.set(name, serviceClass);
  }

  static create<T>(name: string, context: ServiceContext): T {
    const ServiceClass = this.services.get(name);
    if (!ServiceClass) {
      throw new Error(`Service '${name}' not found`);
    }
    return new ServiceClass(context);
  }

  static list(): string[] {
    return Array.from(this.services.keys());
  }
}

// Error types for better error handling
export class ServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 500,
    public details?: any
  ) {
    super(message);
    this.name = 'ServiceError';
  }
}

export class ValidationError extends ServiceError {
  constructor(message: string, public field?: string) {
    super(message, 'VALIDATION_ERROR', 400, { field });
    this.name = 'ValidationError';
  }
}

export class NotFoundError extends ServiceError {
  constructor(resource: string, id?: string) {
    super(
      `${resource}${id ? ` with id ${id}` : ''} not found`,
      'NOT_FOUND',
      404,
      { resource, id }
    );
    this.name = 'NotFoundError';
  }
}

export class PermissionError extends ServiceError {
  constructor(action: string, resource: string) {
    super(
      `Insufficient permissions to ${action} ${resource}`,
      'PERMISSION_DENIED',
      403,
      { action, resource }
    );
    this.name = 'PermissionError';
  }
}

export class ConflictError extends ServiceError {
  constructor(message: string, public field?: string) {
    super(message, 'CONFLICT', 409, { field });
    this.name = 'ConflictError';
  }
}

import { EventEmitter } from 'events';
import Redis from 'ioredis';
import { createLogger } from '../lib/production-logger';

const logger = createLogger('CacheService');

export interface CacheOptions {
  ttl?: number;
  maxSize?: number;
  evictionPolicy?: 'lru' | 'lfu' | 'ttl';
}

export class CacheService extends EventEmitter {
  private redis: Redis | null = null;
  private defaultTtl: number = 3600;

  private distributedNodes: Map<string, any> = new Map();

  constructor(options: CacheOptions = {}) {
    super();
    this.defaultTtl = options.ttl || 3600;
  }

  private getEffectiveKey(key: string, organizationId?: string): string {
    return organizationId ? `org:${organizationId}:${key}` : key;
  }

  async get<T>(key: string, organizationId?: string): Promise<T | null> {
    if (!this.redis) return null;
    const effectiveKey = this.getEffectiveKey(key, organizationId);
    try {
      const data = await this.redis.get(effectiveKey);
      if (!data) return null;
      try {
        return JSON.parse(data) as T;
      } catch (e) {
        return null;
      }
    } catch (error) {
      logger.error(`[Cache] Get error for ${effectiveKey}:`, error as Error);
      return null;
    }
  }

  async set(key: string, value: any, ttl?: number, organizationId?: string): Promise<boolean> {
    if (!this.redis) return false;
    const effectiveKey = this.getEffectiveKey(key, organizationId);
    const effectiveTtl = ttl || this.defaultTtl;
    try {
      const serialized = JSON.stringify(value);
      await this.redis.set(effectiveKey, serialized);
      if (effectiveTtl > 0) {
        await this.redis.expire(effectiveKey, effectiveTtl);
      }
      return true;
    } catch (error) {
      logger.error(`[Cache] Set error for ${effectiveKey}:`, error as Error);
      return false;
    }
  }

  async del(key: string, organizationId?: string): Promise<boolean> {
    if (!this.redis) return false;
    const effectiveKey = this.getEffectiveKey(key, organizationId);
    try {
      const result = await this.redis.del(effectiveKey);
      return result > 0;
    } catch (error) {
      logger.error(`[Cache] Delete error for ${effectiveKey}:`, error as Error);
      return false;
    }
  }

  async exists(key: string, organizationId?: string): Promise<boolean> {
    if (!this.redis) return false;
    const effectiveKey = this.getEffectiveKey(key, organizationId);
    try {
      const result = await this.redis.exists(effectiveKey);
      return result > 0;
    } catch (error) {
      return false;
    }
  }

  async getTTL(key: string, organizationId?: string): Promise<number> {
    if (!this.redis) return -2;
    const effectiveKey = this.getEffectiveKey(key, organizationId);
    try {
      return await this.redis.ttl(effectiveKey);
    } catch (error) {
      return -2;
    }
  }

  async setWithPattern(pattern: string, data: Record<string, any>, ttl?: number): Promise<boolean> {
    if (!this.redis) return false;
    try {
      for (const [key, value] of Object.entries(data)) {
        await this.set(key, value, ttl);
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  async getWithPattern(pattern: string): Promise<Record<string, any>> {
    if (!this.redis) return {};
    try {
      const keys = await this.redis.keys(pattern);
      const result: Record<string, any> = {};
      for (const key of keys) {
        result[key] = await this.get(key);
      }
      return result;
    } catch (error) {
      return {};
    }
  }

  async delWithPattern(pattern: string): Promise<boolean> {
    if (!this.redis) return false;
    try {
      const keys = await this.redis.keys(pattern);
      if (keys.length === 0) return false;
      const result = await this.redis.del(keys);
      return result > 0;
    } catch (error) {
      return false;
    }
  }

  async increment(key: string, amount: number = 1, ttl?: number): Promise<number> {
    if (!this.redis) return 0;
    try {
      const current = await this.redis.get(key);
      const val = (current ? parseInt(current) : 0) + amount;
      await this.redis.set(key, val.toString());
      if (ttl) await this.redis.expire(key, ttl);
      return val;
    } catch (error) {
      return 0;
    }
  }

  async decrement(key: string, amount: number = 1): Promise<number> {
    if (!this.redis) return 0;
    try {
      const current = await this.redis.get(key);
      const val = Math.max(0, (current ? parseInt(current) : 0) - amount);
      await this.redis.set(key, val.toString());
      return val;
    } catch (error) {
      return 0;
    }
  }

  async listPush(key: string, item: any | any[]): Promise<boolean> {
    if (!this.redis) return false;
    try {
      const current = await this.redis.get(key);
      const list = current ? JSON.parse(current) : [];
      if (Array.isArray(item)) {
        list.push(...item);
      } else {
        list.push(item);
      }
      await this.redis.set(key, JSON.stringify(list));
      return true;
    } catch (error) {
      return false;
    }
  }

  async listPop(key: string): Promise<any | null> {
    if (!this.redis) return null;
    try {
      const current = await this.redis.get(key);
      if (!current) return null;
      const list = JSON.parse(current);
      if (list.length === 0) return null;
      const item = list.pop();
      await this.redis.set(key, JSON.stringify(list));
      return item;
    } catch (error) {
      return null;
    }
  }

  async listGetRange(key: string, start: number, end: number): Promise<any[]> {
    if (!this.redis) return [];
    try {
      const current = await this.redis.get(key);
      if (!current) return [];
      const list = JSON.parse(current);
      return list.slice(start, end + 1);
    } catch (error) {
      return [];
    }
  }

  async clear(): Promise<boolean> {
    if (!this.redis) return false;
    try {
      await this.redis.flushall();
      return true;
    } catch (error) {
      return false;
    }
  }

  async healthCheck(): Promise<any> {
    if (!this.redis) return { status: 'unhealthy', error: 'Redis client not initialized' };
    try {
      const ping = await this.redis.ping();
      const info = await this.redis.info();
      const dbsize = await this.redis.dbsize();
      const version = info.split('\n').find(line => line.startsWith('redis_version'))?.split(':')[1].trim();
      return {
        status: ping === 'PONG' ? 'healthy' : 'unhealthy',
        redis_version: version,
        total_keys: dbsize
      };
    } catch (error) {
      return { status: 'unhealthy', error: (error as Error).message };
    }
  }

  async getStats(): Promise<any> {
    if (!this.redis) return {};
    try {
      const info = await this.redis.info();
      const dbsize = await this.redis.dbsize();
      const lines = info.split('\n');
      const getVal = (key: string) => lines.find(l => l.startsWith(key))?.split(':')[1].trim();

      const hits = parseInt(getVal('keyspace_hits') || '0');
      const misses = parseInt(getVal('keyspace_misses') || '0');

      return {
        used_memory: getVal('used_memory_human'),
        connected_clients: parseInt(getVal('connected_clients') || '0'),
        total_commands: parseInt(getVal('total_commands_processed') || '0'),
        hit_rate: hits / (hits + misses) || 0,
        total_keys: dbsize
      };
    } catch (error) {
      return {};
    }
  }

  private async getFromNode(node: any, key: string): Promise<any> {
    return this.get(key);
  }

  private async setToNode(node: any, key: string, value: any, ttl: number): Promise<void> {
    node.connectionCount++;
  }

  private async replicateToNodes(key: string, value: any, ttl: number, replicationFactor: number): Promise<void> {
    const nodes = Array.from(this.distributedNodes.values()).filter(n => n.status === 'active');

    for (let i = 0; i < Math.min(replicationFactor, nodes.length); i++) {
      try {
        await this.setToNode(nodes[i], key, value, ttl);
      } catch (error) {
        logger.error(`Failed to replicate to node ${nodes[i].id}:`, error instanceof Error ? error : new Error(String(error)));
      }
    }
  }

  private calculateNextRun(frequency: 'hourly' | 'daily' | 'weekly', timezone?: string): Date {
    const now = new Date();
    const nextRun = new Date(now);

    switch (frequency) {
      case 'hourly':
        nextRun.setHours(nextRun.getHours() + 1);
        nextRun.setMinutes(0, 0, 0);
        break;
      case 'daily':
        nextRun.setDate(nextRun.getDate() + 1);
        nextRun.setHours(2, 0, 0, 0); // 2 AM
        break;
      case 'weekly':
        nextRun.setDate(nextRun.getDate() + 7);
        nextRun.setHours(2, 0, 0, 0); // 2 AM on Sunday
        const day = now.getDay();
        const diff = (7 - day) % 7;
        nextRun.setDate(now.getDate() + diff);
        break;
    }

    return nextRun;
  }
}

