const logger = createLogger('ChatFirstInterface');

/**
 * Supported Chat Platforms
 */
export type ChatPlatform = 'slack' | 'teams' | 'whatsapp' | 'discord' | 'telegram';

/**
 * Message Types
 */
export type MessageType = 'text' | 'image' | 'file' | 'audio' | 'video' | 'reaction' | 'thread' | 'command';

/**
 * Platform Connection Status
 */
export type ConnectionStatus = 'connected' | 'disconnected' | 'error' | 'pending';

/**
 * Platform Connection Configuration
 */
export interface PlatformConnection {
  id: string;
  agentId: string;
  organizationId: string;
  platform: ChatPlatform;
  status: ConnectionStatus;
  credentials: {
    botToken?: string;
    appToken?: string;
    signingSecret?: string;
    apiKey?: string;
    webhookUrl?: string;
    phoneNumber?: string;
    sessionData?: string;
  };
  settings: {
    autoReply: boolean;
    replyDelayMs: number;
    mentionRequired: boolean;
    allowedChannels?: string[];
    allowedUsers?: string[];
    blockedUsers?: string[];
    welcomeMessage?: string;
    farewellMessage?: string;
    commandPrefix: string;
    maxMessageLength: number;
    threadDepth: number;
  };
  webhooks: {
    incoming: string;
    outgoing?: string;
  };
  stats: {
    messagesReceived: number;
    messagesSent: number;
    errors: number;
    lastMessageAt?: Date;
  };
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Chat Message
 */
export interface ChatMessage {
  id: string;
  platform: ChatPlatform;
  connectionId: string;
  externalId: string; // Platform-specific message ID
  externalThreadId?: string;
  channelId: string;
  channelName?: string;
  userId: string;
  externalUserId: string;
  userName: string;
  userAvatar?: string;
  type: MessageType;
  content: string;
  attachments?: {
    type: string;
    url: string;
    name: string;
    size?: number;
  }[];
  reactions?: {
    emoji: string;
    count: number;
    users: string[];
  }[];
  replyTo?: string;
  mentions: string[];
  isDirectMessage: boolean;
  timestamp: Date;
  metadata: Record<string, unknown>;
  processed: boolean;
  agentResponse?: string;
  responseTime?: number;
}

/**
 * User Mapping
 */
export interface ChatUserMapping {
  id: string;
  platform: ChatPlatform;
  externalUserId: string;
  internalUserId?: string;
  organizationId: string;
  userName: string;
  userEmail?: string;
  profile?: Record<string, unknown>;
