}

/**
 * Platform Command
 */
export interface PlatformCommand {
  name: string;
  description: string;
  syntax: string;
  parameters: {
    name: string;
    required: boolean;
    type: 'string' | 'number' | 'boolean' | 'mention' | 'channel';
    description: string;
  }[];
  permissionLevel: 'all' | 'member' | 'admin';
  handler: (message: ChatMessage, args: Record<string, string>, context: CommandContext) => Promise<string>;
