        `Topic: ${topic || 'general engagement'}. ` +
        `Target audience: ${Object.entries(account.stats.demographics?.interests || {}).slice(0, 3).map(([k]) => k).join(', ')}. ` +
        `Prompt: ${prompt || 'Create engaging content'}`,
