  async bulkUploadFiles(organizationId: string, userId: string, files: {
    filename: string;
    content: Buffer | string;
    mimeType?: string;
    metadata?: Record<string, any>;
  }[]): Promise<{
    successful: {
      fileId: string;
      filename: string;
      size: number;
      url: string;
    }[];
    failed: {
      filename: string;
      error: string;
    }[];
    summary: {
      totalFiles: number;
      uploadedFiles: number;
      failedFiles: number;
      totalSize: number;
      uploadTime: number;
    };
  }> {
    try {
      const startTime = Date.now();
      const successful = [];
      const failed = [];
      let totalSize = 0;

      for (const file of files) {
        try {
          const uploadResult = await this.uploadFile(
            organizationId,
            userId,
            file.filename,
            file.content,
            file.mimeType,
            file.metadata
          );

          successful.push({
            fileId: uploadResult.fileId,
            filename: file.filename,
            size: uploadResult.size,
            url: uploadResult.url
          });

          totalSize += uploadResult.size;
        } catch (error) {
          failed.push({
            filename: file.filename,
            error: error instanceof Error ? error.message : 'Unknown error'
          });
        }
      }

      const uploadTime = Date.now() - startTime;

      this.emit('bulk:upload:completed', {
        organizationId,
        userId,
        summary: {
          totalFiles: files.length,
          uploadedFiles: successful.length,
          failedFiles: failed.length,
          totalSize,
          uploadTime
        }
      });

      return {
        successful,
        failed,
        summary: {
          totalFiles: files.length,
          uploadedFiles: successful.length,
          failedFiles: failed.length,
          totalSize,
          uploadTime
        }
      };
    } catch (error) {
      logger.error('[FileManagementService] Failed to bulk upload files:', error);
      throw error;
    }
  }

  async bulkDeleteFiles(organizationId: string, fileIds: string[]): Promise<{
    successful: string[];
    failed: {
      fileId: string;
      error: string;
    }[];
    summary: {
      totalFiles: number;
      deletedFiles: number;
      failedFiles: number;
      recoveredSpace: number;
    };
  }> {
    try {
      const successful = [];
      const failed = [];
      let recoveredSpace = 0;

      for (const fileId of fileIds) {
        try {
          const file = await this.getFile(organizationId, fileId);
          if (file) {
            await this.deleteFile(organizationId, fileId);
            successful.push(fileId);
            recoveredSpace += file.size;
          }
        } catch (error) {
          failed.push({
            fileId,
            error: error instanceof Error ? error.message : 'Unknown error'
          });
        }
      }

      this.emit('bulk:delete:completed', {
        organizationId,
        summary: {
          totalFiles: fileIds.length,
          deletedFiles: successful.length,
          failedFiles: failed.length,
          recoveredSpace
        }
      });

      return {
        successful,
        failed,
        summary: {
          totalFiles: fileIds.length,
          deletedFiles: successful.length,
          failedFiles: failed.length,
          recoveredSpace
        }
      };
    } catch (error) {
      logger.error('[FileManagementService] Failed to bulk delete files:', error);
      throw error;
    }
  }

