        },
        status: 'success',
      });

      return { invoice: updatedInvoice, stripeInvoice };
    } catch (error) {
      logger.error('[InvoiceService] Failed to finalize invoice:', error);
      throw new Error(`Failed to finalize invoice: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

