  async bulkGenerateInvoices(requests: {
    customerId: string;
    items: {
      description: string;
      quantity: number;
      unitAmount: number;
      currency: string;
    }[];
  }[]): Promise<{
    successful: {
      id: string;
      number: string;
      customer: string;
      amount: number;
      status: string;
    }[];
    failed: {
      customerId: string;
      error: string;
    }[];
    summary: {
      totalInvoices: number;
      generatedInvoices: number;
      failedInvoices: number;
      totalAmount: number;
    };
  }> {
    // Check bulk size limit
    if (requests.length > 100) {
      throw new Error('Bulk size exceeds maximum');
    }

    const successful: any[] = [];
    const failed: any[] = [];
    let totalAmount = 0;

    for (const request of requests) {
      try {
        const invoice = await this.generateInvoice(request);
        successful.push(invoice);
        totalAmount += invoice.amount;
      } catch (error) {
        failed.push({
          customerId: request.customerId,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    return {
      successful,
      failed,
      summary: {
        totalInvoices: requests.length,
        generatedInvoices: successful.length,
        failedInvoices: failed.length,
        totalAmount
      }
    };
  }

