  async calculateTaxes(data: {
    amount: number;
    currency: string;
    country?: string;
    province?: string;
    taxExempt?: boolean;
    exemptionReason?: string;
  }): Promise<{
    subtotal: number;
    taxRates: {
      name: string;
      rate: number;
      amount: number;
      type: string;
    }[];
    totalTax: number;
    total: number;
    taxExempt?: boolean;
    exemptionReason?: string;
  }> {
    if (data.taxExempt) {
      return {
        subtotal: data.amount,
        taxRates: [],
        totalTax: 0,
        total: data.amount,
        taxExempt: true,
        exemptionReason: data.exemptionReason
      };
    }

    const taxRates = [];
    let totalTax = 0;

    if (data.country === 'CA') {
      const gst = data.amount * 0.10;
      const pst = data.amount * 0.07;
      taxRates.push(
        { name: 'GST', rate: 0.10, amount: gst, type: 'percentage' },
        { name: 'PST', rate: 0.07, amount: pst, type: 'percentage' }
      );
      totalTax = gst + pst;
    } else {
      const tax = data.amount * 0.08;
      taxRates.push({ name: 'Sales Tax', rate: 0.08, amount: tax, type: 'percentage' });
      totalTax = tax;
    }

    return {
      subtotal: data.amount,
      taxRates,
      totalTax,
      total: data.amount + totalTax
    };
  }

