        }
      ]
    };
  }

  async calculateInvoiceMetrics(organizationId: string): Promise<{
    totalRevenue: number;
    totalInvoices: number;
    averageInvoiceValue: number;
    medianInvoiceValue: number;
    paymentRate: number;
    averageDaysToPay: number;
