      badDebtRate: 0.02,
      customerRetentionRate: 0.85,
      invoiceGrowthRate: 0.15
    };
  }

  async validateInvoiceData(data: {
    customerId: string;
    items: {
      description: string;
      quantity: number;
      unitAmount: number;
      currency: string;
    }[];
    dueDate?: Date;
  }): Promise<{
    valid: boolean;
    errors: {
      field: string;
      message: string;
      severity: string;
    }[];
    warnings: {
      field: string;
      message: string;
      severity: string;
    }[];
    suggestions: {
      field: string;
      message: string;
      impact: string;
    }[];
  }> {
    const errors: any[] = [];
    const warnings: any[] = [];
    const suggestions: any[] = [];

    // Validate customer
    if (!data.customerId || data.customerId.trim() === '') {
      errors.push({
        field: 'customer_id',
        message: 'Customer ID is required',
        severity: 'error'
      });
    }

    // Validate items
    if (!data.items || data.items.length === 0) {
      errors.push({
        field: 'items',
        message: 'At least one item is required',
        severity: 'error'
      });
    }

    // Add suggestion for long due date
    if (data.dueDate) {
      const daysUntilDue = Math.ceil((data.dueDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
      if (daysUntilDue > 30) {
        suggestions.push({
          field: 'due_date',
          message: 'Consider setting a shorter due date',
          impact: 'improve_cash_flow'
        });
      }
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      suggestions
    };
  }
}

