          failed++;
          results.push({
            recipient,
            status: 'failed' as const,
            error: error instanceof Error ? error.message : 'Unknown error'
          });
        }
      }

      return {
        sent,
        failed,
        results
      };
    } catch (error) {
      logger.error('[NotificationService] Failed to send campaign notification:', error);
      throw error;
    }
  }

