export class PaymentMethodService {
  async createPaymentMethod(params: CreatePaymentMethodParams): Promise<Stripe.PaymentMethod> {
    try {
      // Get organization's Stripe customer ID
      const [organization] = await pgDb
        .select()
        .from(organizations)
        .where(eq(organizations.id, params.organizationId))
        .limit(1);

      if (!organization?.metadata?.stripeCustomerId) {
        throw new Error('Organization does not have a Stripe customer ID');
      }

      let paymentMethod: Stripe.PaymentMethod;

      if (params.type === 'card' && params.card) {
        // Create card payment method
        paymentMethod = await stripe.paymentMethods.create({
          type: 'card',
          card: {
            number: params.card.number,
            exp_month: params.card.exp_month,
            exp_year: params.card.exp_year,
            cvc: params.card.cvc,
          },
          metadata: {
            organizationId: params.organizationId,
            userId: params.userId,
            ...params.metadata,
          },
        });
      } else if (params.type === 'bank_account' && params.bank_account) {
        // Create bank account payment method
        paymentMethod = await stripe.paymentMethods.create({
          type: 'bank_account',
          bank_account: {
            country: params.bank_account.country,
            currency: params.bank_account.currency,
            account_number: params.bank_account.account_number,
            routing_number: params.bank_account.routing_number,
            account_holder_name: params.bank_account.account_holder_name,
          },
          metadata: {
            organizationId: params.organizationId,
            userId: params.userId,
            ...params.metadata,
          },
        });
      } else {
        throw new Error('Invalid payment method parameters');
      }

      // Attach payment method to customer
      await stripe.paymentMethods.attach(paymentMethod.id, {
        customer: organization.metadata.stripeCustomerId,
      });

      // Set as default if requested
      if (params.is_default) {
        await stripe.customers.update(organization.metadata.stripeCustomerId, {
          invoice_settings: {
            default_payment_method: paymentMethod.id,
          },
        });
      }

      logAudit({
        organizationId: params.organizationId,
        action: AuditActions.PAYMENT_METHOD_ADDED,
        resource: 'payment_method',
        resourceId: paymentMethod.id,
        metadata: { 
          type: params.type,
          userId: params.userId,
          isDefault: params.is_default,
        },
        status: 'success',
      });

      return paymentMethod;
    } catch (error) {
      logger.error('[PaymentMethodService] Create payment method failed:', error);
      throw new Error(`Failed to create payment method: ${error.message}`);
    }
  }

  async createSetupIntent(params: SetupIntentParams): Promise<Stripe.SetupIntent> {
    try {
      // Get organization's Stripe customer ID
      const [organization] = await pgDb
        .select()
        .from(organizations)
        .where(eq(organizations.id, params.organizationId))
        .limit(1);

      if (!organization?.metadata?.stripeCustomerId) {
        throw new Error('Organization does not have a Stripe customer ID');
      }

      const setupIntent = await stripe.setupIntents.create({
        customer: organization.metadata.stripeCustomerId,
        payment_method_types: params.payment_method_types || ['card'],
        usage: params.usage || 'off_session',
        metadata: {
          organizationId: params.organizationId,
          userId: params.userId,
          ...params.metadata,
        },
      });

      logAudit({
        organizationId: params.organizationId,
        action: AuditActions.SETUP_INTENT_CREATED,
        resource: 'setup_intent',
        resourceId: setupIntent.id,
        metadata: { 
          userId: params.userId,
          paymentMethodTypes: params.payment_method_types,
        },
        status: 'success',
      });

      return setupIntent;
    } catch (error) {
      logger.error('[PaymentMethodService] Create setup intent failed:', error);
      throw new Error(`Failed to create setup intent: ${error.message}`);
    }
  }

  async getPaymentMethods(organizationId: string): Promise<PaymentMethodInfo[]> {
    try {
      // Get organization's Stripe customer ID
      const [organization] = await pgDb
        .select()
        .from(organizations)
        .where(eq(organizations.id, organizationId))
        .limit(1);

      if (!organization?.metadata?.stripeCustomerId) {
        throw new Error('Organization does not have a Stripe customer ID');
      }

      const paymentMethods = await stripe.paymentMethods.list({
        customer: organization.metadata.stripeCustomerId,
        type: 'card',
      });

      // Get customer's default payment method
      const customer = await stripe.customers.retrieve(organization.metadata.stripeCustomerId);
      const defaultPaymentMethodId = (customer as Stripe.Customer).invoice_settings?.default_payment_method as string;

      return paymentMethods.data.map(method => ({
        id: method.id,
        type: method.type as any,
        last4: method.card?.last4,
        brand: method.card?.brand,
        exp_month: method.card?.exp_month,
        exp_year: method.card?.exp_year,
        fingerprint: method.card?.fingerprint,
        is_default: method.id === defaultPaymentMethodId,
        created: method.created,
        metadata: method.metadata,
      }));
    } catch (error) {
      logger.error('[PaymentMethodService] Get payment methods failed:', error);
      throw new Error(`Failed to get payment methods: ${error.message}`);
    }
  }

  async setDefaultPaymentMethod(organizationId: string, paymentMethodId: string): Promise<void> {
    try {
      // Get organization's Stripe customer ID
      const [organization] = await pgDb
        .select()
        .from(organizations)
        .where(eq(organizations.id, organizationId))
        .limit(1);

      if (!organization?.metadata?.stripeCustomerId) {
        throw new Error('Organization does not have a Stripe customer ID');
      }

      // Verify payment method belongs to this customer
      const paymentMethod = await stripe.paymentMethods.retrieve(paymentMethodId);
      if (paymentMethod.customer !== organization.metadata.stripeCustomerId) {
        throw new Error('Payment method does not belong to this organization');
      }

      // Update customer's default payment method
      await stripe.customers.update(organization.metadata.stripeCustomerId, {
        invoice_settings: {
          default_payment_method: paymentMethodId,
        },
      });

      logAudit({
        organizationId,
        action: AuditActions.PAYMENT_METHOD_UPDATED,
        resource: 'payment_method',
        resourceId: paymentMethodId,
        metadata: { action: 'set_default' },
        status: 'success',
      });
    } catch (error) {
      logger.error('[PaymentMethodService] Set default payment method failed:', error);
      throw new Error(`Failed to set default payment method: ${error.message}`);
    }
  }

  async deletePaymentMethod(organizationId: string, paymentMethodId: string): Promise<void> {
    try {
      // Get organization's Stripe customer ID
      const [organization] = await pgDb
        .select()
        .from(organizations)
        .where(eq(organizations.id, organizationId))
        .limit(1);

      if (!organization?.metadata?.stripeCustomerId) {
        throw new Error('Organization does not have a Stripe customer ID');
      }

      // Verify payment method belongs to this customer
      const paymentMethod = await stripe.paymentMethods.retrieve(paymentMethodId);
      if (paymentMethod.customer !== organization.metadata.stripeCustomerId) {
        throw new Error('Payment method does not belong to this organization');
      }

      // Detach payment method
      await stripe.paymentMethods.detach(paymentMethodId);

      logAudit({
        organizationId,
        action: AuditActions.PAYMENT_METHOD_DELETED,
        resource: 'payment_method',
        resourceId: paymentMethodId,
        metadata: { action: 'detached' },
        status: 'success',
      });
    } catch (error) {
      logger.error('[PaymentMethodService] Delete payment method failed:', error);
      throw new Error(`Failed to delete payment method: ${error.message}`);
    }
  }

  async validatePaymentMethod(paymentMethodId: string): Promise<{
    isValid: boolean;
    isExpired: boolean;
    brand?: string;
    last4?: string;
    funding?: string;
  }> {
    try {
      const paymentMethod = await stripe.paymentMethods.retrieve(paymentMethodId);

      if (paymentMethod.type !== 'card') {
        return { isValid: true };
      }

      const card = paymentMethod.card;
      if (!card) {
        return { isValid: false };
      }

      const now = new Date();
      const currentYear = now.getFullYear();
      const currentMonth = now.getMonth() + 1;

      const isExpired = card.exp_year < currentYear || 
        (card.exp_year === currentYear && card.exp_month < currentMonth);

      return {
        isValid: !isExpired,
        isExpired,
        brand: card.brand,
        last4: card.last4,
        funding: card.funding,
      };
    } catch (error) {
      logger.error('[PaymentMethodService] Validate payment method failed:', error);
      return { isValid: false };
    }
  }
}

export const paymentMethodService = new PaymentMethodService();

import { db as pgDb } from '../db/connection';
import { payments, subscriptions, invoices } from '../db/drizzle-schema';
import { eq, and } from 'drizzle-orm';
import crypto from 'crypto';


import { createLogger } from '../lib/production-logger';

const logger = createLogger(__filename.split('/').pop()?.replace('.ts', '') || 'Service');

// Lazy load Stripe to avoid import errors when not installed
let Stripe: any;
try {
  Stripe = require('stripe');
} catch (e) {
  // Stripe not available, will be mocked in tests
}

export interface PaymentIntent {
  id: string;
  organizationId: string;
  amount: number;
  currency: string;
  status: 'pending' | 'processing' | 'succeeded' | 'failed' | 'canceled';
  paymentMethodId?: string;
  invoiceId?: string;
  description?: string;
  metadata: Record<string, any>;
  clientSecret?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface PaymentMethod {
  id: string;
  organizationId: string;
  type: 'card' | 'bank_account';
  brand?: string;
  last4?: string;
  expiryMonth?: number;
  expiryYear?: number;
  isDefault: boolean;
  stripePaymentMethodId: string;
  metadata: Record<string, any>;
  createdAt: Date;
}

export interface Refund {
  id: string;
  organizationId: string;
  paymentId: string;
  amount: number;
  reason: string;
  status: 'pending' | 'succeeded' | 'failed';
  metadata: Record<string, any>;
  createdAt: Date;
}

export class PaymentService {
  private stripe: any;

  constructor() {
    // Allow constructor to work in tests without env var
    if (process.env.STRIPE_SECRET_KEY && Stripe) {
      this.stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
        apiVersion: '2024-06-20'
      });
    }
  }

  async createPaymentIntent(organizationId: string, params: {
    amount: number;
    currency?: string;
    paymentMethodId?: string;
    invoiceId?: string;
    description?: string;
    metadata?: Record<string, any>;
    confirmImmediately?: boolean;
  }): Promise<PaymentIntent> {
    const id = crypto.randomUUID();
    const now = new Date();

    try {
      const stripeParams: any = {
        amount: Math.round(params.amount * 100), // Convert to cents
        currency: params.currency || 'usd',
        description: params.description,
        metadata: {
          organizationId,
          invoiceId: params.invoiceId,
          ...params.metadata
        },
        automatic_payment_methods: {
          enabled: true
        }
      };

      if (params.paymentMethodId) {
        stripeParams.payment_method = params.paymentMethodId;
        stripeParams.confirm = params.confirmImmediately || false;
      }

      const stripeIntent = await this.stripe.paymentIntents.create(stripeParams);

      const paymentIntent: PaymentIntent = {
        id,
        organizationId,
        amount: params.amount,
        currency: params.currency || 'USD',
        status: this.mapStripeStatus(stripeIntent.status),
        paymentMethodId: params.paymentMethodId,
        invoiceId: params.invoiceId,
        description: params.description,
        metadata: stripeIntent.metadata || {},
        clientSecret: stripeIntent.client_secret,
        createdAt: now,
        updatedAt: now
      };

      // Store in database
      await pgDb.insert(payments).values({
        id: paymentIntent.id,
        organizationId: paymentIntent.organizationId,
        amount: paymentIntent.amount.toString(),
        currency: paymentIntent.currency,
        status: paymentIntent.status,
        paymentMethodId: paymentIntent.paymentMethodId,
        invoiceId: paymentIntent.invoiceId,
        description: paymentIntent.description,
        metadata: paymentIntent.metadata,
        clientSecret: paymentIntent.clientSecret,
        createdAt: paymentIntent.createdAt,
        updatedAt: paymentIntent.updatedAt
      } as any);

      return paymentIntent;
    } catch (error) {
      logger.error('[PaymentService] Failed to create payment intent:', error);
      throw new Error(`Payment intent creation failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  async confirmPayment(paymentIntentId: string, organizationId: string): Promise<PaymentIntent> {
    try {
      // Get payment from database
      const [payment] = await pgDb
        .select()
        .from(payments)
        .where(and(
          eq(payments.id, paymentIntentId),
          eq(payments.organizationId, organizationId)
        ))
        .limit(1);

      if (!payment) {
        throw new Error('Payment not found');
      }

      const stripePaymentId = payment.transactionId;
      if (!stripePaymentId) {
        throw new Error('Stripe payment ID not found');
      }

      // Confirm with Stripe
      const confirmedIntent = await this.stripe.paymentIntents.confirm(stripePaymentId);

      // Update database
      await pgDb
        .update(payments)
        .set({
          status: this.mapStripeStatus(confirmedIntent.status),
          gatewayResponse: confirmedIntent,
          processedAt: new Date(),
          updatedAt: new Date()
        } as any)
        .where(eq(payments.id, paymentIntentId));

      return {
        id: payment.id,
        organizationId: payment.organizationId,
        amount: parseFloat(payment.amount.toString()),
        currency: payment.currency,
        status: this.mapStripeStatus(confirmedIntent.status),
        paymentMethodId: undefined,
        invoiceId: payment.invoiceId,
        description: undefined,
        metadata: (payment.metadata as any) || {},
        createdAt: payment.createdAt,
        updatedAt: new Date()
      };

    } catch (error) {
      if (error instanceof Error && error.message === 'Payment not found') {
        throw error;
      }
      logger.error('Failed to confirm payment:', error);
      throw new Error('Failed to confirm payment');
    }
  }

  async createPaymentMethod(organizationId: string, params: {
    paymentMethodId: string;
    isDefault?: boolean;
  }): Promise<PaymentMethod> {
    const id = crypto.randomUUID();
    const now = new Date();

    try {
      const stripePaymentMethod = await this.stripe.paymentMethods.retrieve(params.paymentMethodId);

      const paymentMethod: PaymentMethod = {
        id,
        organizationId,
        type: stripePaymentMethod.type as PaymentMethod['type'],
        brand: (stripePaymentMethod.card as any)?.brand,
        last4: (stripePaymentMethod.card as any)?.last4,
        expiryMonth: (stripePaymentMethod.card as any)?.exp_month,
        expiryYear: (stripePaymentMethod.card as any)?.exp_year,
        isDefault: params.isDefault || false,
        stripePaymentMethodId: params.paymentMethodId,
        metadata: {},
        createdAt: now
      };

      // Store encrypted payment method details
      await pgDb.insert(payments).values({
        id: paymentMethod.id,
        organizationId: paymentMethod.organizationId,
        amount: '0',
        currency: 'USD',
        method: 'payment_method_setup',
        transactionId: params.paymentMethodId,
        status: 'succeeded',
        paymentMethodDetailsEncrypted: {
          type: paymentMethod.type,
          brand: paymentMethod.brand,
          last4: paymentMethod.last4,
          expiryMonth: paymentMethod.expiryMonth,
          expiryYear: paymentMethod.expiryYear
        },
        metadata: {
          isDefault: paymentMethod.isDefault
        },
        createdAt: paymentMethod.createdAt
      } as any);

      return paymentMethod;

    } catch (error) {
      logger.error('Failed to create payment method:', error);
      throw new Error('Failed to create payment method');
    }
  }

  async getPaymentMethods(organizationId: string): Promise<PaymentMethod[]> {
    const results = await pgDb
      .select()
      .from(payments)
      .where(and(
        eq(payments.organizationId, organizationId),
        eq(payments.method, 'payment_method_setup'),
        eq(payments.status, 'succeeded')
      ))
      .orderBy(payments.createdAt);

    return results.map(payment => {
      const details = payment.paymentMethodDetailsEncrypted as any;
      return {
        id: payment.id,
        organizationId: payment.organizationId,
        type: details?.type || 'card',
        brand: details?.brand,
        last4: details?.last4,
        expiryMonth: details?.expiryMonth,
        expiryYear: details?.expiryYear,
        isDefault: (payment.metadata as any)?.isDefault || false,
        stripePaymentMethodId: payment.transactionId || '',
        metadata: (payment.metadata as any) || {},
        createdAt: payment.createdAt
      };
    });
  }

  async createRefund(organizationId: string, params: {
    paymentId: string;
    amount?: number;
    reason: string;
  }): Promise<Refund> {
    const id = crypto.randomUUID();
    const now = new Date();

    try {
      // Get original payment
      const [payment] = await pgDb
        .select()
        .from(payments)
        .where(and(
          eq(payments.id, params.paymentId),
          eq(payments.organizationId, organizationId)
        ))
        .limit(1);

      if (!payment) {
        throw new Error('Payment not found');
      }

      const stripePaymentId = payment.transactionId;
      if (!stripePaymentId) {
        throw new Error('Stripe payment ID not found');
      }

      // Create refund in Stripe
      const refundAmount = params.amount ? Math.round(params.amount * 100) : Math.round(parseFloat(payment.amount.toString()) * 100);
      const stripeRefund = await this.stripe.refunds.create({
        payment_intent: stripePaymentId,
        amount: refundAmount,
        reason: params.reason as Stripe.RefundCreateParams.Reason
      });

      const refund: Refund = {
        id,
        organizationId,
        paymentId: params.paymentId,
        amount: refundAmount / 100, // Convert back from cents
        reason: params.reason,
        status: stripeRefund.status === 'succeeded' ? 'succeeded' : 'pending',
        metadata: {
          stripeRefundId: stripeRefund.id
        },
        createdAt: now
      };

      // Store refund record
      await pgDb.insert(payments).values({
        id: refund.id,
        organizationId: refund.organizationId,
        invoiceId: payment.invoiceId,
        amount: refund.amount.toString(),
        currency: payment.currency,
        method: 'refund',
        transactionId: stripeRefund.id,
        status: refund.status,
        gatewayResponse: stripeRefund,
        metadata: refund.metadata,
        createdAt: refund.createdAt
      } as any);

      return refund;

    } catch (error) {
      logger.error('Failed to create refund:', error);
      throw new Error('Failed to create refund');
    }
  }

  async getPaymentHistory(organizationId: string, options: {
    limit?: number;
    offset?: number;
    status?: string;
  } = {}): Promise<{ payments: PaymentIntent[]; total: number }> {
    const conditions = [eq(payments.organizationId, organizationId)];

    if (options.status) {
      conditions.push(eq(payments.status, options.status));
    }

    const baseQuery = pgDb
      .select()
      .from(payments)
      .where(and(...conditions));

    // Get total count
    const totalResults = await baseQuery;
    const total = totalResults.length;

    // Apply pagination and ordering
    let query = pgDb
      .select()
      .from(payments)
      .where(and(...conditions))
      .orderBy(payments.createdAt);

    if (options.limit) {
      query = query.limit(options.limit);
    }
    if (options.offset) {
      query = query.offset(options.offset);
    }

    const results = await query;

    const payments = results.map(payment => ({
      id: payment.id,
      organizationId: payment.organizationId,
      amount: parseFloat(payment.amount.toString()),
      currency: payment.currency,
      status: payment.status as PaymentIntent['status'],
      paymentMethodId: undefined,
      invoiceId: payment.invoiceId,
      description: undefined,
      metadata: (payment.metadata as any) || {},
      createdAt: payment.createdAt,
      updatedAt: payment.updatedAt
    }));

    return { payments, total };
  }

  async getPaymentStats(organizationId: string): Promise<{
    totalRevenue: number;
    totalPayments: number;
    successfulPayments: number;
    failedPayments: number;
    refundAmount: number;
  }> {
    const results = await pgDb
      .select()
      .from(payments)
      .where(eq(payments.organizationId, organizationId));

    let totalRevenue = 0;
    let totalPayments = 0;
    let successfulPayments = 0;
    let failedPayments = 0;
    let refundAmount = 0;

    results.forEach(payment => {
      const amount = parseFloat(payment.amount?.toString() || '0');

      if (payment.method === 'refund') {
        refundAmount += amount;
      } else {
        totalPayments++;
        if (payment.status === 'succeeded') {
          totalRevenue += amount;
          successfulPayments++;
        } else if (payment.status === 'failed') {
          failedPayments++;
        }
      }
    });

    return {
      totalRevenue: totalRevenue,
      totalPayments,
      successfulPayments,
      failedPayments,
      refundAmount
    };
  }

  private mapStripeStatus(stripeStatus: string): PaymentIntent['status'] {
    switch (stripeStatus) {
      case 'requires_payment_method':
      case 'requires_confirmation':
      case 'requires_action':
        return 'pending';
      case 'processing':
        return 'processing';
      case 'succeeded':
        return 'succeeded';
      case 'canceled':
        return 'canceled';
      default:
        return 'failed';
    }
  }

  async handleWebhook(event: Stripe.Event): Promise<void> {
    switch (event.type) {
      case 'payment_intent.succeeded':
        await this.handlePaymentSucceeded(event.data.object as Stripe.PaymentIntent);
        break;
      case 'payment_intent.payment_failed':
        await this.handlePaymentFailed(event.data.object as Stripe.PaymentIntent);
        break;
      case 'payment_intent.canceled':
        await this.handlePaymentCanceled(event.data.object as Stripe.PaymentIntent);
        break;
      default:
        logger.info(`Unhandled webhook event type: ${event.type}`);
    }
  }

  private async handlePaymentSucceeded(paymentIntent: Stripe.PaymentIntent): Promise<void> {
    const organizationId = paymentIntent.metadata.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(payments)
      .set({
        status: 'succeeded',
        processedAt: new Date()
      })
      .where(and(
        eq(payments.transactionId, paymentIntent.id),
        eq(payments.organizationId, organizationId)
      ));
  }

  private async handlePaymentFailed(paymentIntent: Stripe.PaymentIntent): Promise<void> {
    const organizationId = paymentIntent.metadata.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(payments)
      .set({
        status: 'failed'
      })
      .where(and(
        eq(payments.transactionId, paymentIntent.id),
        eq(payments.organizationId, organizationId)
      ));
  }

  private async handlePaymentCanceled(paymentIntent: Stripe.PaymentIntent): Promise<void> {
    const organizationId = paymentIntent.metadata.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(payments)
      .set({
        status: 'canceled'
      })
      .where(and(
        eq(payments.transactionId, paymentIntent.id),
        eq(payments.organizationId, organizationId)
      ));
  }
}

export const paymentService = new PaymentService();

import { db as pgDb } from '../db/connection';
import { organizations, subscriptions, invoices, payments, users } from '../db/drizzle-schema';
import { eq, and } from 'drizzle-orm';
import { logAudit, AuditActions } from '../lib/audit';
import { stripeService } from './stripe-service';
import Stripe from 'stripe';


import { createLogger } from '../lib/production-logger';

const logger = createLogger(__filename.split('/').pop()?.replace('.ts', '') || 'Service');

if (!process.env.STRIPE_SECRET_KEY) {
  throw new Error('STRIPE_SECRET_KEY is required for webhook processing');
}

if (!process.env.STRIPE_WEBHOOK_SECRET) {
  throw new Error('STRIPE_WEBHOOK_SECRET is required for webhook processing');
}

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
  apiVersion: '2024-06-20',
});

export class PaymentWebhookService {
  async processWebhook(request: any): Promise<{ success: boolean; message: string }> {
    const body = await request.text();
    const signature = request.headers.get('stripe-signature');

    if (!signature) {
      logger.error('[Webhook] No stripe-signature header found');
      return { success: false, message: 'No signature' };
    }

    let event: Stripe.Event;

    try {
      event = stripe.webhooks.constructEvent(
        body,
        signature,
        process.env.STRIPE_WEBHOOK_SECRET!
      );
    } catch (err) {
      logger.error('[Webhook] Signature verification failed:', err);
      return { success: false, message: 'Invalid signature' };
    }

    logger.info(`Processing event: ${event.type}`);

    try {
      switch (event.type) {
        case 'customer.created':
          await this.handleCustomerCreated(event.data.object as Stripe.Customer);
          break;

        case 'customer.updated':
          await this.handleCustomerUpdated(event.data.object as Stripe.Customer);
          break;

        case 'customer.deleted':
          await this.handleCustomerDeleted(event.data.object as Stripe.Customer);
          break;

        case 'payment_intent.succeeded':
          await this.handlePaymentIntentSucceeded(event.data.object as Stripe.PaymentIntent);
          break;

        case 'payment_intent.payment_failed':
          await this.handlePaymentIntentFailed(event.data.object as Stripe.PaymentIntent);
          break;

        case 'payment_intent.canceled':
          await this.handlePaymentIntentCanceled(event.data.object as Stripe.PaymentIntent);
          break;

        case 'invoice.created':
          await this.handleInvoiceCreated(event.data.object as Stripe.Invoice);
          break;

        case 'invoice.finalized':
          await this.handleInvoiceFinalized(event.data.object as Stripe.Invoice);
          break;

        case 'invoice.payment_succeeded':
          await this.handleInvoicePaymentSucceeded(event.data.object as Stripe.Invoice);
          break;

        case 'invoice.payment_failed':
          await this.handleInvoicePaymentFailed(event.data.object as Stripe.Invoice);
          break;

        case 'invoice.upcoming':
          await this.handleInvoiceUpcoming(event.data.object as Stripe.Invoice);
          break;

        case 'subscription.created':
          await this.handleSubscriptionCreated(event.data.object as Stripe.Subscription);
          break;

        case 'subscription.updated':
          await this.handleSubscriptionUpdated(event.data.object as Stripe.Subscription);
          break;

        case 'subscription.deleted':
          await this.handleSubscriptionDeleted(event.data.object as Stripe.Subscription);
          break;

        case 'subscription.trial_will_end':
          await this.handleSubscriptionTrialWillEnd(event.data.object as Stripe.Subscription);
          break;

        case 'checkout.session.completed':
          await this.handleCheckoutSessionCompleted(event.data.object as Stripe.Checkout.Session);
          break;

        case 'payment_method.attached':
          await this.handlePaymentMethodAttached(event.data.object as Stripe.PaymentMethod);
          break;

        case 'charge.succeeded':
          await this.handleChargeSucceeded(event.data.object as Stripe.Charge);
          break;

        case 'charge.failed':
          await this.handleChargeFailed(event.data.object as Stripe.Charge);
          break;

        case 'account.updated':
          await this.handleAccountUpdated(event.data.object as Stripe.Account);
          break;

        case 'payout.created':
          await this.handlePayoutCreated(event.data.object as Stripe.Payout);
          break;

        case 'payout.paid':
          await this.handlePayoutPaid(event.data.object as Stripe.Payout);
          break;

        case 'payout.failed':
          await this.handlePayoutFailed(event.data.object as Stripe.Payout);
          break;

        default:
          logger.info(`Unhandled event type: ${event.type}`);
      }

      return { success: true, message: 'Event processed successfully' };
    } catch (error) {
      logger.error(`Error processing event ${event.type}:`, error);
      return { success: false, message: 'Processing failed' };
    }
  }

  private async handleCustomerCreated(customer: Stripe.Customer): Promise<void> {
    const organizationId = customer.metadata?.organizationId;
    if (!organizationId) {
      logger.warn('[Webhook] Customer created without organizationId');
      return;
    }

    await pgDb
      .update(organizations)
      .set({
        metadata: {
          stripeCustomerId: customer.id,
          stripeCustomerCreated: new Date().toISOString(),
        }
      })
      .where(eq(organizations.id, organizationId));

    logAudit({
      organizationId,
      action: AuditActions.CUSTOMER_CREATED,
      resource: 'customer',
      resourceId: customer.id,
      metadata: { source: 'webhook' },
      status: 'success',
    });
  }

