  private async handleInvoiceCreated(invoice: Stripe.Invoice): Promise<void> {
    const organizationId = invoice.metadata?.organizationId;
    if (!organizationId) return;

    // Check if invoice already exists
    const [existingInvoice] = await pgDb
      .select()
      .from(invoices)
      .where(and(
        eq(invoices.organizationId, organizationId),
        eq(invoices.invoiceNumber, invoice.number || invoice.id)
      ))
      .limit(1);

    if (!existingInvoice) {
      await pgDb.insert(invoices).values({
        organizationId,
        invoiceNumber: invoice.number || invoice.id,
        status: invoice.status as any,
        amount: (invoice.amount_due / 100).toString(),
        total: (invoice.total / 100).toString(),
        currency: invoice.currency,
        dueDate: invoice.due_date ? new Date(invoice.due_date * 1000) : null,
        metadata: {
          stripeInvoiceId: invoice.id,
          customerId: invoice.customer as string,
          subscriptionId: invoice.subscription as string,
        },
        createdAt: new Date(invoice.created * 1000),
        updatedAt: new Date(),
      });
    }
  }

  private async handleInvoiceFinalized(invoice: Stripe.Invoice): Promise<void> {
    const organizationId = invoice.metadata?.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(invoices)
      .set({
        status: invoice.status as any,
        amount: (invoice.amount_due / 100).toString(),
        total: (invoice.total / 100).toString(),
        updatedAt: new Date(),
      })
      .where(and(
        eq(invoices.organizationId, organizationId),
        eq(invoices.invoiceNumber, invoice.number || invoice.id)
      ));
  }

  private async handleInvoicePaymentSucceeded(invoice: Stripe.Invoice): Promise<void> {
    const organizationId = invoice.metadata?.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(invoices)
      .set({
        status: 'paid',
        paidAt: new Date(),
        transactionId: invoice.payment_intent as string,
        updatedAt: new Date(),
      })
      .where(and(
        eq(invoices.organizationId, organizationId),
        eq(invoices.invoiceNumber, invoice.number || invoice.id)
      ));

    // Update subscription if this is a subscription payment
    if (invoice.subscription) {
      await pgDb
        .update(subscriptions)
        .set({
          status: 'active',
          updatedAt: new Date(),
        })
        .where(and(
          eq(subscriptions.organizationId, organizationId),
          eq(subscriptions.metadata?.stripeSubscriptionId || '', invoice.subscription as string)
        ));
    }

    logAudit({
      organizationId,
      action: AuditActions.INVOICE_PAID,
      resource: 'invoice',
      resourceId: invoice.id,
      metadata: { 
        amount: invoice.amount_paid / 100,
        source: 'webhook'
      },
      status: 'success',
    });
  }

  private async handleInvoicePaymentFailed(invoice: Stripe.Invoice): Promise<void> {
    const organizationId = invoice.metadata?.organizationId;
    if (!organizationId) return;

    await pgDb
      .update(invoices)
      .set({
        status: 'failed',
        updatedAt: new Date(),
      })
      .where(and(
        eq(invoices.organizationId, organizationId),
        eq(invoices.invoiceNumber, invoice.number || invoice.id)
      ));

    // Update subscription status if applicable
    if (invoice.subscription) {
      await pgDb
        .update(subscriptions)
        .set({
          status: 'past_due',
          updatedAt: new Date(),
        })
        .where(and(
          eq(subscriptions.organizationId, organizationId),
          eq(subscriptions.metadata?.stripeSubscriptionId || '', invoice.subscription as string)
        ));
    }

    logAudit({
      organizationId,
      action: AuditActions.INVOICE_PAYMENT_FAILED,
      resource: 'invoice',
      resourceId: invoice.id,
      metadata: { 
        amount: invoice.amount_due / 100,
        source: 'webhook'
      },
      status: 'success',
    });
  }

