  verificationCount: number;
  lastVerifiedAt?: Date;
  expiresAt?: Date;
  relatedMemoryIds: string[];
  tags: string[];
  metadata: Record<string, unknown>;
  accessCount: number;
  lastAccessed: Date;
  createdAt: Date;
  updatedAt: Date;
