export interface IntegrationHealthCheck {
  overall: 'healthy' | 'degraded' | 'unhealthy';
  platforms: PlatformIntegrationStatus[];
  agentMemory: AgentMemoryStatus;
  issues: string[];
  recommendations: string[];
}

export interface SyncOperation {
  id: string;
  platform: PlatformType;
  organizationId: string;
  type: 'full' | 'incremental' | 'webhook';
  status: 'pending' | 'running' | 'completed' | 'failed';
  startTime: Date;
  endTime?: Date;
  recordsProcessed: number;
  errors: string[];
}

export class PlatformIntegrationService {
  private activeSyncs: Map<string, SyncOperation> = new Map();

  async getIntegrationStatus(organizationId: string): Promise<IntegrationHealthCheck> {
    const platforms = await this.getPlatformStatuses(organizationId);
    const agentMemory = await this.getAgentMemoryStatus(organizationId);
    const issues = this.identifyIssues(platforms, agentMemory);
    const recommendations = this.generateRecommendations(platforms, agentMemory, issues);

    const overall = this.calculateOverallHealth(platforms, agentMemory, issues);

    return {
      overall,
      platforms,
      agentMemory,
      issues,
      recommendations,
    };
  }

  async connectPlatform(
    organizationId: string,
    platform: PlatformType,
    authCode: string,
    state: string
  ): Promise<{ success: boolean; connectionId?: string; error?: string }> {
    try {
      // Exchange OAuth code for tokens
      const tokens = await platformAuthService.exchangeOAuthCode(platform, authCode, state);

      // Store credentials
      const platformId = `${platform}_${organizationId}`;
      const stored = await platformAuthService.storeCredentials(
        platformId,
        platform,
        organizationId,
        tokens,
        { organizationId }
      );

      if (!stored) {
        return { success: false, error: 'Failed to store credentials' };
      }

      // Create platform connection record
      const [connection] = await pgDb
        .insert(platformConnections)
        .values({
          organizationId: organizationId as any,
          platform,
          isActive: true,
          metadata: {
            status: 'connected',
            connectedAt: new Date().toISOString(),
            credentialsStored: true,
          },
          createdAt: new Date(),
          updatedAt: new Date(),
        } as any)
        .returning({ id: platformConnections.id });

      // Register webhooks if supported
      try {
        await webhookManager.registerWebhook({
          platform,
          organizationId,
          endpointUrl: `${process.env.API_BASE_URL}/webhooks/${platform}`,
          events: this.getWebhookEvents(platform),
          isActive: true,
        });
      } catch (webhookError) {
        logger.warn(`[PlatformIntegrationService] Failed to register webhooks for ${platform}:`, webhookError);
      }

      return { 
        success: true, 
        connectionId: String((connection as any).id),
      };
    } catch (error) {
      logger.error(`Failed to connect platform ${platform}:`, error);
      return { 
        success: false, 
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  async disconnectPlatform(
    organizationId: string,
    platform: PlatformType
  ): Promise<{ success: boolean; error?: string }> {
    try {
      // Get connection
      const [connection] = await pgDb
        .select()
        .from(platformConnections)
        .where(and(
          eq(platformConnections.organizationId, organizationId as any),
          eq(platformConnections.platform, platform)
        ))
        .limit(1);

      if (!connection) {
        return { success: false, error: 'Platform connection not found' };
      }

      // Unregister webhooks
      try {
        const webhooks = await webhookManager.getWebhooks(organizationId, platform);
        for (const webhook of webhooks) {
          await webhookManager.unregisterWebhook(webhook.id);
        }
      } catch (webhookError) {
        logger.warn(`[PlatformIntegrationService] Failed to unregister webhooks for ${platform}:`, webhookError);
      }

      // Remove credentials
      const platformId = `${platform}_${organizationId}`;
      await platformAuthService.disconnect(organizationId, platformId);

      // Deactivate connection
      await pgDb
        .update(platformConnections)
        .set({ 
          isActive: false, 
          metadata: {
            ...((connection as any).metadata || {}),
            status: 'disconnected',
            disconnectedAt: new Date().toISOString(),
          },
          updatedAt: new Date(),
        } as any)
        .where(eq(platformConnections.id, (connection as any).id));

      return { success: true };
    } catch (error) {
      logger.error(`Failed to disconnect platform ${platform}:`, error);
      return { 
        success: false, 
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  async syncPlatform(
    organizationId: string,
    platform: PlatformType,
    type: 'full' | 'incremental' = 'full'
  ): Promise<SyncOperation> {
    const syncId = this.generateSyncId();
    const syncOperation: SyncOperation = {
      id: syncId,
      platform,
      organizationId,
      type,
      status: 'pending',
      startTime: new Date(),
      recordsProcessed: 0,
      errors: [],
    };

    this.activeSyncs.set(syncId, syncOperation);

    try {
      syncOperation.status = 'running';

      // Get connection
      const [connection] = await pgDb
        .select()
        .from(platformConnections)
        .where(and(
          eq(platformConnections.organizationId, organizationId as any),
          eq(platformConnections.platform, platform)
        ))
        .limit(1);

      if (!connection) {
        throw new Error('Platform connection not found');
      }

      if (!(connection as any).isActive) {
        // Automatically reactivate if we're explicitly trying to sync
        await pgDb
          .update(platformConnections)
          .set({ 
            isActive: true,
            updatedAt: new Date()
          })
          .where(eq(platformConnections.id, (connection as any).id));
      }

      // Perform sync
      const syncResult: SyncResult = await platformSyncService.syncPlatform(
        organizationId,
        platform,
        (connection as any).id
      );

      syncOperation.recordsProcessed = syncResult.recordsProcessed;

      if (!syncResult.success) {
        syncOperation.errors = syncResult.errors;
        throw new Error(`Sync failed: ${syncResult.errors.join(', ')}`);
      }

      // Detect and resolve conflicts
      if (syncResult.recordsProcessed > 0) {
        await this.handleSyncConflicts(organizationId, platform, syncResult);
      }

      syncOperation.status = 'completed';
      syncOperation.endTime = new Date();
    } catch (error) {
      syncOperation.status = 'failed';
      syncOperation.endTime = new Date();
      syncOperation.errors.push(error instanceof Error ? error.message : 'Unknown error');
    }

    this.activeSyncs.delete(syncId);
    return syncOperation;
  }

  async searchAgentMemory(
    agentId: string,
    organizationId: string,
    query: SearchQuery
  ): Promise<any[]> {
    return semanticSearchService.searchMemories(agentId, organizationId, query);
  }

  async getAgentContext(
    agentId: string,
    organizationId: string,
    query: string,
    options?: any
  ): Promise<MemoryContext> {
    return semanticSearchService.retrieveContext(agentId, organizationId, query, options);
  }

  async generateMemorySummary(
    agentId: string,
    organizationId: string,
    type: 'daily' | 'weekly' | 'monthly' | 'topic',
    topic?: string
  ): Promise<any> {
    return memoryManagementService.generateSummary(agentId, organizationId, type, topic);
  }

  async pruneAgentMemory(
    agentId: string,
    organizationId: string
  ): Promise<any> {
    return memoryManagementService.pruneMemories(agentId, organizationId);
  }

  async handleWebhook(
    platform: PlatformType,
    organizationId: string,
    eventId: string,
    eventType: string,
    payload: any,
    headers: Record<string, string>,
    signature?: string
  ): Promise<{ success: boolean; error?: string }> {
    try {
      // Process webhook
      const result = await webhookManager.processIncomingWebhook(
        platform,
        organizationId,
        eventId,
        eventType,
        payload,
        headers,
        signature
      );

      if (!result.success) {
        return result;
      }

      // Trigger incremental sync if needed
      if (this.shouldTriggerSync(eventType)) {
        await this.syncPlatform(organizationId, platform, 'incremental');
      }

      return result;
    } catch (error) {
      logger.error(`Webhook handling failed for ${platform}:`, error);
      return { 
        success: false, 
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  async getSyncOperation(syncId: string): Promise<SyncOperation | undefined> {
    return this.activeSyncs.get(syncId);
  }

  async getActiveSyncs(organizationId: string): Promise<SyncOperation[]> {
    return Array.from(this.activeSyncs.values())
      .filter(sync => sync.organizationId === organizationId && sync.status === 'running');
  }

  // Private helper methods
  private async getPlatformStatuses(organizationId: string): Promise<PlatformIntegrationStatus[]> {
    const platforms: PlatformType[] = [
      'salesforce', 'hubspot', 'slack', 'microsoft_teams', 'google_workspace', 
      'zoom', 'calendly', 'stripe', 'whatsapp', 'instagram', 'facebook', 
      'linkedin', 'twitter', 'telegram', 'signal'
    ];

    const statuses: PlatformIntegrationStatus[] = [];

    for (const platform of platforms) {
      const status = await this.getPlatformStatus(organizationId, platform);
      statuses.push(status);
    }

    return statuses;
  }

  private async getPlatformStatus(organizationId: string, platform: PlatformType): Promise<PlatformIntegrationStatus> {
    try {
      const [connection] = await pgDb
        .select()
        .from(platformConnections)
        .where(and(
          eq(platformConnections.organizationId, organizationId as any),
          eq(platformConnections.platform, platform)
        ))
        .limit(1);

      const isConnected = !!connection;
      const isActive = isConnected && (connection as any).isActive;
      const lastSyncAt = (connection as any)?.lastSyncAt ? new Date((connection as any).lastSyncAt) : undefined;

      const metadata = (connection as any)?.metadata || {};
      const lastSyncResult = metadata.lastSyncResult || {};
      const syncStatus = lastSyncResult.success ? 'success' : 
                        lastSyncResult.errors?.length > 0 ? 'failed' : 
                        lastSyncAt ? 'pending' : 'never';

      // Check credentials status
      const credentials = await platformAuthService.ensureValidCredentialsForOrg(organizationId, platform);
      const credentialsStatus = credentials ? 'valid' : 'missing';

      // Check webhook status
      const webhookStatus = metadata.webhookRegistered ? 'active' : 'inactive';

      // Get record counts
      const totalRecords = lastSyncResult.recordsProcessed || 0;
      const errorCount = lastSyncResult.errors?.length || 0;

      return {
        platform,
        isConnected,
        isActive,
        lastSyncAt,
        syncStatus,
        credentialsStatus,
        webhookStatus,
        totalRecords,
        errorCount,
      };
    } catch (error) {
      return {
        platform,
        isConnected: false,
        isActive: false,
        syncStatus: 'never',
        credentialsStatus: 'missing',
        webhookStatus: 'inactive',
        totalRecords: 0,
        errorCount: 1,
      };
    }
  }

  private async getAgentMemoryStatus(organizationId: string): Promise<AgentMemoryStatus> {
    try {
      // Get stats for all agents in the organization
      const result = await pgDb.execute(`
        SELECT 
          COUNT(*) as total_memories,
          AVG(importance_score) as avg_importance_score,
          MAX(created_at) as newest_memory
        FROM agent_memories
        WHERE organization_id = $1
      `, [organizationId]);

      const contextsResult = await pgDb.execute(`
        SELECT COUNT(*) as total_contexts
        FROM agent_memory_contexts
        WHERE organization_id = $1
      `, [organizationId]);

      const summariesResult = await pgDb.execute(`
        SELECT COUNT(*) as total_summaries, MAX(created_at) as last_summary
        FROM agent_memory_summaries
        WHERE organization_id = $1
      `, [organizationId]);

      const pruningResult = await pgDb.execute(`
        SELECT MAX(completed_at) as last_pruning
        FROM agent_memory_cleanup_jobs
        WHERE organization_id = $1 AND job_type = 'prune' AND status = 'completed'
      `, [organizationId]);

      const row = result.rows[0];
      const contextsRow = contextsResult.rows[0];
      const summariesRow = summariesResult.rows[0];
      const pruningRow = pruningResult.rows[0];

      const totalMemories = parseInt(row.total_memories) || 0;
      const totalContexts = parseInt(contextsRow.total_contexts) || 0;
      const totalSummaries = parseInt(summariesRow.total_summaries) || 0;

      return {
        totalMemories,
        totalContexts,
        totalSummaries,
        avgImportanceScore: parseFloat(row.avg_importance_score) || 0,
        storageUsage: this.estimateStorageUsage(totalMemories, totalContexts, totalSummaries),
        lastSummaryAt: summariesRow.last_summary ? new Date(summariesRow.last_summary) : undefined,
        lastPruningAt: pruningRow.last_pruning ? new Date(pruningRow.last_pruning) : undefined,
      };
    } catch (error) {
      logger.error('[PlatformIntegrationService] Failed to get agent memory status:', error);
      return {
        totalMemories: 0,
        totalContexts: 0,
        totalSummaries: 0,
        avgImportanceScore: 0,
        storageUsage: 0,
      };
    }
  }

  private identifyIssues(platforms: PlatformIntegrationStatus[], agentMemory: AgentMemoryStatus): string[] {
    const issues: string[] = [];

    // Platform issues
    for (const platform of platforms) {
      if (platform.isConnected && !platform.isActive) {
        issues.push(`${platform.platform} connection is inactive`);
      }

      if (platform.credentialsStatus === 'expired' || platform.credentialsStatus === 'reauth_required') {
        issues.push(`${platform.platform} credentials need refresh`);
      }

      if (platform.syncStatus === 'failed') {
        issues.push(`${platform.platform} sync is failing`);
      }

      if (platform.errorCount > 5) {
        issues.push(`${platform.platform} has high error rate`);
      }
    }

    // Memory issues
    if (agentMemory.totalMemories > 50000) {
      issues.push('Agent memory storage is getting large');
    }

    if (agentMemory.lastPruningAt && (Date.now() - agentMemory.lastPruningAt.getTime()) > 7 * 24 * 60 * 60 * 1000) {
      issues.push('Agent memory pruning is overdue');
    }

    if (agentMemory.avgImportanceScore < 1.0) {
      issues.push('Agent memory quality is low');
    }

    return issues;
  }

  private generateRecommendations(
    platforms: PlatformIntegrationStatus[],
    agentMemory: AgentMemoryStatus,
    issues: string[]
  ): string[] {
    const recommendations: string[] = [];

    // Platform recommendations
    const inactivePlatforms = platforms.filter(p => p.isConnected && !p.isActive);
    if (inactivePlatforms.length > 0) {
      recommendations.push('Consider reactivating inactive platform connections');
    }

    const failedPlatforms = platforms.filter(p => p.syncStatus === 'failed');
    if (failedPlatforms.length > 0) {
      recommendations.push('Review and fix platform sync failures');
    }

    const platformsWithoutWebhooks = platforms.filter(p => p.isConnected && p.webhookStatus === 'inactive');
    if (platformsWithoutWebhooks.length > 0) {
      recommendations.push('Enable webhooks for real-time data synchronization');
    }

    // Memory recommendations
    if (agentMemory.totalMemories > 50000) {
      recommendations.push('Run memory pruning to optimize storage');
    }

    if (agentMemory.totalSummaries === 0) {
      recommendations.push('Enable memory summarization for better context retention');
    }

    if (agentMemory.avgImportanceScore < 1.0) {
      recommendations.push('Review memory importance scoring criteria');
    }

    return recommendations;
  }

  private calculateOverallHealth(
    platforms: PlatformIntegrationStatus[],
    agentMemory: AgentMemoryStatus,
    issues: string[]
  ): 'healthy' | 'degraded' | 'unhealthy' {
    const criticalIssues = issues.filter(issue => 
      issue.includes('failed') || issue.includes('expired') || issue.includes('overdue')
    );

    if (criticalIssues.length > 0) {
      return 'unhealthy';
    }

    const activePlatforms = platforms.filter(p => p.isActive).length;
    const totalPlatforms = platforms.filter(p => p.isConnected).length;

    if (totalPlatforms === 0 || activePlatforms / totalPlatforms < 0.5) {
      return 'degraded';
    }

    if (issues.length > 3) {
      return 'degraded';
    }

    return 'healthy';
  }

  private async handleSyncConflicts(
    organizationId: string,
    platform: PlatformType,
    syncResult: SyncResult
  ): Promise<void> {
    // In a real implementation, this would detect and resolve conflicts
    // For now, just log the sync result
    logger.info(`[PlatformIntegrationService] Sync completed for ${platform}:`, syncResult);
  }

  private getWebhookEvents(platform: PlatformType): string[] {
    const eventMap: Record<PlatformType, string[]> = {
      salesforce: ['object.created', 'object.updated', 'object.deleted'],
      hubspot: ['contact.creation', 'contact.deletion', 'company.creation', 'deal.creation'],
      slack: ['message', 'member_joined_channel', 'member_left_channel'],
      microsoft_teams: ['message', 'member_added', 'member_removed'],
      google_workspace: ['calendar.created', 'calendar.updated', 'message.received'],
      zoom: ['meeting.created', 'meeting.updated', 'meeting.ended'],
      calendly: ['invitee.created', 'invitee.canceled'],
      stripe: ['customer.created', 'charge.succeeded', 'invoice.payment_succeeded'],
      whatsapp: ['message', 'message.delivery', 'message.read'],
      instagram: ['comments', 'mentions', 'direct_message'],
      facebook: ['message', 'post', 'comment'],
      linkedin: ['message', 'post', 'comment'],
      twitter: ['tweet', 'mention', 'direct_message'],
      telegram: ['message', 'callback_query'],
      signal: ['message'],
    };

    return eventMap[platform] || [];
  }

  private shouldTriggerSync(eventType: string): boolean {
    const syncTriggeringEvents = [
      'object.created', 'object.updated', 'object.deleted',
      'contact.creation', 'company.creation', 'deal.creation',
      'calendar.created', 'calendar.updated',
      'meeting.created', 'meeting.updated',
      'customer.created', 'charge.succeeded',
    ];

    return syncTriggeringEvents.some(event => eventType.includes(event));
  }

  private estimateStorageUsage(memories: number, contexts: number, summaries: number): number {
    const avgMemorySize = 1000; // 1KB
    const avgContextSize = 500; // 500B
    const avgSummarySize = 2000; // 2KB

    return memories * avgMemorySize + contexts * avgContextSize + summaries * avgSummarySize;
  }

  private generateSyncId(): string {
    return `sync_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

export const platformIntegrationService = new PlatformIntegrationService();

import { WebSocketServer } from 'ws';
import { verifyToken } from '../lib/auth';
import { db as pgDb } from '../db/connection';
import { realtimeClientState, realtimeEvents, realtimePresence } from '../db/drizzle-schema';
import { and, eq, gt, inArray, isNull, or, asc } from 'drizzle-orm';
import crypto from 'crypto';
import { EventEmitter } from 'events';
import { createLogger } from '../lib/production-logger';

const logger = createLogger('RealTimeService');

type AnyServer = unknown;

type ConnectionIdentity = {
  connectionId: string;
  userId?: string;
  organizationId?: string;
  lastAckSeq?: number;
  rate?: {
    windowStartMs: number;
    count: number;
  };
};

type RealtimeEvent = {
  seq: number;
  timestamp: number;
  channel: string;
  type: string;
  payload: unknown;
};

type ClientMessage =
  | { type: 'ping' }
  | { type: 'ack'; seq: number }
  | { type: 'subscribe'; channels: string[]; since?: number }
  | { type: 'message'; channel: string; payload: unknown };

function safeJsonParse(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function getTokenFromRequestUrl(url?: string): string | undefined {
  if (!url) return undefined;
  try {
    const parsed = new URL(url, 'http://localhost');
    const token = parsed.searchParams.get('token');
    return token || undefined;
  } catch {
    return undefined;
  }
}

function getBearerTokenFromHeaders(headers: Record<string, unknown> | undefined): string | undefined {
  const raw = headers?.['authorization'];
  if (typeof raw !== 'string') return undefined;
  const trimmed = raw.trim();
  if (!trimmed.toLowerCase().startsWith('bearer ')) return undefined;
  return trimmed.slice('bearer '.length).trim() || undefined;
}

export class RealTimeService extends EventEmitter {
  private wss: WebSocketServer;
  private clients: Map<unknown, ConnectionIdentity> = new Map();
  private subscriptions: Map<unknown, Set<string>> = new Map();
  private pending: Map<unknown, Map<number, { event: RealtimeEvent; organizationId?: string; attempts: number; lastSentAt: number }>> = new Map();
  private readonly bufferSize: number;
  private readonly inboundMessageLimitPerSecond: number;
  private readonly resendIntervalMs: number;
  private readonly resendAfterMs: number;
  private readonly maxResendAttempts: number;
  private retryInterval?: NodeJS.Timeout;

  constructor(server: AnyServer, options?: { bufferSize?: number }) {
    super();
    this.bufferSize = options?.bufferSize ?? 500;
    this.inboundMessageLimitPerSecond = 10;
    this.resendIntervalMs = 2000;
    this.resendAfterMs = 3000;
    this.maxResendAttempts = 5;

    this.wss = new WebSocketServer({ server: server as any });
    this.wss.on('connection', (ws: any, req: any) => {
      this.handleConnection(ws, req?.url, req?.headers as Record<string, unknown>);
    });

    this.retryInterval = setInterval(() => {
      void this.retryPendingSends();
    }, this.resendIntervalMs);
  }

  destroy(): void {
    if (this.retryInterval) {
      clearInterval(this.retryInterval);
    }
    this.wss.close();
    this.clients.clear();
    this.subscriptions.clear();
    this.pending.clear();
    logger.info('RealTimeService cleaned up');
  }

  broadcast(params: { organizationId?: string; channel: string; type: string; payload: unknown }): void {
    void this.persistAndBroadcast(params);
  }

  private async retryPendingSends(): Promise<void> {
    const now = Date.now();

    for (const [ws, pendingBySeq] of this.pending.entries()) {
      const socket = ws as any;
      if (!socket || socket.readyState !== 1) {
        this.pending.delete(ws);
        continue;
      }

      const identity = this.clients.get(ws);
      if (!identity) {
        this.pending.delete(ws);
        continue;
      }

      for (const [seq, item] of pendingBySeq.entries()) {
        if ((identity.lastAckSeq || 0) >= seq) {
          pendingBySeq.delete(seq);
          continue;
        }

        if (now - item.lastSentAt < this.resendAfterMs) continue;

        if (item.attempts >= this.maxResendAttempts) {
          try {
            socket.send(JSON.stringify({ type: 'delivery_failed', seq }));
          } catch { /* ignore */ }
          try {
            socket.close();
          } catch { /* ignore */ }
          pendingBySeq.delete(seq);
          continue;
        }

        const subs = this.subscriptions.get(ws);
        if (!subs || !subs.has(item.event.channel)) {
          pendingBySeq.delete(seq);
          continue;
        }

        if (item.organizationId && identity.organizationId !== item.organizationId) {
          pendingBySeq.delete(seq);
          continue;
        }

        try {
          socket.send(JSON.stringify({ type: 'event', organizationId: item.organizationId, event: item.event }));
          pendingBySeq.set(seq, { ...item, attempts: item.attempts + 1, lastSentAt: now });
        } catch { /* ignore */ }
      }

      if (pendingBySeq.size === 0) {
        this.pending.delete(ws);
      }
    }
  }

  private trackPending(ws: any, identity: ConnectionIdentity, item: { organizationId?: string; event: RealtimeEvent }): void {
    if (item.event.seq <= 0) return;
    const lastAck = identity.lastAckSeq || 0;
    if (lastAck >= item.event.seq) return;

    const bySeq = this.pending.get(ws) ?? new Map();
    if (!bySeq.has(item.event.seq)) {
      bySeq.set(item.event.seq, {
        organizationId: item.organizationId,
        event: item.event,
        attempts: 1,
        lastSentAt: Date.now(),
      });
      this.pending.set(ws, bySeq);
    }
  }

  private clearAcked(ws: any, identity: ConnectionIdentity): void {
    const bySeq = this.pending.get(ws);
    if (!bySeq) return;
    const lastAck = identity.lastAckSeq || 0;

    for (const seq of bySeq.keys()) {
      if (seq <= lastAck) {
        bySeq.delete(seq);
      }
    }

    if (bySeq.size === 0) {
      this.pending.delete(ws);
    } else {
      this.pending.set(ws, bySeq);
    }
  }

  private async replaySince(ws: any, identity: ConnectionIdentity, subs: Set<string>, since: number): Promise<void> {
    try {
      const channels = Array.from(subs.values());
      if (!channels.length) return;

      const whereOrg = identity.organizationId
        ? or(eq(realtimeEvents.organizationId, identity.organizationId as any), isNull(realtimeEvents.organizationId))
        : isNull(realtimeEvents.organizationId);

      const rows = await pgDb
        .select({
          seq: realtimeEvents.seq,
          timestamp: realtimeEvents.timestamp,
          channel: realtimeEvents.channel,
          type: realtimeEvents.type,
          payload: realtimeEvents.payload,
          organizationId: realtimeEvents.organizationId,
        })
        .from(realtimeEvents)
        .where(and(whereOrg, gt(realtimeEvents.seq, since), inArray(realtimeEvents.channel, channels as any)))
        .orderBy(asc(realtimeEvents.seq))
        .limit(this.bufferSize);

      const replay: RealtimeEvent[] = rows.map((r: any) => ({
        seq: Number(r.seq),
        timestamp: Number(r.timestamp),
        channel: String(r.channel),
        type: String(r.type),
        payload: r.payload,
      }));

      if (!replay.length) return;

      ws.send(JSON.stringify({ type: 'replay', since, events: replay }));
      for (const evt of replay) {
        this.trackPending(ws, identity, {
          ...(identity.organizationId ? { organizationId: identity.organizationId } : {}),
          event: evt,
        });
      }
    } catch { /* best effort */ }
  }

  async persistAndBroadcast(params: { organizationId?: string; channel: string; type: string; payload: unknown }): Promise<void> {
    const eventTimestamp = Date.now();

    let persistedSeq: number;
    try {
      const [row] = await pgDb
        .insert(realtimeEvents)
        .values({
          organizationId: (params.organizationId as any) ?? null,
          channel: params.channel,
          type: params.type,
          payload: (params.payload as any) ?? {},
          timestamp: eventTimestamp,
        } as any)
        .returning({ seq: realtimeEvents.seq });

      persistedSeq = Number((row as any)?.seq);
      if (!Number.isFinite(persistedSeq) || persistedSeq <= 0) {
        return;
      }
    } catch (error: unknown) {
      logger.error('Failed to persist realtime event', error instanceof Error ? error : new Error(String(error)));
      return;
    }

    const event: RealtimeEvent = {
      seq: persistedSeq,
      timestamp: eventTimestamp,
      channel: params.channel,
      type: params.type,
      payload: params.payload,
    };

    const frame = JSON.stringify({ type: 'event', organizationId: params.organizationId, event });

    for (const [clientWs, identity] of this.clients.entries()) {
      const socket = clientWs as any;
      if (socket.readyState !== 1) continue;
      const subs = this.subscriptions.get(clientWs);
      if (!subs || !subs.has(params.channel)) continue;
      if (params.organizationId && identity.organizationId !== params.organizationId) continue;

      try {
        socket.send(frame);
        this.trackPending(clientWs, identity, {
          ...(params.organizationId ? { organizationId: params.organizationId } : {}),
          event,
        });
      } catch (error: unknown) { /* ignore */ }
    }
  }

  private handleConnection(ws: any, url?: string, headers?: Record<string, unknown>): void {
    const token = getTokenFromRequestUrl(url) || getBearerTokenFromHeaders(headers);
    const payload = token ? verifyToken(token) : null;

    const identity: ConnectionIdentity = {
      connectionId: `ws_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`,
      ...(payload?.userId ? { userId: payload.userId } : {}),
      ...(payload?.organizationId ? { organizationId: payload.organizationId } : {}),
      lastAckSeq: 0,
      rate: {
        windowStartMs: Date.now(),
        count: 0,
      },
    };

    this.clients.set(ws, identity);
    void this.onAuthenticatedConnection(ws, identity);

    const subs = new Set<string>();
    subs.add('public');
    if (identity.organizationId) {
      subs.add('org');
    }
    if (url?.includes('/ws/phone-status')) {
      subs.add('phone-status');
    }
    this.subscriptions.set(ws, subs);

    ws.send(
      JSON.stringify({
        type: 'hello',
        connectionId: identity.connectionId,
        authenticated: Boolean(identity.userId),
        organizationId: identity.organizationId,
        subscribed: Array.from(subs.values()),
      })
    );

    ws.on('message', (raw: any) => {
      const msg = safeJsonParse(raw.toString());
      if (!msg || typeof (msg as any).type !== 'string') return;
      void this.handleClientMessage(ws, identity, msg as ClientMessage);
    });

    ws.on('close', () => {
      this.clients.delete(ws);
      this.subscriptions.delete(ws);
      this.pending.delete(ws);
      void this.onDisconnected(identity);
    });

    ws.on('error', () => {
      this.clients.delete(ws);
      this.subscriptions.delete(ws);
      this.pending.delete(ws);
      void this.onDisconnected(identity);
    });
  }

  private async onAuthenticatedConnection(ws: any, identity: ConnectionIdentity): Promise<void> {
    if (!identity.userId || !identity.organizationId) return;

    try {
      const rows = await pgDb
        .select({ lastAckSeq: realtimeClientState.lastAckSeq })
        .from(realtimeClientState)
        .where(
          and(
            eq(realtimeClientState.organizationId, identity.organizationId as any),
            eq(realtimeClientState.userId, identity.userId as any)
          )
        )
        .limit(1);

      const last = Number((rows as any)?.[0]?.lastAckSeq ?? 0);
      identity.lastAckSeq = Number.isFinite(last) ? last : 0;
    } catch {
      identity.lastAckSeq = identity.lastAckSeq ?? 0;
    }

    const now = new Date();
    try {
      await pgDb
        .insert(realtimePresence)
        .values({
          organizationId: identity.organizationId as any,
          userId: identity.userId as any,
          isOnline: true,
          lastSeenAt: now,
          updatedAt: now,
        } as any)
        .onConflictDoUpdate({
          target: [realtimePresence.organizationId, realtimePresence.userId],
          set: {
            isOnline: true,
            lastSeenAt: now,
            updatedAt: now,
          } as any,
        });
    } catch { /* best effort */ }

    this.broadcast({
      organizationId: identity.organizationId,
      channel: 'presence',
      type: 'presence.update',
      payload: { userId: identity.userId, isOnline: true, ts: Date.now() },
    });

    const subs = this.subscriptions.get(ws);
    if (subs) {
      await this.replaySince(ws, identity, subs, identity.lastAckSeq ?? 0);
    }
  }

  private async onDisconnected(identity: ConnectionIdentity): Promise<void> {
    if (!identity.userId || !identity.organizationId) return;
    const now = new Date();

    try {
      await pgDb
        .insert(realtimePresence)
        .values({
          organizationId: identity.organizationId as any,
          userId: identity.userId as any,
          isOnline: false,
          lastSeenAt: now,
          updatedAt: now,
        } as any)
        .onConflictDoUpdate({
          target: [realtimePresence.organizationId, realtimePresence.userId],
          set: {
            isOnline: false,
            lastSeenAt: now,
            updatedAt: now,
          } as any,
        });
    } catch { /* best effort */ }

    this.broadcast({
      organizationId: identity.organizationId,
      channel: 'presence',
      type: 'presence.update',
      payload: { userId: identity.userId, isOnline: false, ts: Date.now() },
    });
  }

  private async handleClientMessage(ws: any, identity: ConnectionIdentity, msg: ClientMessage): Promise<void> {
    switch (msg.type) {
      case 'ping':
        ws.send(JSON.stringify({ type: 'pong', ts: Date.now() }));
        break;
      case 'ack':
        identity.lastAckSeq = Math.max(identity.lastAckSeq || 0, msg.seq);
        this.clients.set(ws, identity);
        ws.send(JSON.stringify({ type: 'ack', seq: msg.seq }));
        this.clearAcked(ws, identity);

        if (identity.userId && identity.organizationId) {
          const now = new Date();
          try {
            await pgDb
              .insert(realtimeClientState)
              .values({
                organizationId: identity.organizationId as any,
                userId: identity.userId as any,
                lastAckSeq: identity.lastAckSeq || 0,
                updatedAt: now,
              } as any)
              .onConflictDoUpdate({
                target: [realtimeClientState.organizationId, realtimeClientState.userId],
                set: {
                  lastAckSeq: identity.lastAckSeq || 0,
                  updatedAt: now,
                } as any,
              });
          } catch { /* best effort */ }
        }
        break;
      case 'subscribe':
        const subs = this.subscriptions.get(ws) ?? new Set<string>();
        for (const ch of msg.channels) {
          if (typeof ch === 'string' && ch.length > 0) subs.add(ch);
        }
        this.subscriptions.set(ws, subs);

        const since =
          typeof msg.since === 'number'
            ? msg.since
            : identity.userId && identity.organizationId
              ? (identity.lastAckSeq ?? 0)
              : undefined;

        if (since !== undefined) {
          await this.replaySince(ws, identity, subs, since);
        }

        ws.send(JSON.stringify({ type: 'subscribed', channels: Array.from(subs.values()) }));
        break;
      case 'message':
        if (this.isRateLimited(identity)) {
          ws.send(JSON.stringify({ type: 'rate_limited', retryAfterMs: 1000 }));
          return;
        }

        const eventTimestamp = Date.now();
        let seq = 0;

        try {
          const [row] = await pgDb
            .insert(realtimeEvents)
            .values({
              organizationId: (identity.organizationId as any) ?? null,
              channel: msg.channel,
              type: 'message',
              payload: {
                from: identity.userId || identity.connectionId,
                body: msg.payload,
              } as any,
              timestamp: eventTimestamp,
            } as any)
            .returning({ seq: realtimeEvents.seq });

          seq = Number((row as any)?.seq);
          if (!Number.isFinite(seq) || seq <= 0) {
            ws.send(JSON.stringify({ type: 'error', code: 'persist_failed' }));
            return;
          }
        } catch {
          ws.send(JSON.stringify({ type: 'error', code: 'persist_failed' }));
          return;
        }

        const event: RealtimeEvent = {
          seq,
          timestamp: eventTimestamp,
          channel: msg.channel,
          type: 'message',
          payload: {
            from: identity.userId || identity.connectionId,
            body: msg.payload,
          },
        };

        const frame = JSON.stringify({ type: 'event', organizationId: identity.organizationId, event });
        for (const [clientWs, otherIdentity] of this.clients.entries()) {
          const socket = clientWs as any;
          if (socket.readyState !== 1) continue;
          const otherSubs = this.subscriptions.get(clientWs);
          if (!otherSubs || !otherSubs.has(msg.channel)) continue;
          if (identity.organizationId && otherIdentity.organizationId !== identity.organizationId) continue;
          try {
            socket.send(frame);
            this.trackPending(clientWs, otherIdentity, {
              ...(identity.organizationId ? { organizationId: identity.organizationId } : {}),
              event,
            });
          } catch { /* ignore */ }
        }

        ws.send(JSON.stringify({ type: 'delivered', seq }));
        break;
    }
  }

  private isRateLimited(identity: ConnectionIdentity): boolean {
    const now = Date.now();
    if (!identity.rate) {
      identity.rate = { windowStartMs: now, count: 0 };
    }

    const elapsed = now - identity.rate.windowStartMs;
    if (elapsed >= 1000) {
      identity.rate.windowStartMs = now;
      identity.rate.count = 0;
    }

    identity.rate.count += 1;
    return identity.rate.count > this.inboundMessageLimitPerSecond;
  }

  private async replaySince(ws: any, identity: ConnectionIdentity, subs: Set<string>, since: number): Promise<void> {
    try {
      const channels = Array.from(subs.values());
      if (!channels.length) return;

      const whereOrg = identity.organizationId
        ? or(eq(realtimeEvents.organizationId, identity.organizationId as any), isNull(realtimeEvents.organizationId))
        : isNull(realtimeEvents.organizationId);

      const rows = await pgDb
        .select({
          seq: realtimeEvents.seq,
          timestamp: realtimeEvents.timestamp,
          channel: realtimeEvents.channel,
          type: realtimeEvents.type,
          payload: realtimeEvents.payload,
          organizationId: realtimeEvents.organizationId,
        })
        .from(realtimeEvents)
        .where(and(whereOrg, gt(realtimeEvents.seq, since), inArray(realtimeEvents.channel, channels as any)))
        .orderBy(asc(realtimeEvents.seq))
        .limit(this.bufferSize);

      const replay: RealtimeEvent[] = rows.map((r: any) => ({
        seq: Number(r.seq),
        timestamp: Number(r.timestamp),
        channel: String(r.channel),
        type: String(r.type),
        payload: r.payload,
      }));

      if (!replay.length) return;

      ws.send(JSON.stringify({ type: 'replay', since, events: replay }));
      for (const evt of replay) {
        this.trackPending(ws, identity, {
          ...(identity.organizationId ? { organizationId: identity.organizationId } : {}),
          event: evt,
        });
      }
    } catch { /* best effort */ }
  }

  private async persistAndBroadcast(params: { organizationId?: string; channel: string; type: string; payload: unknown }): Promise<void> {
    const eventTimestamp = Date.now();

    let persistedSeq: number;
    try {
      const [row] = await pgDb
        .insert(realtimeEvents)
        .values({
          organizationId: (params.organizationId as any) ?? null,
          channel: params.channel,
          type: params.type,
          payload: (params.payload as any) ?? {},
          timestamp: eventTimestamp,
        } as any)
        .returning({ seq: realtimeEvents.seq });

      persistedSeq = Number((row as any)?.seq);
      if (!Number.isFinite(persistedSeq) || persistedSeq <= 0) {
        return;
      }
    } catch (error: unknown) {
      logger.error('Failed to persist realtime event', error instanceof Error ? error : new Error(String(error)));
      return;
    }

    const event: RealtimeEvent = {
      seq: persistedSeq,
      timestamp: eventTimestamp,
      channel: params.channel,
      type: params.type,
      payload: params.payload,
    };

    const frame = JSON.stringify({ type: 'event', organizationId: params.organizationId, event });

    for (const [clientWs, identity] of this.clients.entries()) {
      const socket = clientWs as any;
      if (socket.readyState !== 1) continue;
      const subs = this.subscriptions.get(clientWs);
      if (!subs || !subs.has(params.channel)) continue;
      if (params.organizationId && identity.organizationId !== params.organizationId) continue;

      try {
        socket.send(frame);
        this.trackPending(clientWs, identity, {
          ...(params.organizationId ? { organizationId: params.organizationId } : {}),
          event,
        });
      } catch (error: unknown) { /* ignore */ }
    }
  }

  private handleConnection(ws: any, url?: string, headers?: Record<string, unknown>): void {
    const token = getTokenFromRequestUrl(url) || getBearerTokenFromHeaders(headers);
    const payload = token ? verifyToken(token) : null;

    const identity: ConnectionIdentity = {
      connectionId: `ws_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`,
      ...(payload?.userId ? { userId: payload.userId } : {}),
      ...(payload?.organizationId ? { organizationId: payload.organizationId } : {}),
      lastAckSeq: 0,
      rate: {
        windowStartMs: Date.now(),
        count: 0,
      },
    };

    this.clients.set(ws, identity);
    void this.onAuthenticatedConnection(ws, identity);

    const subs = new Set<string>();
    subs.add('public');
    if (identity.organizationId) {
      subs.add('org');
    }
    if (url?.includes('/ws/phone-status')) {
      subs.add('phone-status');
    }
    this.subscriptions.set(ws, subs);

    ws.send(
      JSON.stringify({
        type: 'hello',
        connectionId: identity.connectionId,
        authenticated: Boolean(identity.userId),
        organizationId: identity.organizationId,
        subscribed: Array.from(subs.values()),
      })
    );

    ws.on('message', (raw: any) => {
      const msg = safeJsonParse(raw.toString());
      if (!msg || typeof (msg as any).type !== 'string') return;
      void this.handleClientMessage(ws, identity, msg as ClientMessage);
    });

    ws.on('close', () => {
      this.clients.delete(ws);
      this.subscriptions.delete(ws);
      this.pending.delete(ws);
      void this.onDisconnected(identity);
    });

    ws.on('error', () => {
      this.clients.delete(ws);
      this.subscriptions.delete(ws);
      this.pending.delete(ws);
      void this.onDisconnected(identity);
    });
  }

  private trackPending(ws: any, identity: ConnectionIdentity, item: { organizationId?: string; event: RealtimeEvent }): void {
    if (!bySeq.has(item.event.seq)) {
      bySeq.set(item.event.seq, {
        organizationId: item.organizationId,
        event: item.event,
        attempts: 1,
        lastSentAt: Date.now(),
      });
      this.pending.set(ws, bySeq);
    }
  }

  private clearAcked(ws: any, identity: ConnectionIdentity): void {
    const bySeq = this.pending.get(ws);
    if (!bySeq) return;
    const lastAck = identity.lastAckSeq || 0;

    for (const seq of bySeq.keys()) {
      if (seq <= lastAck) {
        bySeq.delete(seq);
      }
    }

    if (bySeq.size === 0) {
      this.pending.delete(ws);
    } else {
      this.pending.set(ws, bySeq);
    }
  }
}

export default RealTimeService;

import { db as pgDb } from '../db/connection';
import { eq, and, desc, lte } from 'drizzle-orm';
import crypto from 'crypto';
import { EventEmitter } from 'events';


import { createLogger } from '../lib/production-logger';

const logger = createLogger(__filename.split('/').pop()?.replace('.ts', '') || 'Service');

export interface Report {
  id: string;
  organizationId: string;
  name: string;
  description: string;
  type: 'dashboard' | 'analytics' | 'compliance' | 'financial' | 'custom';
  category: 'marketing' | 'sales' | 'support' | 'operations' | 'hr' | 'finance' | 'security';
  status: 'draft' | 'active' | 'archived';
  config: ReportConfig;
  schedule?: ReportSchedule;
  permissions: ReportPermissions;
  metadata: Record<string, unknown>;
  createdBy: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface ReportConfig {
  dataSource: string[];
  filters: ReportFilter[];
  metrics: ReportMetric[];
  dimensions: ReportDimension[];
  visualizations: ReportVisualization[];
  timeRange: {
    start: Date;
    end: Date;
    relative?: string;
  };
  refreshInterval?: number;
}

export interface ReportFilter {
  id: string;
  field: string;
  operator: 'equals' | 'not_equals' | 'contains' | 'not_contains' | 'greater_than' | 'less_than' | 'in' | 'not_in' | 'between';
  value: unknown;
  label?: string;
}

export interface ReportMetric {
  id: string;
  name: string;
  type: 'count' | 'sum' | 'average' | 'min' | 'max' | 'percentage' | 'ratio';
  field?: string;
  formula?: string;
  format?: string;
  label?: string;
}

export interface ReportDimension {
  id: string;
  name: string;
  field: string;
  type: 'string' | 'number' | 'date' | 'boolean';
  label?: string;
}

export interface ReportVisualization {
  id: string;
  type: 'table' | 'line_chart' | 'bar_chart' | 'pie_chart' | 'area_chart' | 'scatter_plot' | 'gauge' | 'kpi';
  title: string;
  position: { x: number; y: number; width: number; height: number };
  config: {
    metrics: string[];
    dimensions?: string[];
    filters?: string[];
    chartOptions?: Record<string, unknown>;
  };
}

export interface ReportSchedule {
  enabled: boolean;
  frequency: 'hourly' | 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'yearly';
  timezone: string;
  recipients: string[];
  format: 'pdf' | 'excel' | 'csv' | 'json';
  nextRun?: Date;
}

export interface ReportPermissions {
  view: string[];
  edit: string[];
  share: string[];
  isPublic: boolean;
}

export interface ReportExecution {
  id: string;
  reportId: string;
  organizationId: string;
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  parameters: Record<string, unknown>;
  results?: ReportResult;
  error?: string;
  startedAt: Date;
  completedAt?: Date;
  generatedBy?: string;
  fileUrl?: string;
  fileSize?: number;
}

export interface ReportResult {
  data: unknown[];
  summary: {
    totalRows: number;
    executionTime: number;
    generatedAt: Date;
  };
  visualizations: {
    id: string;
    type: string;
    data: unknown;
    config: unknown;
  }[];
}

export class ReportingService extends EventEmitter {
  private reports: Map<string, Report> = new Map();
  private executions: Map<string, ReportExecution> = new Map();
  private scheduledJobs: Map<string, NodeJS.Timeout> = new Map();
  private checkInterval?: NodeJS.Timeout;

  constructor() {
    super();
    this.startScheduledReports();
  }

  private startScheduledReports(): void {
    this.checkInterval = setInterval(() => {
      this.checkScheduledReports();
    }, 60000); // Check every minute
  }

  async createReport(
    organizationId: string,
    report: Omit<Report, 'id' | 'organizationId' | 'createdAt' | 'updatedAt'>
  ): Promise<Report> {
    const id = crypto.randomUUID();
    const now = new Date();

    const newReport: Report = {
      ...report,
      id,
      organizationId,
      createdAt: now,
      updatedAt: now
    };

    // Store report
    this.reports.set(id, newReport);

    // Schedule if needed
    if (report.schedule?.enabled) {
      await this.scheduleReport(newReport);
    }

    logger.info(`Created report: ${id} (${report.name})`);

    this.emit('report:created', newReport);
    return newReport;
  }

  async executeReport(
    reportId: string,
    parameters: Record<string, unknown> = {},
    userId?: string
  ): Promise<ReportExecution> {
    const report = this.reports.get(reportId);
    if (!report) {
      throw new Error(`Report not found: ${reportId}`);
    }

    // Check permissions
    if (!this.hasPermission(report, userId, 'view')) {
      throw new Error('Access denied: insufficient permissions');
    }

    const executionId = crypto.randomUUID();
    const execution: ReportExecution = {
      id: executionId,
      reportId,
      organizationId: report.organizationId,
      status: 'pending',
      parameters,
      startedAt: new Date(),
      generatedBy: userId
    };

    this.executions.set(executionId, execution);

    // Start execution
    setImmediate(() => this.processReportExecution(executionId));

    logger.info(`Started report execution: ${executionId}`);

    this.emit('report:execution_started', execution);
    return execution;
  }

  private async processReportExecution(executionId: string): Promise<void> {
    const execution = this.executions.get(executionId);
    if (!execution) return;

    const report = this.reports.get(execution.reportId);
    if (!report) {
      execution.status = 'failed';
      execution.error = 'Report not found';
      return;
    }

    try {
      execution.status = 'running';

      // Execute the report
      const result = await this.generateReportData(report, execution.parameters);

      execution.results = result;
      execution.status = 'completed';
      execution.completedAt = new Date();

      // Generate file if needed
      if (report.schedule?.format) {
        const fileUrl = await this.generateReportFile(execution, report.schedule.format);
        execution.fileUrl = fileUrl;
      }

      this.emit('report:execution_completed', { execution, result });

    } catch (error) {
      execution.status = 'failed';
      execution.error = error instanceof Error ? error.message : 'Unknown error';
      execution.completedAt = new Date();

      this.emit('report:execution_failed', { execution, error });
    }
  }

  private async generateReportData(report: Report, parameters: Record<string, any>): Promise<ReportResult> {
    const startTime = Date.now();

    // Apply parameters to report config
    const config = this.applyParameters(report.config, parameters);

    // Fetch data from data sources
    const data = await this.fetchData(config.dataSource, config.filters);

    // Apply metrics and dimensions
    const processedData = this.processData(data, config.metrics, config.dimensions);

    // Generate visualizations
    const visualizations = await this.generateVisualizations(processedData, config.visualizations);

    const executionTime = Date.now() - startTime;

    return {
      data: processedData,
      summary: {
        totalRows: processedData.length,
        executionTime,
        generatedAt: new Date()
      },
      visualizations
    };
  }

  private applyParameters(config: ReportConfig, parameters: Record<string, any>): ReportConfig {
    const appliedConfig = JSON.parse(JSON.stringify(config));

    // Apply parameter overrides to filters
    for (const [key, value] of Object.entries(parameters)) {
      const filter = appliedConfig.filters.find((f: ReportFilter) => f.field === key);
      if (filter) {
        filter.value = value;
      }
    }

    // Apply time range overrides
    if (parameters.startDate) {
      appliedConfig.timeRange.start = new Date(parameters.startDate);
    }
    if (parameters.endDate) {
      appliedConfig.timeRange.end = new Date(parameters.endDate);
    }

    return appliedConfig;
  }

  private async fetchData(dataSources: string[], filters: ReportFilter[]): Promise<any[]> {
    // In real implementation, would query from actual data sources
    logger.info(`Fetching data from sources: ${dataSources.join(', ')}`);

    // Simulate data fetching
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Generate sample data
    const sampleData = this.generateSampleData(dataSources, filters);

    return sampleData;
  }

  private generateSampleData(dataSources: string[], filters: ReportFilter[]): any[] {
    const data: any[] = [];
    const rowCount = 100;

    for (let i = 0; i < rowCount; i++) {
      const row: any = {
        id: i + 1,
        date: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        revenue: Math.floor(Math.random() * 10000) + 1000,
        customers: Math.floor(Math.random() * 100) + 10,
        orders: Math.floor(Math.random() * 50) + 5,
        conversion_rate: Math.random() * 0.1 + 0.02,
        category: ['electronics', 'clothing', 'books', 'home', 'sports'][Math.floor(Math.random() * 5)],
        region: ['north', 'south', 'east', 'west'][Math.floor(Math.random() * 4)]
      };

      // Apply filters
      let matchesFilters = true;
      for (const filter of filters) {
        if (!this.matchesFilter(row, filter)) {
          matchesFilters = false;
          break;
        }
      }

      if (matchesFilters) {
        data.push(row);
      }
    }

    return data;
  }

  private matchesFilter(row: any, filter: ReportFilter): boolean {
    const value = row[filter.field];

    switch (filter.operator) {
      case 'equals':
        return value === filter.value;
      case 'not_equals':
        return value !== filter.value;
      case 'contains':
        return String(value).includes(String(filter.value));
      case 'not_contains':
        return !String(value).includes(String(filter.value));
      case 'greater_than':
        return Number(value) > Number(filter.value);
      case 'less_than':
        return Number(value) < Number(filter.value);
      case 'in':
        return Array.isArray(filter.value) && filter.value.includes(value);
      case 'not_in':
        return Array.isArray(filter.value) && !filter.value.includes(value);
      case 'between':
        return Array.isArray(filter.value) && 
               Number(value) >= Number(filter.value[0]) && 
               Number(value) <= Number(filter.value[1]);
      default:
        return true;
    }
  }

  private processData(data: any[], metrics: ReportMetric[], dimensions: ReportDimension[]): any[] {
    // Apply metrics and dimensions to data
    const processedData = data.map(row => {
      const processedRow: any = { ...row };

      // Calculate metrics
      for (const metric of metrics) {
        switch (metric.type) {
          case 'count':
            processedRow[metric.id] = 1;
            break;
          case 'sum':
            processedRow[metric.id] = Number(row[metric.field || 0]);
            break;
          case 'average':
            processedRow[metric.id] = Number(row[metric.field || 0]);
            break;
          case 'min':
            processedRow[metric.id] = Number(row[metric.field || 0]);
            break;
          case 'max':
            processedRow[metric.id] = Number(row[metric.field || 0]);
            break;
          case 'percentage':
            processedRow[metric.id] = (Number(row[metric.field || 0]) / 100) * 100;
            break;
          case 'ratio':
            if (metric.formula) {
              processedRow[metric.id] = this.evaluateFormula(metric.formula, row);
            }
            break;
        }
      }

      return processedRow;
    });

    // Group by dimensions if specified
    if (dimensions.length > 0) {
      return this.groupByDimensions(processedData, dimensions);
    }

    return processedData;
  }

  private groupByDimensions(data: any[], dimensions: ReportDimension[]): any[] {
    const groups: Record<string, any[]> = {};

    for (const row of data) {
      const key = dimensions.map(dim => `${row[dim.field]}`).join('|');

      if (!groups[key]) {
        groups[key] = [];
      }
      groups[key].push(row);
    }

    return Object.values(groups).map(group => {
      const aggregated: any = {};

      // Set dimension values
      for (const dim of dimensions) {
        aggregated[dim.field] = group[0][dim.field];
      }

      // Aggregate metrics
      const metrics = Object.keys(group[0]).filter(key => 
        !dimensions.some(dim => dim.field === key) && 
        !['id', 'date'].includes(key)
      );

      for (const metric of metrics) {
        const values = group.map(row => Number(row[metric] || 0));
        aggregated[metric] = values.reduce((sum, val) => sum + val, 0);
      }

      aggregated._count = group.length;
      return aggregated;
    });
  }

  private evaluateFormula(formula: string, row: any): number {
    // Safe formula evaluation - replaces variable names with values and evaluates mathematically
    try {
      // Replace variable names with their values from the row
      let evalFormula = formula;
      for (const [key, value] of Object.entries(row)) {
        // Use word boundary to match whole variable names only
        evalFormula = evalFormula.replace(new RegExp(`\\b${key}\\b`, 'g'), String(value));
      }

      // Validate formula contains only allowed characters (numbers, operators, parentheses, decimals)
      // Allowed: 0-9, +, -, *, /, %, (, ), ., spaces
      if (!/^[\d\+\-\*\/\%\(\)\.\s]+$/.test(evalFormula)) {
        logger.warn(`[ReportingService] Formula contains invalid characters: ${evalFormula}`);
        return 0;
      }

      // Parse and evaluate the mathematical expression safely
      return this.safeMathEval(evalFormula);
    } catch (error) {
      logger.error('[ReportingService] Formula evaluation failed:', error);
      return 0;
    }
  }

  /**
   * Safely evaluate a mathematical expression without using eval()
   * Supports: +, -, *, /, %, parentheses, decimal numbers
   */
  private safeMathEval(expression: string): number {
    // Remove all whitespace
    const cleanExpr = expression.replace(/\s+/g, '');

    if (!cleanExpr) return 0;

    // Tokenize the expression
    const tokens: (number | string)[] = [];
    let current = '';

    for (let i = 0; i < cleanExpr.length; i++) {
      const char = cleanExpr[i];

      if (/[\d\.]/.test(char)) {
        current += char;
      } else if (/[\+\-\*\/\%\(\)]/.test(char)) {
        if (current) {
          tokens.push(parseFloat(current));
          current = '';
        }
        tokens.push(char);
      }
    }

    if (current) {
      tokens.push(parseFloat(current));
    }

    // Evaluate using recursive descent parsing
    return this.evaluateTokens(tokens, 0)[0];
  }

  private evaluateTokens(tokens: (number | string)[], index: number): [number, number] {
    let [value, nextIndex] = this.parseExpression(tokens, index);
    return [value, nextIndex];
  }

  private parseExpression(tokens: (number | string)[], index: number): [number, number] {
    let [value, nextIndex] = this.parseTerm(tokens, index);

    while (nextIndex < tokens.length) {
      const operator = tokens[nextIndex];
      if (operator === '+' || operator === '-') {
        const [termValue, termNextIndex] = this.parseTerm(tokens, nextIndex + 1);
        if (operator === '+') {
          value += termValue;
        } else {
          value -= termValue;
        }
        nextIndex = termNextIndex;
      } else {
        break;
      }
    }

    return [value, nextIndex];
  }

  private parseTerm(tokens: (number | string)[], index: number): [number, number] {
    let [value, nextIndex] = this.parseFactor(tokens, index);

    while (nextIndex < tokens.length) {
      const operator = tokens[nextIndex];
      if (operator === '*' || operator === '/' || operator === '%') {
        const [factorValue, factorNextIndex] = this.parseFactor(tokens, nextIndex + 1);
        if (operator === '*') {
          value *= factorValue;
        } else if (operator === '/') {
          if (factorValue === 0) {
            logger.warn('[ReportingService] Division by zero in formula');
            return [0, factorNextIndex];
          }
          value /= factorValue;
        } else {
          value %= factorValue;
        }
        nextIndex = factorNextIndex;
      } else {
        break;
      }
    }

    return [value, nextIndex];
  }

  private parseFactor(tokens: (number | string)[], index: number): [number, number] {
    const token = tokens[index];

    if (typeof token === 'number') {
      return [token, index + 1];
    }

    if (token === '(') {
      const [value, nextIndex] = this.parseExpression(tokens, index + 1);
      if (tokens[nextIndex] === ')') {
        return [value, nextIndex + 1];
      }
    }

    // Handle unary minus
    if (token === '-') {
      const [factorValue, factorNextIndex] = this.parseFactor(tokens, index + 1);
      return [-factorValue, factorNextIndex];
    }

    // Handle unary plus
    if (token === '+') {
      return this.parseFactor(tokens, index + 1);
    }

    return [0, index + 1];
  }

  private async generateVisualizations(data: any[], visualizations: ReportVisualization[]): Promise<any[]> {
    const results: any[] = [];

    for (const viz of visualizations) {
      const vizData = await this.generateVisualization(data, viz);
      results.push(vizData);
    }

    return results;
  }

  private async generateVisualization(data: any[], visualization: ReportVisualization): Promise<any> {
    const { type, config } = visualization;

    switch (type) {
      case 'table':
        return this.generateTableVisualization(data, config);
      case 'line_chart':
        return this.generateLineChartVisualization(data, config);
      case 'bar_chart':
        return this.generateBarChartVisualization(data, config);
      case 'pie_chart':
        return this.generatePieChartVisualization(data, config);
      case 'area_chart':
        return this.generateAreaChartVisualization(data, config);
      case 'kpi':
        return this.generateKPIVisualization(data, config);
      default:
        return { type, data: [], config };
    }
  }

  private generateTableVisualization(data: any[], config: any): any {
    return {
      type: 'table',
      data: data.slice(0, 100), // Limit to 100 rows for table
      config: {
        columns: Object.keys(data[0] || {}),
        pagination: true
      }
    };
  }

  private generateLineChartVisualization(data: any[], config: any): any {
    // Aggregate data for line chart
    const aggregated = this.aggregateByTime(data, config.dimensions?.[0] || 'date');

    return {
      type: 'line_chart',
      data: {
        labels: aggregated.map(item => item[config.dimensions?.[0] || 'date']),
        datasets: config.metrics.map((metric: string) => ({
          label: metric,
          data: aggregated.map(item => item[metric])
        }))
      },
      config: config.chartOptions || {}
    };
  }

  private generateBarChartVisualization(data: any[], config: any): any {
    const aggregated = this.aggregateByDimension(data, config.dimensions?.[0] || 'category');

    return {
      type: 'bar_chart',
      data: {
        labels: aggregated.map(item => item[config.dimensions?.[0] || 'category']),
        datasets: config.metrics.map((metric: string) => ({
          label: metric,
          data: aggregated.map(item => item[metric])
        }))
      },
      config: config.chartOptions || {}
    };
  }

  private generatePieChartVisualization(data: any[], config: any): any {
    const aggregated = this.aggregateByDimension(data, config.dimensions?.[0] || 'category');
    const metric = config.metrics?.[0] || 'revenue';

    return {
      type: 'pie_chart',
      data: {
        labels: aggregated.map(item => item[config.dimensions?.[0] || 'category']),
        datasets: [{
          data: aggregated.map(item => item[metric])
        }]
      },
      config: config.chartOptions || {}
    };
  }

  private generateAreaChartVisualization(data: any[], config: any): any {
    const aggregated = this.aggregateByTime(data, config.dimensions?.[0] || 'date');

    return {
      type: 'area_chart',
      data: {
        labels: aggregated.map(item => item[config.dimensions?.[0] || 'date']),
        datasets: config.metrics.map((metric: string) => ({
          label: metric,
          data: aggregated.map(item => item[metric]),
          fill: true
        }))
      },
      config: config.chartOptions || {}
    };
  }

  private generateKPIVisualization(data: any[], config: any): any {
    const metric = config.metrics?.[0] || 'revenue';
    const value = data.reduce((sum, row) => sum + Number(row[metric] || 0), 0);

    return {
      type: 'kpi',
      data: {
        value,
        label: metric,
        format: config.format || 'number'
      },
      config: config.chartOptions || {}
    };
  }

  private aggregateByTime(data: any[], timeField: string): any[] {
    const grouped: Record<string, any[]> = {};

    for (const row of data) {
      const date = row[timeField]?.split('T')[0] || 'unknown';
      if (!grouped[date]) {
        grouped[date] = [];
      }
      grouped[date].push(row);
    }

    return Object.entries(grouped).map(([date, rows]) => {
      const aggregated: any = { [timeField]: date };
      const metrics = Object.keys(rows[0]).filter(key => key !== timeField && !isNaN(Number(rows[0][key])));

      for (const metric of metrics) {
        aggregated[metric] = rows.reduce((sum, row) => sum + Number(row[metric] || 0), 0);
      }

      return aggregated;
    });
  }

  private aggregateByDimension(data: any[], dimension: string): any[] {
    const grouped: Record<string, any[]> = {};

    for (const row of data) {
      const value = row[dimension] || 'unknown';
      if (!grouped[value]) {
        grouped[value] = [];
      }
      grouped[value].push(row);
    }

    return Object.entries(grouped).map(([value, rows]) => {
      const aggregated: any = { [dimension]: value };
      const metrics = Object.keys(rows[0]).filter(key => key !== dimension && !isNaN(Number(rows[0][key])));

      for (const metric of metrics) {
        aggregated[metric] = rows.reduce((sum, row) => sum + Number(row[metric] || 0), 0);
      }

      return aggregated;
    });
  }

  private async generateReportFile(execution: ReportExecution, format: string): Promise<string> {
    if (!execution.results) {
      throw new Error('No results available for file generation');
    }

    const filename = `report_${execution.id}_${Date.now()}.${format}`;
    const fileUrl = `/api/reports/files/${filename}`;

    // In real implementation, would generate actual files
    logger.info(`Generating ${format} file: ${filename}`);

    // Simulate file generation
    await new Promise(resolve => setTimeout(resolve, 2000));

    return fileUrl;
  }

  private async scheduleReport(report: Report): Promise<void> {
    if (!report.schedule?.enabled) return;

    const { frequency, timezone } = report.schedule;

    // Calculate next run time (simplified)
    let nextRun = new Date();
    switch (frequency) {
      case 'hourly':
        nextRun.setHours(nextRun.getHours() + 1);
        break;
      case 'daily':
        nextRun.setDate(nextRun.getDate() + 1);
        nextRun.setHours(9, 0, 0, 0);
        break;
      case 'weekly':
        nextRun.setDate(nextRun.getDate() + 7);
        nextRun.setHours(9, 0, 0, 0);
        break;
      case 'monthly':
        nextRun.setMonth(nextRun.getMonth() + 1);
        nextRun.setDate(1);
        nextRun.setHours(9, 0, 0, 0);
        break;
    }

    report.schedule.nextRun = nextRun;

    // Schedule the job
    const delay = nextRun.getTime() - Date.now();
    const timeout = setTimeout(async () => {
      await this.executeScheduledReport(report.id);
      await this.scheduleReport(report); // Reschedule
    }, delay);

    this.scheduledJobs.set(`${report.id}_scheduled`, timeout);
  }

  private async executeScheduledReport(reportId: string): Promise<void> {
    try {
      const execution = await this.executeReport(reportId);

      // Send to recipients
      const report = this.reports.get(reportId);
      if (report?.schedule?.recipients) {
        await this.sendReportToRecipients(execution, report.schedule.recipients);
      }

      logger.info(`Scheduled report executed: ${reportId}`);
    } catch (error) {
      logger.error(`Scheduled report execution failed: ${reportId}`, error);
    }
  }

  private async sendReportToRecipients(execution: ReportExecution, recipients: string[]): Promise<void> {
    // In real implementation, would send emails/notifications
    logger.info(`Sending report ${execution.id} to ${recipients.join(', ')}`);
  }

  private async checkScheduledReports(): Promise<void> {
    const now = new Date();

    for (const report of this.reports.values()) {
      if (report.schedule?.enabled && report.schedule.nextRun && report.schedule.nextRun <= now) {
        await this.executeScheduledReport(report.id);
      }
    }
  }

  private hasPermission(report: Report, userId?: string, action: 'view' | 'edit' | 'share'): boolean {
    if (!userId) return report.permissions.isPublic && action === 'view';

    return report.permissions[action].includes(userId) || report.permissions[action].includes('*');
  }

  async getReport(organizationId: string, reportId: string, userId?: string): Promise<Report | null> {
    const report = this.reports.get(reportId);
    return report && report.organizationId === organizationId && this.hasPermission(report, userId, 'view') ? report : null;
  }

  async getReports(organizationId: string, userId?: string, filters: {
    type?: Report['type'];
    category?: Report['category'];
    status?: Report['status'];
    limit?: number;
    offset?: number;
  } = {}): Promise<{ reports: Report[]; total: number }> {
    const reports = Array.from(this.reports.values())
      .filter(r => r.organizationId === organizationId)
      .filter(r => this.hasPermission(r, userId, 'view'))
      .filter(r => !filters.type || r.type === filters.type)
      .filter(r => !filters.category || r.category === filters.category)
      .filter(r => !filters.status || r.status === filters.status);

    return {
      reports: reports.slice(filters.offset || 0, (filters.offset || 0) + (filters.limit || 50)),
      total: reports.length
    };
  }

  async getExecution(executionId: string): Promise<ReportExecution | null> {
    return this.executions.get(executionId) || null;
  }

  async getExecutions(organizationId: string, reportId?: string, filters: {
    status?: ReportExecution['status'];
    startDate?: Date;
    endDate?: Date;
    limit?: number;
    offset?: number;
  } = {}): Promise<{ executions: ReportExecution[]; total: number }> {
    const executions = Array.from(this.executions.values())
      .filter(e => e.organizationId === organizationId)
      .filter(e => !reportId || e.reportId === reportId)
      .filter(e => !filters.status || e.status === filters.status);

    return {
      executions: executions.slice(filters.offset || 0, (filters.offset || 0) + (filters.limit || 50)),
      total: executions.length
    };
  }

  async updateReport(
    organizationId: string,
    reportId: string,
    updates: Partial<Report>,
    userId?: string
  ): Promise<Report | null> {
    const report = this.reports.get(reportId);
    if (!report || report.organizationId !== organizationId || !this.hasPermission(report, userId, 'edit')) {
      return null;
    }

    const updatedReport: Report = {
      ...report,
      ...updates,
      updatedAt: new Date()
    };

    this.reports.set(reportId, updatedReport);

    // Reschedule if schedule changed
    if (updates.schedule) {
      await this.scheduleReport(updatedReport);
    }

    this.emit('report:updated', updatedReport);
    return updatedReport;
  }

  async deleteReport(organizationId: string, reportId: string, userId?: string): Promise<boolean> {
    const report = this.reports.get(reportId);
    if (!report || report.organizationId !== organizationId || !this.hasPermission(report, userId, 'edit')) {
      return false;
    }

    // Cancel scheduled jobs
    const jobKey = `${reportId}_scheduled`;
    const timeout = this.scheduledJobs.get(jobKey);
    if (timeout) {
      clearTimeout(timeout);
      this.scheduledJobs.delete(jobKey);
    }

    this.reports.delete(reportId);

    this.emit('report:deleted', { reportId, userId });
    return true;
  }

  async getReportStats(organizationId: string): Promise<{
    totalReports: number;
    activeReports: number;
    totalExecutions: number;
    successfulExecutions: number;
    failedExecutions: number;
    averageExecutionTime: number;
  }> {
    const reports = Array.from(this.reports.values()).filter(r => r.organizationId === organizationId);
    const executions = Array.from(this.executions.values()).filter(e => e.organizationId === organizationId);

    const successfulExecutions = executions.filter(e => e.status === 'completed').length;
    const failedExecutions = executions.filter(e => e.status === 'failed').length;

    const completedExecutions = executions.filter(e => e.completedAt);
    const averageExecutionTime = completedExecutions.length > 0
      ? completedExecutions.reduce((sum, e) => sum + (e.completedAt!.getTime() - e.startedAt.getTime()), 0) / completedExecutions.length
      : 0;

    return {
      totalReports: reports.length,
      activeReports: reports.filter(r => r.status === 'active').length,
      totalExecutions: executions.length,
      successfulExecutions,
      failedExecutions,
      averageExecutionTime
    };
  }

  /**
   * Cleanup resources
   */
  destroy(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
    }
    // Clear all scheduled job timeouts
    for (const timeout of this.scheduledJobs.values()) {
      clearTimeout(timeout);
    }
    this.scheduledJobs.clear();
    this.removeAllListeners();
    logger.info('ReportingService cleaned up');
  }
}

