export interface SessionSearchFilters {
  // Basic filters
  agentId?: string;
  participantIds?: string[];
  status?: ('pending' | 'in_progress' | 'completed' | 'escalated' | 'rejected' | 'timeout')[];

  // Counseling specific filters
  counselingMode?: ('main_to_sub' | 'sub_to_main' | 'peer_to_peer' | 'cross_functional')[];
  counselingType?: ('performance_improvement' | 'skill_development' | 'crisis_intervention' | 'career_guidance' | 'coordination_alignment' | 'conflict_resolution')[];
  programType?: string[];

  // Priority and urgency
  priority?: ('low' | 'medium' | 'high' | 'critical' | 'emergency')[];
  severity?: ('low' | 'medium' | 'high' | 'critical')[];

  // Date filters
  createdAfter?: Date;
  createdBefore?: Date;
  updatedAfter?: Date;
  updatedBefore?: Date;
  completedAfter?: Date;
  completedBefore?: Date;

  // Content filters
  topicContains?: string;
  questionContains?: string;
  answerContains?: string;
  tags?: string[];

  // Performance filters
  minConfidence?: number;
  maxConfidence?: number;
  hasRecommendations?: boolean;
  hasActionItems?: boolean;
  isEscalated?: boolean;

  // Relationship filters
  initiatorId?: string;
  responderId?: string;
  category?: string[];

  // Pagination
  limit?: number;
  offset?: number;

  // Sorting
  sortBy?: 'createdAt' | 'updatedAt' | 'priority' | 'status' | 'topic';
  sortOrder?: 'asc' | 'desc';
}

export interface SessionSearchResult {
  sessions: ConsultationSession[];
  total: number;
  hasMore: boolean;
  facets: SearchFacets;
}

export interface SearchFacets {
  byStatus: Record<string, number>;
  byMode: Record<string, number>;
  byPriority: Record<string, number>;
  byType: Record<string, number>;
  byMonth: Record<string, number>;
  byAgent: { agentId: string; agentName: string; count: number }[];
}

export interface FullTextSearchOptions {
  query: string;
  fields?: ('topic' | 'question' | 'answer' | 'recommendations' | 'context')[];
  fuzzy?: boolean;
  caseSensitive?: boolean;
}

class SessionSearchService {
  private sessionIndex: Map<string, SearchableSessionData> = new Map();

  // ============================================
  // INDEXING
  // ============================================

  indexSession(session: ConsultationSession): void {
    const searchableData: SearchableSessionData = {
      id: session.id,
      status: session.status,
      createdAt: new Date(session.createdAt),
      updatedAt: new Date(session.updatedAt),
      initiatorId: session.initiator.agentId,
      initiatorName: session.initiator.agentName,
      participantIds: session.participants.map(p => p.agentId),
      participantNames: session.participants.map(p => p.agentName),
      topics: session.requests.map(r => r.topic),
      questions: session.requests.map(r => r.question),
      answers: session.responses.map(r => r.answer),
      recommendations: session.responses.flatMap(r => r.recommendations),
      priorities: session.requests.map(r => r.priority),
      types: session.requests.map(r => r.type),
      tags: session.requests.flatMap(r => r.tags || []),
      counselingContext: session.requests.map(r => r.counselingContext).filter(Boolean),
      confidence: session.responses.map(r => r.confidence),
    };

    this.sessionIndex.set(session.id, searchableData);
  }

  removeFromIndex(sessionId: string): void {
    this.sessionIndex.delete(sessionId);
  }

  // ============================================
  // SEARCH
  // ============================================

  searchSessions(
    sessions: ConsultationSession[],
    filters: SessionSearchFilters
  ): SessionSearchResult {
    let results = [...sessions];

    // Apply filters
    if (filters.agentId) {
      results = results.filter(s => 
        s.initiator.agentId === filters.agentId ||
        s.participants.some(p => p.agentId === filters.agentId)
      );
    }

    if (filters.participantIds && filters.participantIds.length > 0) {
      results = results.filter(s =>
        filters.participantIds!.some(id => 
          s.initiator.agentId === id || s.participants.some(p => p.agentId === id)
        )
      );
    }

    if (filters.status && filters.status.length > 0) {
      results = results.filter(s => filters.status!.includes(s.status));
    }

    if (filters.counselingMode && filters.counselingMode.length > 0) {
      results = results.filter(s => {
        const latestRequest = s.requests[s.requests.length - 1];
        const mode = latestRequest?.counselingContext?.relationship;
        return mode && filters.counselingMode!.includes(mode as any);
      });
    }

    if (filters.programType && filters.programType.length > 0) {
      results = results.filter(s => {
        const latestRequest = s.requests[s.requests.length - 1];
        const type = latestRequest?.counselingContext?.sessionType;
        return type && filters.programType!.includes(type as any);
      });
    }

    if (filters.priority && filters.priority.length > 0) {
      results = results.filter(s => {
        const latestRequest = s.requests[s.requests.length - 1];
        return latestRequest && filters.priority!.includes(latestRequest.priority);
      });
    }

    if (filters.counselingType && filters.counselingType.length > 0) {
      results = results.filter(s => {
        const latestRequest = s.requests[s.requests.length - 1];
        return latestRequest && filters.counselingType!.includes(latestRequest.type as any);
      });
    }

    // Date filters
    if (filters.createdAfter) {
      results = results.filter(s => new Date(s.createdAt) >= filters.createdAfter!);
    }
    if (filters.createdBefore) {
      results = results.filter(s => new Date(s.createdAt) <= filters.createdBefore!);
    }
    if (filters.updatedAfter) {
      results = results.filter(s => new Date(s.updatedAt) >= filters.updatedAfter!);
    }
    if (filters.updatedBefore) {
      results = results.filter(s => new Date(s.updatedAt) <= filters.updatedBefore!);
    }
    if (filters.completedAfter) {
      results = results.filter(s => 
        s.status === 'completed' && new Date(s.updatedAt) >= filters.completedAfter!
      );
    }
    if (filters.completedBefore) {
      results = results.filter(s => 
        s.status === 'completed' && new Date(s.updatedAt) <= filters.completedBefore!
      );
    }

    // Content filters
    if (filters.topicContains) {
      const term = filters.topicContains.toLowerCase();
      results = results.filter(s => 
        s.requests.some(r => r.topic.toLowerCase().includes(term))
      );
    }
    if (filters.questionContains) {
      const term = filters.questionContains.toLowerCase();
      results = results.filter(s => 
        s.requests.some(r => r.question.toLowerCase().includes(term))
      );
    }
    if (filters.answerContains) {
      const term = filters.answerContains.toLowerCase();
      results = results.filter(s => 
        s.responses.some(r => r.answer.toLowerCase().includes(term))
      );
    }
    if (filters.tags && filters.tags.length > 0) {
      results = results.filter(s => 
        s.requests.some(r => 
          filters.tags!.some(tag => r.tags?.includes(tag))
        )
      );
    }

    // Performance filters
    if (filters.minConfidence !== undefined) {
      results = results.filter(s => 
        s.responses.some(r => r.confidence >= filters.minConfidence!)
      );
    }
    if (filters.maxConfidence !== undefined) {
      results = results.filter(s => 
        s.responses.some(r => r.confidence <= filters.maxConfidence!)
      );
    }
    if (filters.hasRecommendations !== undefined) {
      results = results.filter(s => 
        s.responses.some(r => 
          filters.hasRecommendations ? r.recommendations.length > 0 : r.recommendations.length === 0
        )
      );
    }
    if (filters.isEscalated !== undefined) {
      results = results.filter(s => 
        filters.isEscalated ? s.status === 'escalated' : s.status !== 'escalated'
      );
    }

    // Relationship filters
    if (filters.initiatorId) {
      results = results.filter(s => s.initiator.agentId === filters.initiatorId);
    }
    if (filters.responderId) {
      results = results.filter(s => 
        s.responses.some(r => r.respondingAgentId === filters.responderId)
      );
    }
    if (filters.category && filters.category.length > 0) {
      results = results.filter(s => 
        filters.category!.includes(s.initiator.category) ||
        s.participants.some(p => filters.category!.includes(p.category))
      );
    }

    // Calculate facets before pagination
    const facets = this.calculateFacets(results);

    const total = results.length;

    // Sorting
    if (filters.sortBy) {
      results = this.sortResults(results, filters.sortBy, filters.sortOrder || 'desc');
    }

    // Pagination
    const offset = filters.offset || 0;
    const limit = filters.limit || 50;
    const paginatedResults = results.slice(offset, offset + limit);
    const hasMore = results.length > offset + limit;

    return {
      sessions: paginatedResults,
      total,
      hasMore,
      facets,
    };
  }

  private sortResults(
    sessions: ConsultationSession[],
    sortBy: SessionSearchFilters['sortBy'],
    order: 'asc' | 'desc'
  ): ConsultationSession[] {
    const multiplier = order === 'asc' ? 1 : -1;

    return sessions.sort((a, b) => {
      switch (sortBy) {
        case 'createdAt':
          return multiplier * (new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
        case 'updatedAt':
          return multiplier * (new Date(a.updatedAt).getTime() - new Date(b.updatedAt).getTime());
        case 'priority':
          const priorityOrder = { emergency: 0, critical: 1, high: 2, medium: 3, low: 4 };
          const aPriority = priorityOrder[a.requests[a.requests.length - 1]?.priority || 'medium'];
          const bPriority = priorityOrder[b.requests[b.requests.length - 1]?.priority || 'medium'];
          return multiplier * (aPriority - bPriority);
        case 'status':
          const statusOrder = { pending: 0, in_progress: 1, escalated: 2, completed: 3, rejected: 4, timeout: 5 };
          return multiplier * (statusOrder[a.status] - statusOrder[b.status]);
        case 'topic':
          return multiplier * (a.requests[0]?.topic || '').localeCompare(b.requests[0]?.topic || '');
        default:
          return 0;
      }
    });
  }

  private calculateFacets(sessions: ConsultationSession[]): SearchFacets {
    const byStatus: Record<string, number> = {};
    const byMode: Record<string, number> = {};
    const byPriority: Record<string, number> = {};
    const byType: Record<string, number> = {};
    const byMonth: Record<string, number> = {};
    const byAgentMap: Record<string, { agentId: string; agentName: string; count: number }> = {};

    for (const session of sessions) {
      // Status
      byStatus[session.status] = (byStatus[session.status] || 0) + 1;

      // Mode
      const latestRequest = session.requests[session.requests.length - 1];
      const mode = latestRequest?.counselingContext?.relationship || 'unknown';
      byMode[mode] = (byMode[mode] || 0) + 1;

      // Priority
      const priority = latestRequest?.priority || 'medium';
      byPriority[priority] = (byPriority[priority] || 0) + 1;

      // Type
      const type = latestRequest?.type || 'unknown';
      byType[type] = (byType[type] || 0) + 1;

      // Month
      const month = new Date(session.createdAt).toISOString().slice(0, 7);
      byMonth[month] = (byMonth[month] || 0) + 1;

      // Agents
      if (!byAgentMap[session.initiator.agentId]) {
        byAgentMap[session.initiator.agentId] = {
          agentId: session.initiator.agentId,
          agentName: session.initiator.agentName,
          count: 0,
        };
      }
      byAgentMap[session.initiator.agentId].count++;
    }

    return {
      byStatus,
      byMode,
      byPriority,
      byType,
      byMonth,
      byAgent: Object.values(byAgentMap).sort((a, b) => b.count - a.count).slice(0, 10),
    };
  }

  // ============================================
  // FULL-TEXT SEARCH
  // ============================================

  fullTextSearch(
    sessions: ConsultationSession[],
    options: FullTextSearchOptions
  ): ConsultationSession[] {
    const query = options.caseSensitive ? options.query : options.query.toLowerCase();
    const fields = options.fields || ['topic', 'question', 'answer'];

    return sessions.filter(session => {
      const searchableContent: string[] = [];

      if (fields.includes('topic')) {
        searchableContent.push(...session.requests.map(r => r.topic));
      }
      if (fields.includes('question')) {
        searchableContent.push(...session.requests.map(r => r.question));
      }
      if (fields.includes('answer')) {
        searchableContent.push(...session.responses.map(r => r.answer));
      }
      if (fields.includes('recommendations')) {
        searchableContent.push(...session.responses.flatMap(r => r.recommendations));
      }
      if (fields.includes('context')) {
        searchableContent.push(
          ...session.requests.map(r => JSON.stringify(r.context))
        );
      }

      const contentToSearch = searchableContent.join(' ');
      const searchContent = options.caseSensitive ? contentToSearch : contentToSearch.toLowerCase();

      if (options.fuzzy) {
        return this.fuzzyMatch(searchContent, query);
      }

      return searchContent.includes(query);
    });
  }

  private fuzzyMatch(text: string, query: string): boolean {
    // Simple fuzzy matching - check if all characters of query appear in order
    let queryIndex = 0;
    for (let i = 0; i < text.length && queryIndex < query.length; i++) {
      if (text[i] === query[queryIndex]) {
        queryIndex++;
      }
    }
    return queryIndex === query.length;
  }

  // ============================================
  // SAVED SEARCHES
  // ============================================

  private savedSearches: Map<string, SavedSearch> = new Map();

  saveSearch(userId: string, name: string, filters: SessionSearchFilters): SavedSearch {
    const saved: SavedSearch = {
      id: randomUUID(),
      userId,
      name,
      filters,
      createdAt: new Date(),
    };
    this.savedSearches.set(saved.id, saved);
    return saved;
  }

  getSavedSearches(userId: string): SavedSearch[] {
    return Array.from(this.savedSearches.values())
      .filter(s => s.userId === userId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }

  deleteSavedSearch(searchId: string): boolean {
    return this.savedSearches.delete(searchId);
  }

  // ============================================
  // QUICK FILTERS
  // ============================================

  getQuickFilters(agentId: string): QuickFilter[] {
    return [
      {
        id: 'my_sessions',
        label: 'My Sessions',
        description: 'Sessions where I am involved',
        filter: { participantIds: [agentId] },
        icon: 'user',
      },
      {
        id: 'initiated_by_me',
        label: 'Initiated by Me',
        description: 'Sessions I started',
        filter: { initiatorId: agentId },
        icon: 'send',
      },
      {
        id: 'awaiting_response',
        label: 'Awaiting Response',
        description: 'Sessions waiting for my response',
        filter: { status: ['pending', 'in_progress'], responderId: agentId },
        icon: 'clock',
      },
      {
        id: 'high_priority',
        label: 'High Priority',
        description: 'Critical and high priority sessions',
        filter: { priority: ['critical', 'high', 'emergency'] },
        icon: 'alert',
      },
      {
        id: 'recently_completed',
        label: 'Recently Completed',
        description: 'Sessions completed in last 7 days',
        filter: { 
          status: ['completed'],
          completedAfter: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
        },
        icon: 'check',
      },
      {
        id: 'escalated',
        label: 'Escalated',
        description: 'Sessions that have been escalated',
        filter: { isEscalated: true },
        icon: 'trending-up',
      },
    ];
  }
}

interface SearchableSessionData {
  id: string;
  status: string;
  createdAt: Date;
  updatedAt: Date;
  initiatorId: string;
  initiatorName: string;
  participantIds: string[];
  participantNames: string[];
  topics: string[];
  questions: string[];
  answers: string[];
  recommendations: string[];
  priorities: string[];
  types: string[];
  tags: string[];
  counselingContext: any[];
  confidence: number[];
}

interface SavedSearch {
  id: string;
  userId: string;
  name: string;
  filters: SessionSearchFilters;
  createdAt: Date;
}

interface QuickFilter {
  id: string;
  label: string;
  description: string;
  filter: Partial<SessionSearchFilters>;
  icon: string;
}

// Singleton instance
export const sessionSearchService = new SessionSearchService();

// Convenience functions
export function searchCounselingSessions(
  sessions: ConsultationSession[],
  filters: SessionSearchFilters
): SessionSearchResult {
  return sessionSearchService.searchSessions(sessions, filters);
}

export function fullTextSearchSessions(
  sessions: ConsultationSession[],
  options: FullTextSearchOptions
): ConsultationSession[] {
  return sessionSearchService.fullTextSearch(sessions, options);
}

export function saveSearchFilter(
  userId: string,
  name: string,
  filters: SessionSearchFilters
): SavedSearch {
  return sessionSearchService.saveSearch(userId, name, filters);
}

export function getQuickSessionFilters(agentId: string): QuickFilter[] {
  return sessionSearchService.getQuickFilters(agentId);
}

export default sessionSearchService;

/**
 * Social CRM AI Agent Integration Service
 * Integrates Sales & Revenue AI and Customer Experience AI agents with CRM functionality
 * Supports agent-to-agent consulting for customer relationship management
 */

import { AIAgent } from '../../constants/aiAgentHierarchy';
import { 
  a2aCommunicationService, 
  ConsultationSession 
} from '../services/a2a-communication-service';

// ============================================
// TYPES & INTERFACES
// ============================================

export interface CRMContact {
  id: string;
  name: string;
  email: string;
  phone?: string;
  company?: string;
  title?: string;
  status: 'lead' | 'prospect' | 'customer' | 'churned' | 'champion';
  source: string;
  tags: string[];
  assignedAgentId?: string;
  assignedSalesRepId?: string;
  score: number; // 0-100 lead score
  lastActivityAt?: Date;
  createdAt: Date;
  customFields?: Record<string, any>;
}

export interface CRMDeal {
  id: string;
  name: string;
  contactId: string;
  value: number;
  currency: string;
  stage: 'prospecting' | 'qualification' | 'proposal' | 'negotiation' | 'closed_won' | 'closed_lost';
  probability: number;
  expectedCloseDate: Date;
  assignedAgentId?: string;
  activities: string[];
  notes: string[];
  createdAt: Date;
  updatedAt: Date;
}

export interface CRMActivity {
  id: string;
  type: 'call' | 'email' | 'meeting' | 'note' | 'task' | 'deal_created' | 'deal_updated';
  contactId?: string;
  dealId?: string;
  agentId?: string;
  description: string;
  timestamp: Date;
  metadata?: Record<string, any>;
}

export interface CRMTask {
  id: string;
  type: 'lead_qualification' | 'deal_management' | 'contact_update' | 'follow_up' | 'negotiation' | 'escalation';
  agentId: string;
  status: 'pending' | 'in_progress' | 'completed';
  input: Record<string, any>;
  output?: Record<string, any>;
  consultationIds?: string[];
  createdAt: Date;
  completedAt?: Date;
}

export interface LeadScoreResult {
  score: number;
  grade: 'A' | 'B' | 'C' | 'D';
  factors: { positive: string[]; negative: string[] };
  recommendations: string[];
  nextActions: string[];
}

// ============================================
// SOCIAL CRM AI AGENT SERVICE
// ============================================

class SocialCRMAgentService {
  private tasks: Map<string, CRMTask> = new Map();
  private contacts: Map<string, CRMContact> = new Map();
  private deals: Map<string, CRMDeal> = new Map();
  private activities: Map<string, CRMActivity> = new Map();

  // ============================================
  // LEAD MANAGEMENT
  // ============================================

  /**
   * AI Lead Development Rep (SDR) qualifies leads
   * Consults with Sales Rep for complex qualification scenarios
   */
  async qualifyLead(
    contact: CRMContact,
    sdrId: string = 'ai-lead-dev-rep'
  ): Promise<{ task: CRMTask; score: LeadScoreResult; consultation?: ConsultationSession }> {
    const task = this.createTask('lead_qualification', sdrId, { contact });

    // Calculate lead score
    const score = this.calculateLeadScore(contact);

    let consultation: ConsultationSession | undefined;

    // If high-value lead, consult with Sales Rep
    if (score.score >= 80) {
      consultation = await a2aCommunicationService.peerConsultation(
        sdrId,
        'ai-sales-rep',
        'collaborative',
        `High-value lead: ${contact.name}`,
        `Lead ${contact.name} scored ${score.score}/100. Recommendations: ${score.recommendations.join(', ')}`
      );
      task.consultationIds = [consultation.id];

      // Update contact with sales rep assignment
      contact.assignedSalesRepId = 'ai-sales-rep';
    }

    contact.score = score.score;
    this.contacts.set(contact.id, contact);

    this.logActivity({
      type: 'note',
      contactId: contact.id,
      agentId: sdrId,
      description: `Lead qualified with score ${score.score}/100, grade ${score.grade}`,
    });

    this.completeTask(task.id, { score, contactId: contact.id });

    return { task, score, consultation };
  }

  /**
   * AI Sales Rep manages deal progression
   * Consults with Negotiator for deal closure
   */
  async manageDeal(
    deal: CRMDeal,
    action: 'progress' | 'negotiate' | 'close',
    salesRepId: string = 'ai-sales-rep'
  ): Promise<{ task: CRMTask; deal: CRMDeal; consultations: ConsultationSession[] }> {
    const task = this.createTask('deal_management', salesRepId, { deal, action });
    const consultations: ConsultationSession[] = [];

    if (action === 'negotiate') {
      // Consult with AI Negotiator for negotiation strategy
      const negotiationConsultation = await a2aCommunicationService.peerConsultation(
        salesRepId,
        'ai-negotiator',
        'advisory',
        `Negotiation strategy: ${deal.name}`,
        `Deal value: $${deal.value}, stage: ${deal.stage}. Need negotiation strategy.`
      );
      consultations.push(negotiationConsultation);

      // Consult with Pricing Strategist for pricing optimization
      const pricingConsultation = await a2aCommunicationService.peerConsultation(
        salesRepId,
        'ai-pricing-strategist',
        'analytical',
        `Pricing optimization: ${deal.name}`,
        `Optimize pricing strategy for deal ${deal.name}`
      );
      consultations.push(pricingConsultation);
    }

    if (action === 'close') {
      // Consult with Sales Executive for deal closure approval
      const closureConsultation = await a2aCommunicationService.subagentEscalatesToMainAgent(
        salesRepId,
        'sales-revenue-main',
        `Deal closure approval: ${deal.name}`,
        `Requesting approval to close deal ${deal.name} worth $${deal.value}`
      );
      consultations.push(closureConsultation);
    }

    // Update deal
    if (action === 'progress') {
      deal.stage = this.progressStage(deal.stage);
    } else if (action === 'close') {
      deal.stage = 'closed_won';
    }
    deal.updatedAt = new Date();
    this.deals.set(deal.id, deal);

    task.consultationIds = consultations.map(c => c.id);
    this.completeTask(task.id, { deal, action });

    this.logActivity({
      type: 'deal_updated',
      dealId: deal.id,
      contactId: deal.contactId,
      agentId: salesRepId,
      description: `Deal ${action}d to ${deal.stage}`,
    });

    return { task, deal, consultations };
  }

  // ============================================
  // CUSTOMER SUCCESS
  // ============================================

  /**
   * AI Account Manager handles customer success
   * Consults with Upsell Agent for expansion opportunities
   */
  async manageAccount(
    contactId: string,
    action: 'health_check' | 'expansion' | 'renewal' | 'risk_assessment',
    accountManagerId: string = 'ai-account-manager'
  ): Promise<{ task: CRMTask; result: any; consultation?: ConsultationSession }> {
    const contact = this.contacts.get(contactId);
    if (!contact) throw new Error('Contact not found');

    const task = this.createTask('contact_update', accountManagerId, { contactId, action });

    let consultation: ConsultationSession | undefined;
    let result: any;

    switch (action) {
      case 'health_check':
        result = {
          healthScore: 85,
          status: 'healthy',
          lastEngagement: '2 days ago',
          satisfaction: 4.5,
        };
        break;

      case 'expansion':
        // Consult with Upsell Agent for expansion opportunities
        consultation = await a2aCommunicationService.peerConsultation(
          accountManagerId,
          'ai-upsell-cross-sell',
          'analytical',
          `Expansion opportunity: ${contact.name}`,
          `Identify upsell/cross-sell opportunities for ${contact.name}`
        );

        result = {
          opportunities: [
            { product: 'Premium Plan', probability: 0.75, potentialValue: 5000 },
            { product: 'Add-on Module', probability: 0.60, potentialValue: 2000 },
          ],
          recommendedApproach: 'Schedule QBR to discuss growth',
        };
        break;

      case 'risk_assessment':
        // Escalate to Retention Specialist if at risk
        consultation = await a2aCommunicationService.peerConsultation(
          accountManagerId,
          'ai-retention-specialist',
          'advisory',
          `Risk assessment: ${contact.name}`,
          `Assess churn risk for ${contact.name}`
        );

        result = {
          riskLevel: 'low',
          factors: ['High engagement', 'Recent expansion'],
          recommendations: ['Continue regular check-ins'],
        };
        break;
    }

    if (consultation) {
      task.consultationIds = [consultation.id];
    }

    this.completeTask(task.id, { result, action });

    return { task, result, consultation };
  }

  // ============================================
  // MAIN/SUBAGENT CONSULTING
  // ============================================

  /**
   * Sales & Revenue Main Agent coordinates deal strategy
   */
  async coordinateDealStrategy(
    dealId: string,
    participatingAgentIds: string[]
  ): Promise<{ consultations: ConsultationSession[]; strategy: any }> {
    const mainAgentId = 'sales-revenue-main';
    const consultations: ConsultationSession[] = [];

    for (const agentId of participatingAgentIds) {
      const consultation = await a2aCommunicationService.mainAgentConsultsSubagent(
        mainAgentId,
        agentId,
        `Deal strategy coordination: ${dealId}`,
        `Coordinate strategy for deal ${dealId}`,
        'high'
      );
      consultations.push(consultation);
    }

    const strategy = {
      approach: 'multi-touch',
      timeline: '2 weeks',
      keyStakeholders: participatingAgentIds,
      riskMitigation: ['Competitor analysis', 'Pricing flexibility'],
    };

    return { consultations, strategy };
  }

  /**
   * Escalate complex CRM scenario to Main Agent
   */
  async escalateToMainAgent(
    subAgentId: string,
    escalationReason: string,
    context: Record<string, any>
  ): Promise<ConsultationSession> {
    return a2aCommunicationService.subagentEscalatesToMainAgent(
      subAgentId,
      'sales-revenue-main',
      `CRM Escalation: ${escalationReason}`,
      escalationReason,
      context
    );
  }

  /**
   * Cross-functional consultation between Sales and Customer Experience agents
   */
  async crossFunctionalConsultation(
    salesAgentId: string,
    customerExperienceAgentId: string,
    contactId: string,
    topic: string
  ): Promise<ConsultationSession> {
    return a2aCommunicationService.peerConsultation(
      salesAgentId,
      customerExperienceAgentId,
      'collaborative',
      `Cross-functional: ${topic}`,
      `Collaborative approach for contact ${contactId}: ${topic}`
    );
  }

  // ============================================
  // CRM AUTOMATION
  // ============================================

  /**
   * AI CRM Assistant automates CRM updates
   */
  async automateCRMUpdate(
    updateType: 'contact' | 'deal' | 'activity',
    data: any,
    crmAssistantId: string = 'ai-crm-assistant'
  ): Promise<CRMTask> {
    const task = this.createTask('contact_update', crmAssistantId, { updateType, data });

    switch (updateType) {
      case 'contact':
        this.contacts.set(data.id, { ...this.contacts.get(data.id), ...data });
        break;
      case 'deal':
        this.deals.set(data.id, { ...this.deals.get(data.id), ...data, updatedAt: new Date() });
        break;
      case 'activity':
        this.logActivity(data);
        break;
    }

    this.completeTask(task.id, { updated: true, type: updateType });
    return task;
  }

  // ============================================
  // QUERY METHODS
  // ============================================

  getContact(contactId: string): CRMContact | undefined {
    return this.contacts.get(contactId);
  }

  getDeal(dealId: string): CRMDeal | undefined {
    return this.deals.get(dealId);
  }

  getContactDeals(contactId: string): CRMDeal[] {
    return Array.from(this.deals.values()).filter(d => d.contactId === contactId);
  }

  getContactActivities(contactId: string): CRMActivity[] {
    return Array.from(this.activities.values())
      .filter(a => a.contactId === contactId)
      .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
  }

  getTasksByAgent(agentId: string): CRMTask[] {
    return Array.from(this.tasks.values()).filter(t => t.agentId === agentId);
  }

  getHighValueLeads(minScore: number = 80): CRMContact[] {
    return Array.from(this.contacts.values())
      .filter(c => c.score >= minScore && c.status === 'lead')
      .sort((a, b) => b.score - a.score);
  }

  getPipelineDeals(): CRMDeal[] {
    return Array.from(this.deals.values())
      .filter(d => !['closed_won', 'closed_lost'].includes(d.stage))
      .sort((a, b) => b.value - a.value);
  }

  getServiceStats(): {
    totalContacts: number;
    totalDeals: number;
    totalPipelineValue: number;
    tasksCompleted: number;
    activeConsultations: number;
    avgDealSize: number;
  } {
    const deals = Array.from(this.deals.values());
    const pipelineDeals = deals.filter(d => !['closed_won', 'closed_lost'].includes(d.stage));

    return {
      totalContacts: this.contacts.size,
      totalDeals: this.deals.size,
      totalPipelineValue: pipelineDeals.reduce((sum, d) => sum + d.value, 0),
      tasksCompleted: Array.from(this.tasks.values()).filter(t => t.status === 'completed').length,
      activeConsultations: Array.from(this.tasks.values()).filter(t => 
        t.consultationIds && t.consultationIds.length > 0
      ).length,
      avgDealSize: deals.length > 0 
        ? deals.reduce((sum, d) => sum + d.value, 0) / deals.length 
        : 0,
    };
  }

  // ============================================
  // PRIVATE HELPERS
  // ============================================

  private createTask(
    type: CRMTask['type'],
    agentId: string,
    input: Record<string, any>
  ): CRMTask {
    const task: CRMTask = {
      id: this.generateId(),
      type,
      agentId,
      status: 'pending',
      input,
      createdAt: new Date(),
    };
    this.tasks.set(task.id, task);
    return task;
  }

  private completeTask(taskId: string, output: Record<string, any>): void {
    const task = this.tasks.get(taskId);
    if (task) {
      task.status = 'completed';
      task.output = output;
      task.completedAt = new Date();
    }
  }

  private logActivity(activity: Omit<CRMActivity, 'id' | 'timestamp'>): void {
    const fullActivity: CRMActivity = {
      ...activity,
      id: this.generateId(),
      timestamp: new Date(),
    };
    this.activities.set(fullActivity.id, fullActivity);
  }

  private calculateLeadScore(contact: CRMContact): LeadScoreResult {
    let score = 50; // Base score
    const positive: string[] = [];
    const negative: string[] = [];

    // Positive factors
    if (contact.company) {
      score += 15;
      positive.push('Has company information');
    }
    if (contact.title?.toLowerCase().includes('director') || contact.title?.toLowerCase().includes('manager')) {
      score += 20;
      positive.push('Decision maker title');
    }
    if (contact.source === 'referral') {
      score += 25;
      positive.push('Referral source');
    }
    if (contact.tags.includes('enterprise')) {
      score += 15;
      positive.push('Enterprise segment');
    }

    // Negative factors
    if (!contact.phone) {
      score -= 10;
      negative.push('No phone number');
    }
    if (contact.tags.includes('competitor')) {
      score -= 20;
      negative.push('Competitor association');
    }

    score = Math.max(0, Math.min(100, score));

    let grade: 'A' | 'B' | 'C' | 'D' = 'D';
    if (score >= 80) grade = 'A';
    else if (score >= 60) grade = 'B';
    else if (score >= 40) grade = 'C';

    return {
      score,
      grade,
      factors: { positive, negative },
      recommendations: [
        'Schedule discovery call within 24 hours',
        'Research company background',
        'Prepare personalized demo',
      ],
      nextActions: score >= 80 
        ? ['Immediate outreach', 'Priority handling'] 
        : ['Nurture with content', 'Schedule follow-up'],
    };
  }

  private progressStage(currentStage: CRMDeal['stage']): CRMDeal['stage'] {
    const stages: CRMDeal['stage'][] = ['prospecting', 'qualification', 'proposal', 'negotiation', 'closed_won'];
    const currentIndex = stages.indexOf(currentStage);
    return stages[Math.min(currentIndex + 1, stages.length - 1)];
  }

  private generateId(): string {
    return `crm_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

