   * Get webhook delivery
   */
  async getDelivery(deliveryId: string, organizationId: string): Promise<WebhookDelivery | null> {
    try {
      const delivery = this.activeDeliveries.get(deliveryId);
      if (delivery) {
        // Verify organization access
        const webhook = await this.getWebhook(delivery.webhookId, organizationId);
        if (webhook) {
          return delivery;
        }
      }
      return null;
    } catch (error) {
      logger.error('[WebhookService] Failed to get delivery:', error);
      throw new Error('Failed to get delivery');
    }
  }

  /**
   * List webhook deliveries
   */
  async listDeliveries(organizationId: string, filters?: {
    webhookId?: string;
    status?: string;
    dateRange?: { start: Date; end: Date };
    limit?: number;
    offset?: number;
  }): Promise<WebhookDelivery[]> {
    try {
      const deliveries = Array.from(this.activeDeliveries.values())
        .filter(async (delivery) => {
          const webhook = await this.getWebhook(delivery.webhookId, organizationId);
          return webhook !== null;
        })
        .filter(delivery => !filters.webhookId || delivery.webhookId === filters.webhookId)
        .filter(delivery => !filters.status || delivery.status === filters.status)
        .filter(delivery => {
          if (!filters.dateRange) return true;
          return delivery.createdAt >= filters.dateRange.start && delivery.createdAt <= filters.dateRange.end;
        })
        .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
        .slice(filters.offset || 0, (filters.offset || 0) + (filters.limit || 50));

      return deliveries;
    } catch (error) {
      logger.error('[WebhookService] Failed to list deliveries:', error);
      throw new Error('Failed to list deliveries');
    }
  }

  /**
   * Retry webhook delivery
   */
  async retryDelivery(deliveryId: string, organizationId: string): Promise<boolean> {
    try {
      const delivery = await this.getDelivery(deliveryId, organizationId);
      if (!delivery) {
        return false;
      }

      if (delivery.status === 'delivered') {
        return false;
      }

      // Reset delivery status
      delivery.status = 'pending';
      delivery.attempts = 0;
      delivery.error = undefined;
      delivery.updatedAt = new Date();

      // Add to queue
      this.deliveryQueue.push(delivery);
      this.processQueue();

      this.emit('webhook:retry', delivery);
      return true;
    } catch (error) {
      logger.error('[WebhookService] Failed to retry delivery:', error);
      throw new Error('Failed to retry delivery');
    }
  }

  /**
   * Get webhook statistics
   */
  async getWebhookStats(organizationId: string): Promise<WebhookStats> {
    try {
      const deliveries = Array.from(this.activeDeliveries.values())
        .filter(async (delivery) => {
          const webhook = await this.getWebhook(delivery.webhookId, organizationId);
          return webhook !== null;
        });

      const successfulDeliveries = deliveries.filter(d => d.status === 'delivered');
      const failedDeliveries = deliveries.filter(d => d.status === 'failed');

      const successRate = deliveries.length > 0
        ? successfulDeliveries.length / deliveries.length
        : 0;

      const averageDeliveryTime = successfulDeliveries.length > 0
        ? successfulDeliveries.reduce((sum, d) => sum + (d.response?.duration || 0), 0) / successfulDeliveries.length
        : 0;

      const deliveriesByStatus = deliveries.reduce((acc, delivery) => {
        acc[delivery.status] = (acc[delivery.status] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);

      // Group by webhook
      const deliveriesByWebhook = deliveries.reduce((acc, delivery) => {
        const existing = acc.find(item => item.webhookId === delivery.webhookId);
        if (existing) {
          existing.deliveries++;
          if (delivery.status === 'delivered') existing.successRate++;
        } else {
          acc.push({
            webhookId: delivery.webhookId,
            webhookName: `Webhook ${delivery.webhookId}`, // Would get actual name
            deliveries: 1,
            successRate: delivery.status === 'delivered' ? 1 : 0,
          });
        }
        return acc;
      }, [] as { webhookId: string; webhookName: string; deliveries: number; successRate: number }[]);

      // Calculate success rates
      deliveriesByWebhook.forEach(item => {
        item.successRate = item.deliveries > 0 ? item.successRate / item.deliveries : 0;
      });

      const recentDeliveries = deliveries
        .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
        .slice(0, 10);

      return {
        totalWebhooks: 0, // Would query actual count
        activeWebhooks: 0, // Would query actual count
        totalDeliveries: deliveries.length,
        successfulDeliveries: successfulDeliveries.length,
        failedDeliveries: failedDeliveries.length,
        successRate,
        averageDeliveryTime,
        deliveriesByStatus,
        deliveriesByWebhook,
        recentDeliveries,
      };
    } catch (error) {
      logger.error('[WebhookService] Failed to get webhook stats:', error);
      throw new Error('Failed to get webhook stats');
    }
  }

  /**
   * Process delivery queue
   */
  private async processQueue(): Promise<void> {
    if (this.isProcessingQueue || this.deliveryQueue.length === 0) {
      return;
    }

    this.isProcessingQueue = true;

    try {
      while (this.deliveryQueue.length > 0 && this.activeDeliveries.size < this.maxConcurrentDeliveries) {
        const delivery = this.deliveryQueue.shift()!;
        await this.processDelivery(delivery);
      }
    } catch (error) {
      logger.error('[WebhookService] Error processing queue:', error);
    } finally {
      this.isProcessingQueue = false;
    }
  }

  /**
   * Process individual delivery
   */
  private async processDelivery(delivery: WebhookDelivery): Promise<void> {
    try {
      delivery.status = 'retrying';
      delivery.attempts++;
      delivery.lastAttempt = new Date();
      delivery.updatedAt = new Date();

      this.activeDeliveries.set(delivery.id, delivery);

      // Get webhook
      const webhook = await this.getWebhook(delivery.webhookId, '');
      if (!webhook) {
        throw new Error('Webhook not found');
      }

      // Get event
      const event = await this.getEvent(delivery.eventId);
      if (!event) {
        throw new Error('Event not found');
      }

      // Set timeout
      const timeout = setTimeout(() => {
        this.handleDeliveryTimeout(delivery.id);
      }, webhook.retryPolicy.timeoutMs);

      this.deliveryTimeouts.set(delivery.id, timeout);

      // Deliver webhook
      const result = await this.deliverWebhook(webhook, event);

      // Clear timeout
      clearTimeout(timeout);
      this.deliveryTimeouts.delete(delivery.id);

      if (result.success) {
        delivery.status = 'delivered';
        delivery.response = {
          statusCode: result.statusCode || 200,
          headers: result.headers || {},
          body: JSON.stringify(result.data || {}),
          duration: result.duration || 0,
        };
      } else {
        delivery.status = 'failed';
        delivery.error = result.error;

        // Check if should retry
        if (delivery.attempts < webhook.retryPolicy.maxAttempts) {
          delivery.status = 'pending';
          delivery.nextRetry = new Date(Date.now() + webhook.retryPolicy.backoffMs * delivery.attempts);

          // Schedule retry
          setTimeout(() => {
            this.deliveryQueue.push(delivery);
            this.processQueue();
          }, webhook.retryPolicy.backoffMs * delivery.attempts);
        }
      }

      delivery.updatedAt = new Date();

      this.emit('webhook:delivered', delivery);
    } catch (error) {
      delivery.status = 'failed';
      delivery.error = error instanceof Error ? error.message : 'Unknown error';
      delivery.updatedAt = new Date();

      this.emit('webhook:failed', delivery);
    } finally {
      // Clean up after delay
      setTimeout(() => {
        this.activeDeliveries.delete(delivery.id);
      }, 60000); // Keep in memory for 1 minute
    }
  }

  /**
   * Deliver webhook to endpoint
   */
  private async deliverWebhook(webhook: WebhookDefinition, event: WebhookEvent): Promise<{
    success: boolean;
    statusCode?: number;
    headers?: Record<string, string>;
    data?: any;
    error?: string;
    duration?: number;
  }> {
    try {
      const startTime = Date.now();

      // Prepare payload
      const payload = {
        id: event.id,
        type: event.type,
        data: event.data,
        timestamp: event.timestamp.toISOString(),
        source: event.source,
        version: event.version,
        metadata: event.metadata,
      };

      // Prepare headers
      const headers = {
        'Content-Type': 'application/json',
        'User-Agent': 'WebhookService/1.0',
        'X-Webhook-ID': webhook.id,
        'X-Event-ID': event.id,
        'X-Event-Type': event.type,
        ...webhook.headers,
      };

      // Add signature if secret is configured
      if (webhook.secret) {
        const signature = this.generateSignature(JSON.stringify(payload), webhook.secret);
        headers['X-Webhook-Signature'] = signature;
      }

      // Make request
      const response = await fetch(webhook.url, {
        method: 'POST',
        headers,
        body: JSON.stringify(payload),
      });

      const duration = Date.now() - startTime;

      if (response.ok) {
        return {
          success: true,
          statusCode: response.status,
          headers: Object.fromEntries(response.headers.entries()),
          data: await response.json(),
          duration,
        };
      } else {
        return {
          success: false,
          statusCode: response.status,
          headers: Object.fromEntries(response.headers.entries()),
          error: `HTTP ${response.status}: ${response.statusText}`,
          duration,
        };
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Generate webhook signature
   */
  private generateSignature(payload: string, secret: string): string {
    return crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');
  }

  /**
   * Get event by ID
   */
  private async getEvent(eventId: string): Promise<WebhookEvent | null> {
    // Simplified - would query actual database
    return null;
  }

  /**
   * Handle delivery timeout
   */
  private handleDeliveryTimeout(deliveryId: string): void {
    const delivery = this.activeDeliveries.get(deliveryId);
    if (delivery) {
      delivery.status = 'failed';
      delivery.error = 'Delivery timeout';
      delivery.updatedAt = new Date();

      this.deliveryTimeouts.delete(deliveryId);
      this.emit('webhook:timeout', delivery);
    }
  }

  /**
   * Verify webhook signature
   */
  verifySignature(payload: string, signature: string, secret: string): boolean {
    try {
      const expectedSignature = this.generateSignature(payload, secret);
      return verifyWebhookSignature(signature, expectedSignature);
    } catch (error) {
      logger.error('[WebhookService] Failed to verify signature:', error);
      return false;
    }
  }

  /**
   * Start queue processor
   */
  private startQueueProcessor(): void {
    this.queueProcessorInterval = setInterval(() => {
      this.processQueue();
    }, 1000); // Process queue every second
  }

  /**
   * Start cleanup process
   */
  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      this.cleanup();
    }, 60000); // Cleanup every minute
  }

  /**
   * Cleanup old deliveries
   */
  private cleanup(): void {
    const now = Date.now();
    const cutoff = now - 24 * 60 * 60 * 1000; // 24 hours ago

    for (const [id, delivery] of this.activeDeliveries.entries()) {
      if (delivery.updatedAt.getTime() < cutoff) {
        this.activeDeliveries.delete(id);
      }
    }
  }

  /**
   * Cleanup resources
   */
  cleanup(): void {
    // Clear timeouts
    for (const timeout of this.deliveryTimeouts.values()) {
      clearTimeout(timeout);
    }
    this.deliveryTimeouts.clear();

    // Clear queues and active deliveries
    this.deliveryQueue = [];
    this.activeDeliveries.clear();
    this.deliveryTimeouts.clear();
    this.removeAllListeners();
  }

  /**
   * Destroy the service
   */
  destroy(): void {
    if (this.queueProcessorInterval) {
      clearInterval(this.queueProcessorInterval);
    }
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
    }
    // Clear all delivery timeouts
    for (const timeout of this.deliveryTimeouts.values()) {
      clearTimeout(timeout);
    }
    this.deliveryQueue = [];
    this.activeDeliveries.clear();
    this.deliveryTimeouts.clear();
    this.removeAllListeners();
  }
}

export const unifiedWebhookService = new UnifiedWebhookService();

import { db } from '../db/connection';
import { eq, and, gte, lte, desc, sql, inArray } from 'drizzle-orm';
import * as crypto from 'crypto';
import { EventEmitter } from 'events';
import { workflows, workflowExecutions } from '../db/drizzle-schema';

import { createLogger } from '../lib/production-logger';

const logger = createLogger(__filename.split('/').pop()?.replace('.ts', '') || 'Service');

export interface WorkflowDefinition {
  id: string;
  organizationId: string;
  name: string;
  description: string;
  trigger: {
    type: 'manual' | 'scheduled' | 'event' | 'webhook';
    config: Record<string, any>;
  };
  steps: WorkflowStep[];
  settings: {
    timeout?: number;
    retryPolicy?: {
      maxAttempts: number;
      backoffMs: number;
    };
    notifications?: {
      onSuccess?: string[];
      onFailure?: string[];
    };
  };
  status: 'active' | 'inactive' | 'archived';
  createdAt: Date;
  updatedAt: Date;
}

export interface WorkflowStep {
  id: string;
  type: 'action' | 'condition' | 'parallel' | 'delay' | 'webhook' | 'email' | 'data_transform';
  name: string;
  config: Record<string, any>;
  nextSteps?: string[];
  condition?: {
    type: 'if' | 'switch';
    rules: {
      condition: string;
      nextStep: string;
    }[];
  };
}

export interface WorkflowExecution {
  id: string;
  workflowId: string;
  organizationId: string;
  triggerData: Record<string, any>;
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  currentStepId?: string;
  stepResults: {
    stepId: string;
    status: 'pending' | 'running' | 'completed' | 'failed' | 'skipped';
    result?: any;
    error?: string;
    startedAt?: Date;
    completedAt?: Date;
  }[];
  metadata: {
    triggeredBy?: string;
    triggeredAt: Date;
    completedAt?: Date;
    error?: string;
    retryCount?: number;
  };
  createdAt: Date;
  updatedAt: Date;
}

export interface WorkflowTemplate {
  id: string;
  name: string;
  description: string;
  category: string;
  definition: Omit<WorkflowDefinition, 'id' | 'organizationId' | 'createdAt' | 'updatedAt'>;
  tags: string[];
  isPublic: boolean;
  createdBy: string;
  createdAt: Date;
}

export interface WorkflowExecutionContext {
  executionId: string;
  workflowId: string;
  organizationId: string;
  triggerData: Record<string, any>;
  stepResults: Record<string, any>;
  variables: Record<string, any>;
}

export class UnifiedWorkflowService extends EventEmitter {
  private activeExecutions: Map<string, WorkflowExecution> = new Map();
  private stepHandlers: Map<string, (step: WorkflowStep, context: WorkflowExecutionContext) => Promise<any>> = new Map();
  private executionQueue: WorkflowExecution[] = [];
  private maxConcurrentExecutions: number = 10;
  private queueProcessorInterval?: NodeJS.Timeout;
  private isProcessingQueue: boolean = false;

  constructor() {
    super();
    this.initializeStepHandlers();
    this.startQueueProcessor();
  }

  /**
   * Create a new workflow
   */
  async createWorkflow(organizationId: string, workflowData: Omit<WorkflowDefinition, 'id' | 'createdAt' | 'updatedAt'>): Promise<WorkflowDefinition> {
    try {
      const workflow: WorkflowDefinition = {
        ...workflowData,
        id: crypto.randomUUID(),
        organizationId,
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      // Store workflow in database (simplified - would use actual workflow table)
      logger.info(`Created workflow: ${workflow.id} for org: ${organizationId}`);

      this.emit('workflow:created', workflow);
      return workflow;
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('[WorkflowService] Failed to create workflow:', error);
      throw new Error(`Failed to create workflow: ${errorMessage}`);
    }
  }

  /**
   * Execute a workflow
   */
  async executeWorkflow(workflowId: string, organizationId: string, triggerData: Record<string, any>): Promise<WorkflowExecution> {
    try {
      // Get workflow definition
      const workflow = await this.getWorkflow(workflowId, organizationId);
      if (!workflow) {
        throw new Error('Workflow not found');
      }

      const execution: WorkflowExecution = {
        id: crypto.randomUUID(),
        workflowId,
        organizationId,
        triggerData,
        status: 'pending',
        stepResults: [],
        metadata: {
          triggeredAt: new Date(),
          retryCount: 0,
        },
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      // Store execution
      this.activeExecutions.set(execution.id, execution);

      // Add to queue
      this.executionQueue.push(execution);
      this.processQueue();

      this.emit('workflow:started', execution);
      return execution;
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('[WorkflowService] Failed to execute workflow:', error);
      throw new Error(`Failed to execute workflow: ${errorMessage}`);
    }
  }

  /**
   * Get workflow by ID
   */
  async getWorkflow(workflowId: string, organizationId: string): Promise<WorkflowDefinition | null> {
    try {
      const [workflow] = await db.select()
        .from(workflows)
        .where(and(
          eq(workflows.id, workflowId),
          eq(workflows.organizationId, organizationId)
        ))
        .limit(1);

      if (!workflow) return null;

      // Map database record to WorkflowDefinition interface
      return {
        id: workflow.id,
        organizationId: workflow.organizationId,
        name: workflow.name,
        description: workflow.description || '',
        trigger: workflow.trigger as { type: 'manual' | 'scheduled' | 'event' | 'webhook'; config: Record<string, any> },
        steps: (workflow.actions as unknown as WorkflowStep[] || []).map((action: any, index: number) => ({
          id: action.id || `step-${index}`,
          type: action.type || 'action',
          name: action.name || `Step ${index + 1}`,
          config: action.config || {},
          nextSteps: action.nextSteps,
          condition: action.condition,
        })),
        settings: {
          timeout: 30000,
          retryPolicy: { maxAttempts: 3, backoffMs: 1000 },
          notifications: { onSuccess: [], onFailure: [] },
        },
        status: workflow.status as 'active' | 'inactive' | 'archived',
        createdAt: workflow.createdAt,
        updatedAt: workflow.updatedAt,
      };
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      logger.error('[WorkflowService] Failed to get workflow:', error);
      throw new Error(`Failed to get workflow: ${errorMessage}`);
    }
  }

  /**
   * List workflows for organization
   */
  async listWorkflows(organizationId: string, filters?: {
    status?: string;
    category?: string;
    limit?: number;
    offset?: number;
  }): Promise<WorkflowDefinition[]> {
    try {
      const conditions = [eq(workflows.organizationId, organizationId)];

      if (filters?.status) {
        conditions.push(eq(workflows.status, filters.status));
      }

      const workflowList = await db.select()
        .from(workflows)
        .where(and(...conditions))
        .orderBy(desc(workflows.updatedAt))
        .limit(filters?.limit || 50)
        .offset(filters?.offset || 0);

      return workflowList.map(workflow => ({
        id: workflow.id,
        organizationId: workflow.organizationId,
        name: workflow.name,
        description: workflow.description || '',
        trigger: workflow.trigger as { type: 'manual' | 'scheduled' | 'event' | 'webhook'; config: Record<string, any> },
        steps: (workflow.actions as unknown as WorkflowStep[] || []).map((action: any, index: number) => ({
          id: action.id || `step-${index}`,
          type: action.type || 'action',
          name: action.name || `Step ${index + 1}`,
          config: action.config || {},
          nextSteps: action.nextSteps,
          condition: action.condition,
        })),
        settings: {
          timeout: 30000,
          retryPolicy: { maxAttempts: 3, backoffMs: 1000 },
          notifications: { onSuccess: [], onFailure: [] },
        },
        status: workflow.status as 'active' | 'inactive' | 'archived',
        createdAt: workflow.createdAt,
        updatedAt: workflow.updatedAt,
      }));
    } catch (error: any) {
      logger.error('[WorkflowService] Failed to list workflows:', error);
      throw new Error('Failed to list workflows');
    }
  }

  /**
   * Update workflow
   */
  async updateWorkflow(workflowId: string, organizationId: string, updates: Partial<WorkflowDefinition>): Promise<WorkflowDefinition> {
    try {
      const existing = await this.getWorkflow(workflowId, organizationId);
      if (!existing) {
        throw new Error('Workflow not found');
      }

      // Update in database
      const [updated] = await db.update(workflows)
        .set({
          name: updates.name ?? existing.name,
          description: updates.description ?? existing.description,
          status: updates.status ?? existing.status,
          trigger: updates.trigger ?? existing.trigger,
          actions: updates.steps ? updates.steps.map(step => ({
            id: step.id,
            type: step.type,
            name: step.name,
            config: step.config,
            nextSteps: step.nextSteps,
            condition: step.condition,
          })) : existing.steps,
          updatedAt: new Date(),
        })
        .where(and(
          eq(workflows.id, workflowId),
          eq(workflows.organizationId, organizationId)
        ))
        .returning();

      const updatedWorkflow: WorkflowDefinition = {
        ...existing,
        ...updates,
        updatedAt: new Date(),
      };

      this.emit('workflow:updated', updatedWorkflow);
