        .from(aiAgents)
        .where(and(...whereParts))
        .orderBy(desc(aiAgents.createdAt));

      return {
        agents,
        count: agents.length,
      };
    } catch (error: any) {
      console.error('Failed to list agents:', error);
      throw new Error(error.message || 'Failed to list agents');
