import { Permission } from '../../../../lib/rbac';
import { whatsappService } from '../../../../services/whatsapp-service';
import { db as pgDb } from '../../../../db/connection';
import { platformConnections } from '../../../../db/drizzle-schema';
import { eq } from 'drizzle-orm';

const inputSchema = z.object({
  platformId: z.string(),
  platformName: z.string(),
  connectionType: z.enum(['qr-code', 'oauth', 'credentials', 'google-account']),
});

export const connectQRProcedure = permissionProcedure(Permission.PLATFORM_CREATE)
  .input(inputSchema)
  .mutation(async ({ input, ctx }: { input: z.infer<typeof inputSchema>; ctx: any }) => {
    try {
      console.log('Generating QR code for platform:', input.platformName);
      
      const userId = ctx.user?.id;
      const organizationId = ctx.user?.organizationId;
      if (!userId) {
        throw new Error('User not authenticated');
      }
      if (!organizationId) {
        throw new Error('User organization not found');
      }

      // Use real WhatsApp service for WhatsApp connections
      if (input.platformName.toLowerCase() === 'whatsapp') {
        const connection = await whatsappService.generateQRCode(userId, '');

        await pgDb
          .insert(platformConnections)
          .values({
            organizationId,
            platform: 'whatsapp',
            isActive: false,
            metadata: {
              status: 'pending_qr',
              platformId: input.platformId,
              platformName: input.platformName,
              sessionId: connection.sessionId,
              linkingCode: connection.linkingCode,
              expiresAt: connection.expiresAt.toISOString(),
              e2eEnabled: true,
              encryptionType: 'E2E-Encrypted',
            },
          } as any)
          .onConflictDoUpdate({
            target: [platformConnections.organizationId, platformConnections.platform],
            set: {
              isActive: false,
              metadata: {
                status: 'pending_qr',
                platformId: input.platformId,
                platformName: input.platformName,
                sessionId: connection.sessionId,
                linkingCode: connection.linkingCode,
                expiresAt: connection.expiresAt.toISOString(),
                e2eEnabled: true,
                encryptionType: 'E2E-Encrypted',
              },
              updatedAt: new Date(),
            },
          });
        
        return {
          success: true,
          qrCode: connection.qrCode,
          linkingCode: connection.linkingCode,
          sessionId: connection.sessionId,
          expiresAt: connection.expiresAt.toISOString(),
          e2eEnabled: true,
          encryptionType: 'E2E-Encrypted',
          publicKey: connection.encryptionKey.substring(0, 100) + '...',
        };
      }

      // For other platforms, return structured OAuth data
      return {
        success: true,
        qrCode: `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(JSON.stringify({
          platformId: input.platformId,
          platformName: input.platformName,
        }))}`,
        linkingCode: 'LINK' + Date.now().toString().slice(-4),
        sessionId: 'session-' + Date.now(),
        expiresAt: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
        e2eEnabled: true,
        encryptionType: 'RSA-2048',
        publicKey: 'PK_' + Math.random().toString(36).substr(2, 32),
      };
    } catch (error: any) {
      console.error('Failed to generate QR code:', error);
      throw new Error(error.message || 'Failed to generate QR code');
    }
  });

import { z } from "zod";
import { permissionProcedure } from '../../../create-context';
import { Permission } from '../../../../lib/rbac';
import { db as pgDb } from '../../../../db/connection';
import { platformConnections } from '../../../../db/drizzle-schema';
import { and, eq } from 'drizzle-orm';

const inputSchema = z.object({
  platformId: z.string(),
});

export const disconnectPlatformProcedure = permissionProcedure(Permission.PLATFORM_DELETE)
  .input(inputSchema)
  .mutation(async ({ input, ctx }: { input: z.infer<typeof inputSchema>; ctx: any }) => {
    console.log('Disconnecting platform:', input.platformId);

    const organizationId = ctx.user?.organizationId;
    if (!organizationId) {
      throw new Error('User organization not found');
    }

    const connections = await pgDb
      .select()
      .from(platformConnections)
      .where(eq(platformConnections.organizationId, organizationId as any));

    const existing = connections.find((c: any) => {
      const meta = c?.metadata || {};
      return String(meta.platformId || '') === String(input.platformId);
    });

    if (existing) {
      const meta = (existing as any).metadata || {};
      const mergedMetadata = {
        ...meta,
        status: 'disconnected',
        disconnectedAt: new Date().toISOString(),
        encryptedCredentials: null,
      };

      await pgDb
        .update(platformConnections)
        .set({ isActive: false, metadata: mergedMetadata as any, updatedAt: new Date() } as any)
        .where(eq(platformConnections.id, (existing as any).id));
    }
    
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    return {
      success: true,
      message: 'Platform disconnected successfully',
    };
  });

import { z } from "zod";
import { permissionProcedure } from '../../../create-context';
import { Permission } from '../../../../lib/rbac';
import { db as pgDb } from '../../../../db/connection';
import { platformConnections } from '../../../../db/drizzle-schema';
import { platformAuthService, PlatformType } from '../../../../services/platform-auth-service';
import { and, eq } from 'drizzle-orm';
import { platformSyncEngine } from '../../../../services/consolidated-platform-sync-service';

const inputSchema = z.object({
  platformId: z.string(),
});

export const syncPlatformProcedure = permissionProcedure(Permission.PLATFORM_UPDATE)
  .input(inputSchema)
  .mutation(async ({ input, ctx }: { input: z.infer<typeof inputSchema>; ctx: any }) => {
    console.log('Syncing platform:', input.platformId);

    const organizationId = ctx.user?.organizationId;
    if (!organizationId) {
      throw new Error('User organization not found');
    }

    const connections = await pgDb
      .select()
      .from(platformConnections)
      .where(eq(platformConnections.organizationId, organizationId as any));

    const conn = connections.find((c: any) => {
      const meta = c?.metadata || {};
      return String(meta.platformId || '') === String(input.platformId);
    });

    if (!conn) {
      throw new Error('Platform connection not found');
    }

    let status: string = (conn as any).metadata?.status || 'active';
    const platformType = String((conn as any).platform || '') as PlatformType;
    if ((conn as any).isActive) {
      await platformAuthService.ensureValidCredentialsForOrg(organizationId as string, platformType);
      const [refreshed] = await pgDb
        .select()
        .from(platformConnections)
        .where(eq(platformConnections.id, (conn as any).id))
        .limit(1);
      status = (refreshed as any)?.metadata?.status || status;
    }

    const result = await platformSyncEngine.enqueueAndRunConnectionSync({
      organizationId: organizationId as string,
      platform: platformType,
      connectionId: String((conn as any).id),
      jobType: 'manual_sync',
      payload: {
        platformId: input.platformId,
      },
    });

    return {
      success: true,
      lastSync: new Date().toISOString(),
      messageCount: result.messageCount,
      status: result.status,
    };
  });

