import { Hono } from 'hono';
import { z } from 'zod';

/**
 * API utility functions for consistent responses and error handling
 */

export class APIUtils {
  /**
   * Standard success response format
   */
  static success<T>(data: T, meta?: {
    message?: string;
    timestamp?: string;
    requestId?: string;
  }) {
    return {
      success: true,
      data,
      meta: {
        timestamp: meta?.timestamp || new Date().toISOString(),
        message: meta?.message,
        requestId: meta?.requestId,
      }
    };
  }

  /**
   * Standard error response format
   */
  static error(
    code: string,
    message: string,
    details?: any,
    meta?: {
      timestamp?: string;
      requestId?: string;
      traceId?: string;
    }
  ) {
    return {
      success: false,
      error: {
        code,
        message,
        details,
      },
      meta: {
        timestamp: meta?.timestamp || new Date().toISOString(),
        requestId: meta?.requestId,
        traceId: meta?.traceId,
      }
    };
  }

  /**
   * Extract pagination parameters
   */
  static getPaginationParams(c: Context): {
    limit: number;
    offset: number;
    page: number;
  } {
    const query = c.req.query();
    const limit = Math.min(parseInt(query.limit || '50'), 100);
    const offset = Math.max(parseInt(query.offset || '0'), 0);
    const page = Math.max(parseInt(query.page || '1'), 1);

    return { limit, offset, page };
  }

  /**
   * Build pagination metadata
   */
  static buildPaginationMeta(
    total: number,
    limit: number,
    offset: number,
    page: number
  ) {
    const totalPages = Math.ceil(total / limit);
    const hasNext = page < totalPages;
    const hasPrev = page > 1;

    return {
      pagination: {
        total,
        limit,
        offset,
        page,
        totalPages,
        hasNext,
        hasPrev,
        nextOffset: hasNext ? offset + limit : null,
        prevOffset: hasPrev ? Math.max(0, offset - limit) : null,
      }
    };
  }

  /**
   * Extract sorting parameters
   */
  static getSortingParams(c: Context, allowedFields: string[] = []): {
    sortBy?: string;
    sortOrder: 'asc' | 'desc';
  } {
    const query = c.req.query();
    let sortBy = query.sortBy;
    let sortOrder: 'asc' | 'desc' = 'desc';

    if (sortBy && allowedFields.length > 0) {
      sortBy = allowedFields.includes(sortBy) ? sortBy : allowedFields[0];
    }

    if (query.sortOrder?.toLowerCase() === 'asc') {
      sortOrder = 'asc';
    }

    return { sortBy, sortOrder };
  }

  /**
   * Extract filtering parameters
   */
  static getFilterParams(c: Context, schema?: z.ZodSchema): {
    filters: Record<string, any>;
    search?: string;
  } {
    const query = c.req.query();
    const filters: Record<string, any> = {};
    let search: string | undefined;

    Object.keys(query).forEach(key => {
      if (key === 'search') {
        search = query[key];
      } else if (key !== 'limit' && key !== 'offset' && key !== 'page' && 
                 key !== 'sortBy' && key !== 'sortOrder') {
        filters[key] = query[key];
      }
    });

    if (schema) {
      try {
        const validated = schema.parse(filters);
        return { filters: validated, search };
      } catch (error) {
        // Return original filters if validation fails
        return { filters, search };
      }
    }

    return { filters, search };
  }

  /**
   * Generate request ID
   */
  static generateRequestId(): string {
    return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Get client IP address from request
   */
  static getClientIP(c: Context): string {
    return (
      c.req.header('x-forwarded-for')?.split(',')[0]?.trim() ||
      c.req.header('x-real-ip') ||
      c.req.header('cf-connecting-ip') ||
      'unknown'
    );
  }

  /**
   * Get user agent from request
   */
  static getUserAgent(c: Context): string {
    return c.req.header('user-agent') || 'unknown';
  }

  /**
   * Validate API version
   */
  static validateAPIVersion(c: Context, supportedVersions: string[] = ['v1']): boolean {
    const version = c.req.header('api-version') || 
                   c.req.path.match(/^\/api\/([^\/]+)/)?.[1] ||
                   'v1';

    return supportedVersions.includes(version);
  }

  /**
   * Rate limiting response
   */
  static rateLimitResponse(
    retryAfter: number,
    limit: number,
    remaining: number,
    resetTime: number
  ) {
    return {
      success: false,
      error: {
        code: 'RATE_LIMIT_EXCEEDED',
        message: 'Too many requests. Please try again later.',
        details: {
          retryAfter,
          limit,
          remaining,
          resetTime: new Date(resetTime).toISOString(),
        }
      }
    };
  }

  /**
   * Health check response
   */
  static healthResponse(status: 'healthy' | 'degraded' | 'unhealthy', checks: Record<string, any>) {
    return {
      status,
      timestamp: new Date().toISOString(),
      checks,
      uptime: process.uptime(),
      version: process.env.npm_package_version || '1.0.0',
      environment: process.env.NODE_ENV || 'development'
    };
  }

  /**
   * Cache control headers
   */
  static setCacheHeaders(c: Context, maxAge: number, etag?: string) {
    if (etag) {
      c.header('ETag', etag);
    }
    c.header('Cache-Control', `public, max-age=${maxAge}`);
    c.header('Vary', 'Accept-Encoding');
  }

  /**
   * Security headers
   */
  static setSecurityHeaders(c: Context) {
    c.header('X-Content-Type-Options', 'nosniff');
    c.header('X-Frame-Options', 'DENY');
    c.header('X-XSS-Protection', '1; mode=block');
    c.header('Referrer-Policy', 'strict-origin-when-cross-origin');
    c.header('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  }

  /**
   * CORS headers for specific origin
   */
  static setCORSHeaders(c: Context, origin: string, methods: string[] = ['GET', 'POST', 'PUT', 'DELETE']) {
    c.header('Access-Control-Allow-Origin', origin);
    c.header('Access-Control-Allow-Methods', methods.join(', '));
    c.header('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-CSRF-Token, X-API-Key');
    c.header('Access-Control-Max-Age', '86400');
    c.header('Access-Control-Allow-Credentials', 'true');
  }
}

export default APIUtils;

import { drizzle } from 'drizzle-orm/postgres-js';
import postgres from 'postgres';
import * as schema from '../db/drizzle-schema';
import { logger } from './production-logger';

/**
 * Database utility functions and connection management
 */

export class DatabaseUtils {
  private static connection: postgres.Sql | null = null;
  private static db: ReturnType<typeof drizzle> | null = null;

  /**
   * Initialize database connection
   */
  static initialize(connectionString?: string) {
    if (this.connection) {
      return this.db;
    }

    const url = connectionString || process.env.DATABASE_URL;
    if (!url) {
      throw new Error('DATABASE_URL is required');
    }

    // Create connection with production-ready settings
    this.connection = postgres(url, {
      max: 20, // Maximum number of connections
      idle_timeout: 20, // Close idle connections after 20 seconds
      connect_timeout: 10, // Connection timeout
      prepare: false, // Disable prepared statements for better performance
    });

    this.db = drizzle(this.connection, { schema });
    return this.db;
  }

  /**
   * Get database instance
   */
  static getDatabase() {
    if (!this.db) {
      return this.initialize();
    }
    return this.db;
  }

  /**
   * Close database connection
   */
  static async close() {
    if (this.connection) {
      await this.connection.end();
      this.connection = null;
      this.db = null;
    }
  }

  /**
   * Execute transaction with retry logic
   */
  static async withTransaction<T>(
    callback: (tx: ReturnType<typeof drizzle>) => Promise<T>,
    maxRetries: number = 3
  ): Promise<T> {
    const db = this.getDatabase();
    let lastError: Error;

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        return await db.transaction(callback);
      } catch (error) {
        lastError = error as Error;

        // Don't retry on certain errors
        if (error instanceof Error && (
          error.message.includes('unique constraint') ||
          error.message.includes('foreign key constraint') ||
          error.message.includes('check constraint')
        )) {
          throw error;
        }

        // Wait before retry (exponential backoff)
        if (attempt < maxRetries) {
          await this.delay(Math.pow(2, attempt) * 100);
        }
      }
    }

    throw lastError!;
  }

  /**
   * Bulk insert with batch size control
   */
  static async bulkInsert<T>(
    table: any,
    data: T[],
    batchSize: number = 1000
  ) {
    const db = this.getDatabase();
    const results = [];

    for (let i = 0; i < data.length; i += batchSize) {
      const batch = data.slice(i, i + batchSize);
      const result = await db.insert(table).values(batch).returning();
      results.push(...result);
    }

    return results;
  }

  /**
   * Soft delete helper
   */
  static async softDelete(
    table: any,
    where: any,
    deletedBy?: string
  ) {
    const db = this.getDatabase();
    return db.update(table).set({
      deletedAt: new Date(),
      deletedBy,
      updatedAt: new Date(),
    } as any).where(where);
  }

  /**
   * Restore soft deleted record
   */
  static async restore(table: any, where: any) {
    const db = this.getDatabase();
    return db.update(table).set({
      deletedAt: null,
      deletedBy: null,
      updatedAt: new Date(),
    } as any).where(where);
  }

  /**
   * Get records with soft delete filter
   */
  static getWithoutDeleted(table: any) {
    const db = this.getDatabase();
    return db.select().from(table).where(
      (table as any).deletedAt === null
    );
  }

  /**
   * Pagination helper
   */
  static async paginate<T>(
    query: any,
    page: number = 1,
    limit: number = 50
  ): Promise<{
    data: T[];
    pagination: {
      page: number;
      limit: number;
      total: number;
      totalPages: number;
      hasNext: boolean;
      hasPrev: boolean;
    };
  }> {
    const offset = (page - 1) * limit;

    // Get total count
    const countQuery = query.$dynamic();
    const [{ count }] = await countQuery.limit(1);

    // Get data
    const data = await query.limit(limit).offset(offset);

    const total = Number(count);
    const totalPages = Math.ceil(total / limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
        hasNext: page < totalPages,
        hasPrev: page > 1,
      },
    };
  }

  /**
   * Search helper with text search
   */
  static async search(
    table: any,
    searchColumns: string[],
    searchTerm: string,
    options: {
      limit?: number;
      offset?: number;
      orderBy?: string;
      orderDirection?: 'asc' | 'desc';
    } = {}
  ) {
    const db = this.getDatabase();
    const { limit = 50, offset = 0, orderBy, orderDirection = 'desc' } = options;

    let query = db.select().from(table);

    // Add search conditions
    if (searchTerm && searchColumns.length > 0) {
      const searchConditions = searchColumns.map(column => 
        (table as any)[column].toLowerCase().like(`%${searchTerm.toLowerCase()}%`)
      );

      // Use OR condition for search
      query = query.where(
        // This would need to be adapted based on your ORM syntax
        // For Drizzle, you'd use or() function
      );
    }

    // Add ordering
    if (orderBy) {
      const column = (table as any)[orderBy];
      query = query.orderBy(
        orderDirection === 'asc' ? column.asc() : column.desc()
      );
    }

    return query.limit(limit).offset(offset);
  }

  /**
   * Health check for database
   */
  static async healthCheck(): Promise<{
    status: 'healthy' | 'degraded' | 'unhealthy';
    latency?: number;
    error?: string;
  }> {
    try {
      const start = Date.now();
      await this.getDatabase().execute('SELECT 1');
      const latency = Date.now() - start;

      return {
        status: latency < 1000 ? 'healthy' : 'degraded',
        latency,
      };
    } catch (error) {
      return {
        status: 'unhealthy',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  /**
   * Get database statistics
   */
  static async getStats(): Promise<{
    connectionCount: number;
    idleConnections: number;
    activeConnections: number;
  }> {
    // This would need to be adapted based on your database
    // For PostgreSQL, you could query pg_stat_activity
    const db = this.getDatabase();

    try {
      const result = await db.execute(`
        SELECT 
          count(*) as total_connections,
          count(*) FILTER (WHERE state = 'idle') as idle_connections,
          count(*) FILTER (WHERE state = 'active') as active_connections
        FROM pg_stat_activity 
        WHERE datname = current_database()
      `);

      return result[0] || {
        connectionCount: 0,
        idleConnections: 0,
        activeConnections: 0,
      };
    } catch (error) {
      return {
        connectionCount: 0,
        idleConnections: 0,
        activeConnections: 0,
      };
    }
  }

  /**
   * Backup helper (for development/testing)
   */
  static async createBackup(tableName: string): Promise<string> {
    // This is a simplified backup function
    // In production, you'd use proper backup tools
    const db = this.getDatabase();
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupName = `${tableName}_backup_${timestamp}`;

    await db.execute(`
      CREATE TABLE ${backupName} AS 
      SELECT * FROM ${tableName}
    `);

    return backupName;
  }

  /**
   * Utility delay function
   */
  private static delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Migration helper
   */
  static async runMigration(migrationSQL: string): Promise<void> {
    const db = this.getDatabase();
    await this.withTransaction(async (tx) => {
      await tx.execute(migrationSQL);
    });
  }

  /**
   * Cache invalidation helper
   */
  static async invalidateCache(pattern: string): Promise<void> {
    // This would integrate with your caching solution
    // For now, it's a placeholder
    logger.info(`Cache invalidated for pattern: ${pattern}`);
  }
}

