      // Process subscription created webhook
      const subscriptionRequest = {
        text: async () => JSON.stringify({
          id: 'evt_subscription_created',
          type: 'subscription.created',
          data: {
            object: {
              id: 'sub_test123',
              status: 'active',
              current_period_end: Math.floor(Date.now() / 1000) + 2592000,
