      expect(payments[0].failureReason).toBe('Your card was declined.');

      // Process retry payment
      const retryRequest = {
        text: async () => JSON.stringify({
          id: 'evt_payment_retry',
          type: 'payment_intent.succeeded',
          data: {
            object: {
              id: 'pi_retry123',
              amount: 2000,
              currency: 'usd',
