        email: 'consistency@example.com',
        status: 'active',
        stripeCustomerId: 'cus_consistency123',
        createdAt: new Date(),
        updatedAt: new Date()
      }).returning().then(rows => rows[0]);

      // Create invoice
      const invoice = await testDb.insert(invoices).values({
        id: 'inv_consistency123',
        organizationId: organization.id,
        number: 'INV-CONSISTENCY-001',
        amount: 3000,
        currency: 'usd',
        status: 'pending',
        dueDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
        createdAt: new Date(),
        updatedAt: new Date()
      }).returning().then(rows => rows[0]);

      // Process payment
      const paymentRequest = {
        text: async () => JSON.stringify({
          id: 'evt_consistency_payment',
          type: 'payment_intent.succeeded',
          data: {
            object: {
              id: 'pi_consistency123',
              amount: 3000,
              currency: 'usd',
              status: 'succeeded',
              metadata: {
                organizationId: organization.id,
                invoiceId: invoice.id
              },
            },
          },
        }),
        headers: {
          get: jest.fn((name) => {
            if (name === 'stripe-signature') {
              return 't=1234567890,v1=test_signature';
            }
            return null;
          }),
