            }
            return null;
          }),
        },
      };

      const result = await paymentWebhookService.processWebhook(failureRequest);
      expect(result.success).toBe(false);
      expect(result.message).toContain('Processing failed');

      // Restore original database
      Object.assign(testDb, originalDb);
    });

    it('should handle webhook replay scenarios', async () => {
      const organization = await testDb.insert(organizations).values({
        id: 'test-org-replay',
        name: 'Replay Test Org',
        email: 'replay@example.com',
        status: 'active',
        stripeCustomerId: 'cus_replay123',
        createdAt: new Date(),
        updatedAt: new Date()
      }).returning().then(rows => rows[0]);

      const replayRequest = {
        text: async () => JSON.stringify({
          id: 'evt_replay_test',
          type: 'payment_intent.succeeded',
          data: {
            object: {
              id: 'pi_replay123',
              amount: 1500,
              currency: 'usd',
              status: 'succeeded',
              metadata: {
                organizationId: organization.id,
              },
            },
          },
        }),
        headers: {
          get: jest.fn((name) => {
            if (name === 'stripe-signature') {
              return 't=1234567890,v1=test_signature';
            }
            return null;
          }),
        },
      };

      // Process webhook twice
      const result1 = await paymentWebhookService.processWebhook(replayRequest);
      const result2 = await paymentWebhookService.processWebhook(replayRequest);

      expect(result1.success).toBe(true);
      expect(result2.success).toBe(true);

      // Should only create one payment record (idempotency)
      const payments = await testDb.select().from(payments)
        .where(eq(payments.organizationId, organization.id));
      expect(payments).toHaveLength(1);
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, jest } from '@jest/globals';
import request from 'supertest';
import { app } from '../../backend/server';
import { db } from '../../backend/db/connection';

describe('Payment End-to-End Workflow', () => {
  let organizationId: string;
  let userId: string;
  let authToken: string;
  let customerId: string;
  let subscriptionId: string;

  beforeEach(async () => {
    // Create test organization and user
    const orgResult = await db.insert({
      into: 'organizations',
      values: {
        name: 'Payment Test Organization',
        domain: 'payment-test.com',
        plan: 'pro',
        settings: {},
        created_at: new Date(),
        updated_at: new Date(),
      },
      returning: ['id'],
    });

    organizationId = orgResult[0].id;

    const userResult = await db.insert({
      into: 'users',
      values: {
        organization_id: organizationId,
        email: 'payment@example.com',
        name: 'Payment Test User',
        role: 'admin',
        is_active: true,
        created_at: new Date(),
        updated_at: new Date(),
      },
      returning: ['id'],
    });

    userId = userResult[0].id;

    // Get auth token
    const loginResponse = await request(app)
      .post('/api/auth/login')
      .send({
        email: 'payment@example.com',
        password: 'testpassword',
      });

    authToken = loginResponse.body.token;
  });

  afterEach(async () => {
    // Clean up test data
    await db.delete().from('invoices').where('customer_id', '=', customerId);
    await db.delete().from('subscriptions').where('customer_id', '=', customerId);
    await db.delete().from('payments').where('organization_id', '=', organizationId);
    await db.delete().from('customers').where('organization_id', '=', organizationId);
    await db.delete().from('users').where('id', '=', userId);
    await db.delete().from('organizations').where('id', '=', organizationId);
  });

  describe('Complete Payment Workflow', () => {
    it('should handle one-time payment from creation to completion', async () => {
      // Step 1: Create customer
      const customerData = {
        email: 'customer@example.com',
        name: 'John Doe',
        phone: '+1234567890',
        address: {
          line1: '123 Main St',
          city: 'New York',
          state: 'NY',
          postal_code: '10001',
          country: 'US',
        },
        metadata: { source: 'website' },
      };

      const customerResponse = await request(app)
        .post('/api/customers')
        .set('Authorization', `Bearer ${authToken}`)
        .send(customerData)
        .expect(201);

      customerId = customerResponse.body.id;
      expect(customerResponse.body).toMatchObject({
        email: 'customer@example.com',
        name: 'John Doe',
        phone: '+1234567890',
        address: expect.objectContaining({
          city: 'New York',
          country: 'US',
        }),
      });

      // Step 2: Create payment intent
      const paymentData = {
        customer_id: customerId,
        amount: 5000, // $50.00
        currency: 'usd',
        description: 'Test Product Purchase',
        metadata: { order_id: 'order-123', product_id: 'prod-456' },
      };

      const paymentResponse = await request(app)
        .post('/api/payments/intent')
        .set('Authorization', `Bearer ${authToken}`)
        .send(paymentData)
        .expect(201);

      const paymentIntentId = paymentResponse.body.id;
      expect(paymentResponse.body).toMatchObject({
        amount: 5000,
        currency: 'usd',
        status: 'requires_payment_method',
        description: 'Test Product Purchase',
        client_secret: expect.any(String),
      });

      // Step 3: Confirm payment with payment method
      const confirmData = {
        payment_method_id: 'pm_card_visa',
        save_payment_method: true,
      };

      const confirmResponse = await request(app)
        .post(`/api/payments/intent/${paymentIntentId}/confirm`)
        .set('Authorization', `Bearer ${authToken}`)
        .send(confirmData)
        .expect(200);

      expect(confirmResponse.body).toMatchObject({
        id: paymentIntentId,
        status: 'succeeded',
        amount: 5000,
        charges: expect.any(Array),
      });

      // Step 4: Create invoice for the payment
      const invoiceData = {
        customer_id: customerId,
        description: 'Invoice for Test Product',
        line_items: [
          {
            description: 'Test Product',
            quantity: 1,
            unit_amount: 5000,
            currency: 'usd',
          },
        ],
        due_date: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        metadata: { invoice_number: 'INV-001' },
      };

      const invoiceResponse = await request(app)
        .post('/api/invoices')
        .set('Authorization', `Bearer ${authToken}`)
        .send(invoiceData)
        .expect(201);

