    it('should sync Stripe customers', async () => {
      const mockSync = jest.spyOn(platformDataSyncService, 'syncPlatform')
        .mockResolvedValue({
          success: true,
          messageCount: 15,
          recordsProcessed: 20,
          errors: [],
          lastSyncAt: new Date()
