import { PostgreSqlContainer } from '@testcontainers/postgresql';
import { RedisContainer } from '@testcontainers/redis';
import { setupTestDatabase, cleanupTestDatabase } from '../setup/integration.setup';

describe('Platform Integration Tests', () => {
  let postgresContainer: PostgreSqlContainer;
  let redisContainer: RedisContainer;
  let dbConnection: any;
  let redisClient: any;

  beforeAll(async () => {
    postgresContainer = await new PostgreSqlContainer()
      .withDatabase('test_platform_integration')
      .withUsername('test')
      .withPassword('test')
      .start();

    redisContainer = await new RedisContainer()
      .start();

    dbConnection = await setupTestDatabase(postgresContainer.getConnectionUri());
    redisClient = await redisContainer.getConnection();
  }, 60000);

  afterAll(async () => {
    await cleanupTestDatabase(dbConnection);
    await postgresContainer.stop();
    await redisContainer.stop();
  });

  beforeEach(async () => {
    await dbConnection.query('TRUNCATE TABLE platform_syncs, sync_logs, leads, contacts CASCADE');
    await redisClient.flushdb();
  });

  describe('Salesforce Integration', () => {
    it('should authenticate with Salesforce successfully', async () => {
      const salesforceConfig = {
        platform: 'salesforce',
        organizationId: 'test-org-id',
        config: {
          apiKey: 'test-salesforce-api-key',
          baseUrl: 'https://test.salesforce.com',
          mapping: {
            leadStatus: {
              'New': 'new',
              'Working': 'contacted',
              'Qualified': 'qualified'
            },
            contactFields: {
              'FirstName': 'firstName',
              'LastName': 'lastName',
              'Email': 'email'
            }
          }
        }
      };

      const response = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(salesforceConfig)
      });

      expect(response.status).toBe(201);
      const syncConfig = await response.json();
      expect(syncConfig.platform).toBe('salesforce');
      expect(syncConfig.isActive).toBe(true);
    });

    it('should sync leads from Salesforce', async () => {
      // Create sync configuration
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'salesforce',
          organizationId: 'test-org-id',
          syncType: 'import_only',
          config: {
            apiKey: 'test-key',
            baseUrl: 'https://test.salesforce.com'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Mock Salesforce API response
      const mockSalesforceLeads = [
        {
          Id: '001SF000001',
          FirstName: 'John',
          LastName: 'Doe',
          Email: 'john.doe@example.com',
          Company: 'Test Corp',
          Status: 'New'
        },
        {
          Id: '001SF000002',
          FirstName: 'Jane',
          LastName: 'Smith',
          Email: 'jane.smith@example.com',
          Company: 'Another Corp',
          Status: 'Working'
        }
      ];

      // Trigger sync
      const syncExecutionResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'import_leads',
          data: mockSalesforceLeads
        })
      });

      expect(syncExecutionResponse.status).toBe(200);
      const syncResult = await syncExecutionResponse.json();

      expect(syncResult.recordsProcessed).toBe(2);
      expect(syncResult.successfulSyncs).toBe(2);
      expect(syncResult.failedSyncs).toBe(0);
    });

    it('should handle Salesforce API errors gracefully', async () => {
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'salesforce',
          organizationId: 'test-org-id',
          config: {
            apiKey: 'invalid-key',
            baseUrl: 'https://test.salesforce.com'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Try to sync with invalid credentials
      const syncExecutionResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'import_leads'
        })
      });

      expect(syncExecutionResponse.status).toBe(400);
      const errorResult = await syncExecutionResponse.json();
      expect(errorResult.error).toContain('authentication');
    });
  });

  describe('HubSpot Integration', () => {
    it('should authenticate with HubSpot successfully', async () => {
      const hubspotConfig = {
        platform: 'hubspot',
        organizationId: 'test-org-id',
        config: {
          apiKey: 'test-hubspot-api-key',
          baseUrl: 'https://api.hubapi.com',
          mapping: {
            leadStatus: {
              'NEW': 'new',
              'CONTACTED': 'contacted',
              'QUALIFIED': 'qualified'
            }
          }
        }
      };

      const response = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(hubspotConfig)
      });

      expect(response.status).toBe(201);
      const syncConfig = await response.json();
      expect(syncConfig.platform).toBe('hubspot');
    });

    it('should sync contacts to HubSpot', async () => {
      // Create sync configuration
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'hubspot',
          organizationId: 'test-org-id',
          syncType: 'export_only',
          config: {
            apiKey: 'test-hubspot-key',
            baseUrl: 'https://api.hubapi.com'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Create test contacts in local system
      const testContacts = [
        {
          id: 'contact-1',
          firstName: 'Alice',
          lastName: 'Johnson',
          email: 'alice.j@example.com',
          company: 'Tech Corp',
          status: 'qualified'
        },
        {
          id: 'contact-2',
          firstName: 'Bob',
          lastName: 'Wilson',
          email: 'bob.w@example.com',
          company: 'Startup Inc',
          status: 'new'
        }
      ];

      // Export to HubSpot
      const exportResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'export_contacts',
          data: testContacts
        })
      });

      expect(exportResponse.status).toBe(200);
      const exportResult = await exportResponse.json();

      expect(exportResult.recordsProcessed).toBe(2);
      expect(exportResult.successfulSyncs).toBe(2);
    });
  });

  describe('Bidirectional Sync', () => {
    it('should sync data in both directions', async () => {
      // Create bidirectional sync configuration
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'pipedrive',
          organizationId: 'test-org-id',
          syncType: 'bidirectional',
          config: {
            apiKey: 'test-pipedrive-key',
            baseUrl: 'https://test.pipedrive.com',
            mapping: {
              leadStatus: {
                'Open': 'new',
                'Won': 'converted',
                'Lost': 'lost'
              }
            }
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Import from Pipedrive
      const importData = [
        {
          id: 'deal-1',
          title: 'Test Deal 1',
          status: 'Open',
          value: 10000,
          person_name: 'John Doe',
          email: 'john@example.com'
        }
      ];

      const importResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'import_deals',
          data: importData
        })
      });

      expect(importResponse.status).toBe(200);

      // Export back to Pipedrive
      const exportData = [
        {
          id: 'local-lead-1',
          firstName: 'Jane',
          lastName: 'Smith',
          email: 'jane@example.com',
          status: 'qualified',
          value: 15000
        }
      ];

      const exportResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'export_leads',
          data: exportData
        })
      });

      expect(exportResponse.status).toBe(200);
      const exportResult = await exportResponse.json();
      expect(exportResult.recordsProcessed).toBe(1);
    });
  });

  describe('Sync Conflict Resolution', () => {
    it('should handle conflicting records', async () => {
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'zoho',
          organizationId: 'test-org-id',
          syncType: 'bidirectional',
          config: {
            apiKey: 'test-zoho-key',
            baseUrl: 'https://test.zoho.com',
            conflictResolution: 'latest_wins'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Simulate conflicting data
      const conflictingRecords = [
        {
          id: 'conflict-1',
          email: 'conflict@example.com',
          firstName: 'John', // Local version
          lastName: 'Doe',
          updatedAt: new Date('2024-01-01T10:00:00Z'),
          externalData: {
            firstName: 'Jonathan', // External version
            lastName: 'Doe',
            updatedAt: new Date('2024-01-01T09:00:00Z')
          }
        }
      ];

      const conflictResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'resolve_conflicts',
          data: conflictingRecords
        })
      });

      expect(conflictResponse.status).toBe(200);
      const result = await conflictResponse.json();

      expect(result.conflictsResolved).toBe(1);
      expect(result.resolutionStrategy).toBe('latest_wins');
    });
  });

  describe('Sync Performance and Scaling', () => {
    it('should handle large datasets efficiently', async () => {
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'salesforce',
          organizationId: 'test-org-id',
          config: {
            apiKey: 'test-key',
            baseUrl: 'https://test.salesforce.com',
            batchSize: 100
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Generate large dataset
      const largeDataset = Array.from({ length: 1000 }, (_, i) => ({
        id: `lead-${i}`,
        firstName: `User${i}`,
        lastName: `Test${i}`,
        email: `user${i}@example.com`,
        company: `Company ${i % 100}`,
        status: ['new', 'contacted', 'qualified'][i % 3]
      }));

      const startTime = Date.now();

      const syncResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'import_leads',
          data: largeDataset
        })
      });

      const endTime = Date.now();
      const duration = endTime - startTime;

      expect(syncResponse.status).toBe(200);
      const result = await syncResponse.json();

      expect(result.recordsProcessed).toBe(1000);
      expect(result.successfulSyncs).toBe(1000);
      expect(duration).toBeLessThan(30000); // Should complete within 30 seconds
    });
  });

  describe('Sync Monitoring and Logging', () => {
    it('should log sync activities', async () => {
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'hubspot',
          organizationId: 'test-org-id',
          config: {
            apiKey: 'test-key',
            baseUrl: 'https://api.hubapi.com'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Execute sync
      await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'import_contacts',
          data: [{ id: 'test-1', email: 'test@example.com' }]
        })
      });

      // Check sync logs
      const logsResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/logs`);
      const logs = await logsResponse.json();

      expect(logs.length).toBeGreaterThan(0);
      expect(logs[0]).toHaveProperty('timestamp');
      expect(logs[0]).toHaveProperty('action');
      expect(logs[0]).toHaveProperty('status');
    });

    it('should track sync metrics', async () => {
      const syncResponse = await fetch('http://localhost:3001/api/platform-sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          platform: 'salesforce',
          organizationId: 'test-org-id',
          config: {
            apiKey: 'test-key',
            baseUrl: 'https://test.salesforce.com'
          }
        })
      });

      const syncConfig = await syncResponse.json();

      // Execute multiple syncs
      for (let i = 0; i < 5; i++) {
        await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/execute`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            type: 'import_leads',
            data: [{ id: `test-${i}`, email: `test${i}@example.com` }]
          })
        });
      }

      // Check metrics
      const metricsResponse = await fetch(`http://localhost:3001/api/platform-sync/${syncConfig.id}/metrics`);
      const metrics = await metricsResponse.json();

      expect(metrics.totalSyncs).toBe(5);
      expect(metrics.successfulSyncs).toBe(5);
      expect(metrics.averageSyncTime).toBeGreaterThan(0);
      expect(metrics.lastSyncAt).toBeDefined();
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, jest } from '@jest/globals';
import { PlatformSyncEngine } from '../../backend/services/platform-sync-engine';
import { platformAuthService } from '../../backend/services/platform-auth-service';
import { platformDataSyncService } from '../../backend/services/platform-data-sync-service';

jest.mock('../../backend/services/platform-auth-service');
jest.mock('../../backend/services/platform-data-sync-service');
jest.mock('../../backend/db/connection');

describe('Platform Sync Integration Tests', () => {
  let syncEngine: PlatformSyncEngine;
  let mockDb: any;

  beforeEach(() => {
    jest.clearAllMocks();
    syncEngine = new PlatformSyncEngine();

    mockDb = {
      select: jest.fn(),
      insert: jest.fn(),
      update: jest.fn(),
      delete: jest.fn(),
    };

    require('../../backend/db/connection').pgDb = mockDb;
  });

  describe('Complete Platform Sync Workflow', () => {
    it('should complete full sync workflow for Salesforce', async () => {
      // Mock platform connection
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'salesforce-access-token',
        refreshToken: 'salesforce-refresh-token',
        platformId: 'salesforce-connection-123',
      });

      // Mock successful sync
      (platformDataSyncService.syncPlatform as jest.Mock).mockResolvedValue({
        success: true,
        recordsProcessed: 150,
        messageCount: 75,
        errors: [],
        lastSyncAt: new Date(),
      });

      // Mock job insertion
      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'sync-job-123' }]),
      });

      // Mock job status update
      mockDb.update.mockReturnValue({
        where: jest.fn().mockReturnValue({
          set: jest.fn().mockResolvedValue(undefined),
        }),
      });

      // Trigger sync
      const result = await syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'salesforce',
        jobType: 'manual_sync',
      });

      expect(result).toBeDefined();
      expect(platformAuthService.ensureValidCredentialsForOrg).toHaveBeenCalledWith('org-123', 'salesforce');
      expect(platformDataSyncService.syncPlatform).toHaveBeenCalled();
    });

    it('should handle sync failures and retry logic', async () => {
      // Mock credentials
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'hubspot-access-token',
        platformId: 'hubspot-connection-123',
      });

      // Mock sync failure
      (platformDataSyncService.syncPlatform as jest.Mock).mockResolvedValue({
        success: false,
        recordsProcessed: 0,
        messageCount: 0,
        errors: ['Rate limit exceeded', 'API timeout'],
        lastSyncAt: new Date(),
      });

      // Mock job operations
      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'failed-sync-job-123' }]),
      });

      mockDb.update.mockReturnValue({
        where: jest.fn().mockReturnValue({
          set: jest.fn().mockResolvedValue(undefined),
        }),
      });

      // Expect sync to fail
      await expect(syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'hubspot',
        jobType: 'manual_sync',
      })).rejects.toThrow('Sync failed: Rate limit exceeded, API timeout');
    });

    it('should handle multiple platform syncs concurrently', async () => {
      const platforms = ['salesforce', 'hubspot', 'slack'];

      // Mock credentials for all platforms
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'mock-access-token',
        platformId: 'mock-connection-123',
      });

      // Mock successful syncs
      (platformDataSyncService.syncPlatform as jest.Mock).mockResolvedValue({
        success: true,
        recordsProcessed: 100,
        messageCount: 50,
        errors: [],
        lastSyncAt: new Date(),
      });

      // Mock job insertion
      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'concurrent-sync-job-123' }]),
      });

      // Trigger concurrent syncs
      const syncPromises = platforms.map(platform =>
        syncEngine.triggerSync({
          organizationId: 'org-123',
          platform: platform as any,
          jobType: 'manual_sync',
        })
      );

      const results = await Promise.all(syncPromises);

      expect(results).toHaveLength(3);
      expect(platformDataSyncService.syncPlatform).toHaveBeenCalledTimes(3);
    });
  });

  describe('Platform Connection Management', () => {
    it('should handle expired credentials refresh', async () => {
      // Mock expired credentials
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock)
        .mockResolvedValueOnce({
          accessToken: 'expired-token',
          refreshToken: 'valid-refresh-token',
          expiresAt: new Date(Date.now() - 1000), // Expired
        })
        .mockResolvedValueOnce({
          accessToken: 'new-access-token',
          refreshToken: 'new-refresh-token',
          expiresAt: new Date(Date.now() + 3600000), // Valid for 1 hour
        });

      // Mock successful sync after refresh
      (platformDataSyncService.syncPlatform as jest.Mock).mockResolvedValue({
        success: true,
        recordsProcessed: 50,
        messageCount: 25,
        errors: [],
        lastSyncAt: new Date(),
      });

      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'refresh-sync-job-123' }]),
      });

      const result = await syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'microsoft_teams',
        jobType: 'manual_sync',
      });

      expect(result).toBeDefined();
      expect(platformAuthService.ensureValidCredentialsForOrg).toHaveBeenCalledTimes(2);
    });

    it('should handle platform connection not found', async () => {
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue(null);

      await expect(syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'stripe',
        jobType: 'manual_sync',
      })).rejects.toThrow('Invalid or expired credentials for stripe');
    });
  });

  describe('Sync Job Management', () => {
    it('should track sync job status throughout lifecycle', async () => {
      const jobId = 'status-tracking-job-123';

      // Mock job creation
      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: jobId }]),
      });

      // Mock credentials
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'tracking-token',
        platformId: 'tracking-connection-123',
      });

      // Mock sync with progress
      (platformDataSyncService.syncPlatform as jest.Mock).mockImplementation(async () => {
        // Simulate processing time
        await new Promise(resolve => setTimeout(resolve, 100));
        return {
          success: true,
          recordsProcessed: 200,
          messageCount: 100,
          errors: [],
          lastSyncAt: new Date(),
        };
      });

      // Mock status queries
      mockDb.select.mockReturnValue({
        where: jest.fn().mockReturnValue({
          limit: jest.fn().mockResolvedValue([
            { id: jobId, status: 'pending' },
            { id: jobId, status: 'in_progress' },
            { id: jobId, status: 'completed' },
          ]),
        }),
      });

      // Start sync
      const syncPromise = syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'calendly',
        jobType: 'manual_sync',
      });

      // Check status during sync
      const status1 = await syncEngine.getJobStatus(jobId);
      expect(status1?.status).toBeDefined();

      await syncPromise;

      // Check final status
      const finalStatus = await syncEngine.getJobStatus(jobId);
      expect(finalStatus?.status).toBe('completed');
    });

    it('should handle sync job cancellation', async () => {
      const jobId = 'cancellable-job-123';

      // Mock job creation
      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: jobId }]),
      });

      // Mock long-running sync
      (platformDataSyncService.syncPlatform as jest.Mock).mockImplementation(async () => {
        await new Promise(resolve => setTimeout(resolve, 5000)); // Long sync
        return {
          success: true,
          recordsProcessed: 1000,
          messageCount: 500,
          errors: [],
          lastSyncAt: new Date(),
        };
      });

      // Start sync
      const syncPromise = syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'zoom',
        jobType: 'scheduled_sync',
      });

      // Cancel after short delay
      setTimeout(async () => {
        await syncEngine.cancelJob(jobId);
      }, 100);

      // Expect cancellation to work
      await expect(syncPromise).rejects.toThrow('Job cancelled');
    });
  });

  describe('Error Recovery and Retry Logic', () => {
    it('should implement exponential backoff for failed syncs', async () => {
      let attemptCount = 0;

      // Mock credentials
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'retry-token',
        platformId: 'retry-connection-123',
      });

      // Mock initial failures, then success
      (platformDataSyncService.syncPlatform as jest.Mock).mockImplementation(async () => {
        attemptCount++;
        if (attemptCount < 3) {
          throw new Error('Temporary API failure');
        }
        return {
          success: true,
          recordsProcessed: 100,
          messageCount: 50,
          errors: [],
          lastSyncAt: new Date(),
        };
      });

      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'retry-job-123' }]),
      });

      const startTime = Date.now();
      const result = await syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'google_workspace',
        jobType: 'manual_sync',
      });
      const endTime = Date.now();

      expect(result).toBeDefined();
      expect(attemptCount).toBe(3);
      expect(endTime - startTime).toBeGreaterThan(1000); // Should have delays between retries
    });

    it('should handle platform-specific error responses', async () => {
      (platformAuthService.ensureValidCredentialsForOrg as jest.Mock).mockResolvedValue({
        accessToken: 'error-test-token',
        platformId: 'error-connection-123',
      });

      // Mock platform-specific error
      (platformDataSyncService.syncPlatform as jest.Mock).mockResolvedValue({
        success: false,
        recordsProcessed: 0,
        messageCount: 0,
        errors: [
          'Salesforce: INVALID_SESSION_ID: Invalid session ID',
          'Salesforce: LIMIT_EXCEEDED: Concurrent limit exceeded'
        ],
        lastSyncAt: new Date(),
      });

      mockDb.insert.mockReturnValue({
        values: jest.fn().mockResolvedValue([{ id: 'error-job-123' }]),
      });

      await expect(syncEngine.triggerSync({
        organizationId: 'org-123',
        platform: 'salesforce',
        jobType: 'manual_sync',
      })).rejects.toThrow('Salesforce: INVALID_SESSION_ID: Invalid session ID, Salesforce: LIMIT_EXCEEDED: Concurrent limit exceeded');
    });
  });
});

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { setupTestApp, cleanupTestApp } from '../setup/test-setup';
import { createTestUser, createTestOrganization } from '../setup/test-helpers';

describe('Privacy Features Integration Tests', () => {
  let testOrg: any;
  let testUser: any;
  let authToken: string;

  beforeAll(async () => {
    await setupTestApp();
    testOrg = await createTestOrganization();
    testUser = await createTestUser({ organizationId: testOrg.id, role: 'user' });
    authToken = `Bearer ${testUser.sessionToken}`;
  });

  afterAll(async () => {
    await cleanupTestApp();
  });

  describe('Consent Management', () => {
    it('should create consent records', async () => {
      const consentData = {
        consentType: 'marketing_emails',
        granted: true,
        version: '1.0.0'
      };

      const response = await fetch('http://localhost:3000/api/trpc/privacy.updateConsent', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(consentData)
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data).toMatchObject({
        consentType: consentData.consentType,
        granted: consentData.granted,
        version: consentData.version
      });
    });

    it('should retrieve consent records', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.getConsents', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({})
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(Array.isArray(result.result.data.consents)).toBe(true);
    });

    it('should filter consents by type', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.getConsents', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ consentType: 'marketing_emails' })
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data.consents.every((c: any) => c.consentType === 'marketing_emails')).toBe(true);
    });
  });

  describe('Privacy Settings', () => {
    it('should get privacy settings', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.getSettings', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({})
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data).toHaveProperty('settings');
      expect(result.result.data.success).toBe(true);
    });

    it('should update privacy settings', async () => {
      const settingsData = {
        dataRetention: {
          enabled: true,
          periodDays: 365
        },
        communications: {
          email: true,
          sms: false
        }
      };

      const response = await fetch('http://localhost:3000/api/trpc/privacy.updateSettings', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(settingsData)
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data.success).toBe(true);
    });
  });

  describe('Data Export', () => {
    it('should export user data', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.exportData', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({})
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data).toHaveProperty('exportId');
      expect(result.result.data).toHaveProperty('status');
    });
  });

  describe('Breach Check', () => {
    it('should check for data breaches', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.breachCheck', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({})
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data).toHaveProperty('success');
      expect(result.result.data).toHaveProperty('breachesFound');
      expect(result.result.data).toHaveProperty('breaches');
      expect(Array.isArray(result.result.data.breaches)).toBe(true);
    });

    it('should check breaches for specific email', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.breachCheck', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ email: 'test@example.com' })
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(result.result.data.success).toBe(true);
    });
  });

  describe('Access Logs', () => {
    it('should retrieve access logs', async () => {
      const response = await fetch('http://localhost:3000/api/trpc/privacy.accessLogs', {
        method: 'POST',
        headers: {
          'Authorization': authToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          startDate: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
          endDate: new Date().toISOString()
        })
      });

      expect(response.ok).toBe(true);
      const result = await response.json();
      expect(Array.isArray(result.result.data.logs)).toBe(true);
    });
  });
});

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { app } from '../../backend/hono';
import { createSession, revokeSession, hashPassword } from '../../backend/lib/auth';
import { db as pgDb } from '../../backend/db/connection';
import { users, organizations } from '../../backend/db/drizzle-schema';
import { eq } from 'drizzle-orm';
import { Role, Permission } from '../../backend/lib/rbac';

describe('RBAC Integration Tests', () => {
  let orgId: string;
  let superAdminId: string;
  let enterpriseAdminId: string;
  let adminId: string;
  let userId: string;
  let superAdminToken: string;
  let enterpriseAdminToken: string;
  let adminToken: string;
  let userToken: string;

  beforeAll(async () => {
    // Create test organization
    const [org] = await pgDb
      .insert(organizations)
      .values({
        name: 'RBAC Test Org',
        slug: 'rbac-test-org',
        status: 'active',
      } as any)
      .returning();
    orgId = org!.id;

    // Create users with different roles
    const createUser = async (role: Role, email: string) => {
      const passwordHash = await hashPassword('TestPass123!');
      const [user] = await pgDb
        .insert(users)
        .values({
          email,
          passwordHash,
          firstName: role.charAt(0).toUpperCase() + role.slice(1),
          lastName: 'User',
          emailVerified: true,
          role,
          status: 'active',
          organizationId: role !== 'super_admin' ? orgId : null,
        } as any)
        .returning();
      return user!.id;
    };

    superAdminId = await createUser('super_admin', 'super@test.com');
    enterpriseAdminId = await createUser('enterprise_admin', 'enterprise@test.com');
    adminId = await createUser('admin', 'admin@test.com');
    userId = await createUser('user', 'user@test.com');

    // Create sessions
    superAdminToken = (await createSession(superAdminId, '127.0.0.1', 'test-agent')).token;
    enterpriseAdminToken = (await createSession(enterpriseAdminId, '127.0.0.1', 'test-agent')).token;
    adminToken = (await createSession(adminId, '127.0.0.1', 'test-agent')).token;
    userToken = (await createSession(userId, '127.0.0.1', 'test-agent')).token;
  });

  afterAll(async () => {
    // Cleanup
    await pgDb.delete(users).where(eq(users.organizationId, orgId));
    await pgDb.delete(users).where(eq(users.id, superAdminId));
    await pgDb.delete(organizations).where(eq(organizations.id, orgId));
  });

  const makeRequest = async (token: string, path: string, method = 'GET') => {
    return app.request(path, {
      method,
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
    });
  };

  describe('Super Admin Access', () => {
    it('should access any resource regardless of tenant', async () => {
      const res = await makeRequest(superAdminToken, '/api/trpc/enterprise.backup.list');
      expect(res.status).toBe(200);
    });

    it('should trigger backups without org context', async () => {
      const res = await app.request('/api/trpc/enterprise.backup.trigger', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${superAdminToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ database: 'test', type: 'full' }),
      });
      expect(res.status).toBe(200);
    });
  });

  describe('Enterprise Admin Access', () => {
    it('should access enterprise resources within their org', async () => {
      const res = await makeRequest(enterpriseAdminToken, '/api/trpc/enterprise.backup.list');
      expect(res.status).toBe(200);
    });

    it('should trigger backups for their org', async () => {
      const res = await app.request('/api/trpc/enterprise.backup.trigger', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${enterpriseAdminToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ database: 'test', type: 'full' }),
      });
      expect(res.status).toBe(200);
    });
  });

  describe('Admin Access', () => {
    it('should access limited enterprise resources', async () => {
      const res = await makeRequest(adminToken, '/api/trpc/enterprise.backup.list');
      expect(res.status).toBe(200);
    });

    it('should be denied from triggering backups (requires BACKUP_TRIGGER)', async () => {
      const res = await app.request('/api/trpc/enterprise.backup.trigger', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${adminToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ database: 'test', type: 'full' }),
      });
      expect(res.status).toBe(403);
    });
  });

  describe('User Access', () => {
    it('should be denied from backup list', async () => {
      const res = await makeRequest(userToken, '/api/trpc/enterprise.backup.list');
      expect(res.status).toBe(403);
    });

    it('should be denied from triggering backups', async () => {
      const res = await app.request('/api/trpc/enterprise.backup.trigger', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${userToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ database: 'test', type: 'full' }),
      });
      expect(res.status).toBe(403);
    });
  });

  describe('Default-protected /api/* layer', () => {
    it('should allow /api/trpc (allowlist)', async () => {
      const res = await makeRequest(userToken, '/api/trpc/auth.me');
      expect(res.status).toBe(200);
    });

    it('should reject unauthenticated requests to protected /api/*', async () => {
      const res = await app.request('/api/trpc/enterprise.backup.list');
      expect(res.status).toBe(401);
    });
  });
});

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { app } from '../../backend/hono';
import { hashAccessToken, createSession, revokeSession, hashPassword, validateSession } from '../../backend/lib/auth';
import { db as pgDb } from '../../backend/db/connection';
import { users, sessions } from '../../backend/db/drizzle-schema';
import { eq } from 'drizzle-orm';

describe('Session Token Migration Tests', () => {
  let userId: string;
  let plainSessionId: string;
  let hashedSessionId: string;
  let plainToken: string;
  let hashedToken: string;

  beforeAll(async () => {
    // Create test user
    const passwordHash = await hashPassword('TestPass123!');
    const [user] = await pgDb
      .insert(users)
      .values({
        email: 'migration-test@example.com',
        passwordHash,
        firstName: 'Migration',
        lastName: 'Test',
        emailVerified: true,
        role: 'user',
        status: 'active',
      } as any)
      .returning();
    userId = user!.id;

    // Manually insert a legacy plaintext session
    plainToken = `legacy-plain-${crypto.randomUUID()}`;
    const [plainSession] = await pgDb
      .insert(sessions)
      .values({
        id: crypto.randomUUID(),
        userId,
        token: plainToken, // plaintext
        refreshToken: `refresh-${crypto.randomUUID()}`,
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
        lastActivityAt: new Date(),
        ipAddress: '127.0.0.1',
        userAgent: 'test-agent',
      } as any)
      .returning();
    plainSessionId = plainSession!.id;

    // Insert a hashed session for comparison
    hashedToken = hashAccessToken(`hashed-${crypto.randomUUID()}`);
    const [hashedSession] = await pgDb
      .insert(sessions)
      .values({
        id: crypto.randomUUID(),
        userId,
        token: hashedToken, // already hashed
        refreshToken: `refresh-${crypto.randomUUID()}`,
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
        lastActivityAt: new Date(),
        ipAddress: '127.0.0.1',
        userAgent: 'test-agent',
      } as any)
      .returning();
    hashedSessionId = hashedSession!.id;
  });

  afterAll(async () => {
    // Cleanup
    await pgDb.delete(sessions).where(eq(sessions.userId, userId));
    await pgDb.delete(users).where(eq(users.id, userId));
  });

  it('should migrate plaintext token to hashed on validation', async () => {
    // Before migration: plaintext token exists
    const before = await pgDb
      .select()
      .from(sessions)
      .where(eq(sessions.id, plainSessionId))
      .limit(1);
    expect(before[0]?.token).toBe(plainToken); // still plaintext

    // Validate session (should trigger migration)
    const { valid, session } = await validateSession(plainToken);
    expect(valid).toBe(true);
    expect(session?.id).toBe(plainSessionId);

    // After migration: token should be hashed
    const after = await pgDb
      .select()
      .from(sessions)
      .where(eq(sessions.id, plainSessionId))
      .limit(1);
    expect(after[0]?.token).not.toBe(plainToken); // no longer plaintext
    expect(after[0]?.token).toMatch(/^[a-f0-9]{64}$/); // looks like SHA-256 hex
  });

  it('should validate already-hashed token without migration', async () => {
    const { valid, session } = await validateSession(hashedToken);
    expect(valid).toBe(true);
    expect(session?.id).toBe(hashedSessionId);
  });

  it('should reject invalid tokens', async () => {
    const { valid } = await validateSession('invalid-token');
    expect(valid).toBe(false);
  });

  it('should allow Hono access with migrated token', async () => {
    // Use the original plaintext token (it should be migrated internally)
    const res = await app.request('/api/trpc/auth.me', {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${plainToken}`,
        'Content-Type': 'application/json',
      },
    });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.result.data.id).toBe(userId);
  });
});

import { describe, it, expect, beforeAll, afterAll } from '@jest/globals';
import { Hono } from 'hono';
import { ssoService } from '../../backend/services/sso-service';
import { db as pgDb } from '../../backend/db/connection';
import { organizations, users } from '../../backend/db/drizzle-schema';
import { eq } from 'drizzle-orm';

describe('SSO Service Tests', () => {
  let testOrg: any;

  beforeAll(async () => {
    // Create test organization with SSO config
    const [org] = await pgDb.insert(organizations).values({
      name: 'SSO Test Org',
      slug: 'sso-test-org',
      ownerId: 'temp-owner',
      billingEmail: 'sso@example.com',
      plan: 'enterprise',
      status: 'active',
      maxUsers: 100,
      maxStorage: 10240,
      settings: {
        sso: {
          oidc: {
            issuer: 'https://login.microsoftonline.com/test-tenant/v2.0',
            clientId: 'test-client-id',
            clientSecret: 'test-client-secret',
            redirectUri: 'http://localhost:3000/auth/callback',
            scopes: ['openid', 'email', 'profile'],
          },
          saml: {
            idpMetadataXml: `<?xml version="1.0"?>
<EntityDescriptor xmlns="urn:oasis:names:tc:SAML:2.0:metadata" entityID="https://sts.windows.net/test-tenant/">
  <IDPSSODescriptor protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol">
    <SingleSignOnService Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect" Location="https://login.microsoftonline.com/test-tenant/saml2"/>
  </IDPSSODescriptor>
</EntityDescriptor>`,
            emailAttribute: 'email',
          },
        },
      },
      metadata: {},
    }).returning();
    testOrg = org;
  });

  afterAll(async () => {
    await pgDb.delete(organizations).where(eq(organizations.slug, 'sso-test-org'));
  });

  describe('SAML SSO', () => {
    it('should generate SP metadata', async () => {
      const baseUrl = 'https://app.example.com';
      const metadata = await ssoService.getSamlSpMetadata(testOrg.slug, baseUrl);

      expect(metadata).toContain('EntityDescriptor');
      expect(metadata).toContain('SPSSODescriptor');
      expect(metadata).toContain(baseUrl);
    });

    it('should build SAML auth URL', async () => {
      const baseUrl = 'https://app.example.com';
      const { url } = await ssoService.buildSamlAuthUrl(testOrg.slug, baseUrl);

      expect(url).toBeDefined();
      expect(typeof url).toBe('string');
    });

    it('should handle SAML callback with valid response', async () => {
      // Mock SAML response
      const mockSamlResponse = 'mock-saml-response';
      const baseUrl = 'https://app.example.com';

      try {
        const session = await ssoService.handleSamlCallback({
          orgSlug: testOrg.slug,
          baseUrl,
          samlResponse: mockSamlResponse,
        });

        expect(session).toBeDefined();
        expect(session.token).toBeDefined();
        expect(session.userId).toBeDefined();
      } catch (error) {
        // Expected to fail in test environment without real SAML
        expect(error).toBeDefined();
      }
    });

    it('should reject SAML callback for invalid org', async () => {
      const baseUrl = 'https://app.example.com';

      await expect(
        ssoService.handleSamlCallback({
          orgSlug: 'invalid-org',
          baseUrl,
          samlResponse: 'mock-response',
        })
      ).rejects.toThrow('Organization not found');
    });
  });

  describe('OIDC SSO', () => {
    it('should build OIDC auth URL', async () => {
      const { url, state } = await ssoService.buildOidcAuthUrl(testOrg.slug);

      expect(url).toBeDefined();
      expect(state).toBeDefined();
      expect(url).toContain('login.microsoftonline.com');
      expect(url).toContain('response_type=code');
    });

    it('should include required OIDC parameters', async () => {
      const { url, state } = await ssoService.buildOidcAuthUrl(testOrg.slug);

      expect(url).toContain('client_id=test-client-id');
      expect(url).toContain('state=' + state);
      expect(url).toContain('code_challenge_method=S256');
      expect(url).toContain('scope=');
    });

    it('should reject OIDC callback for invalid state', async () => {
      await expect(
        ssoService.handleOidcCallback({
          code: 'mock-code',
          state: 'invalid-state',
        })
      ).rejects.toThrow('Invalid or expired state');
    });

    it('should reject OIDC callback for invalid org', async () => {
      // Create a valid state first
      const { state } = await ssoService.buildOidcAuthUrl(testOrg.slug);

      // Delete the org to simulate invalid org
      await pgDb.delete(organizations).where(eq(organizations.slug, testOrg.slug));

      await expect(
        ssoService.handleOidcCallback({
          code: 'mock-code',
          state,
        })
      ).rejects.toThrow('Organization not found');
    });
  });

  describe('User Provisioning', () => {
    it('should create new user on first SSO login', async () => {
      const email = 'sso-new-user@example.com';

      // Ensure user doesn't exist
      await pgDb.delete(users).where(eq(users.email, email));

      try {
        const session = await (ssoService as any).provisionAndCreateSession({
          email,
          organizationId: testOrg.id,
          firstName: 'SSO',
          lastName: 'User',
        });

        expect(session).toBeDefined();
        expect(session.email).toBe(email);
        expect(session.userId).toBeDefined();

        // Verify user was created
        const [createdUser] = await pgDb
          .select()
          .from(users)
          .where(eq(users.email, email))
          .limit(1);

        expect(createdUser).toBeDefined();
        expect((createdUser as any).emailVerified).toBe(true);
        expect((createdUser as any).organizationId).toBe(testOrg.id);
      } catch (error) {
        // Expected to fail in test environment
        expect(error).toBeDefined();
      }
    });

    it('should update existing user on SSO login', async () => {
      const email = 'sso-existing-user@example.com';

      // Create existing user without org
      const [existingUser] = await pgDb.insert(users).values({
        email,
        passwordHash: 'mock-hash',
        firstName: 'Existing',
        lastName: 'User',
        emailVerified: true,
        role: 'user',
        status: 'active',
        failedLoginAttempts: 0,
        preferences: {},
        metadata: {},
      }).returning();

      try {
        const session = await (ssoService as any).provisionAndCreateSession({
          email,
          organizationId: testOrg.id,
          firstName: 'Updated',
          lastName: 'User',
        });

        expect(session).toBeDefined();

        // Verify user was updated with org
        const [updatedUser] = await pgDb
          .select()
          .from(users)
          .where(eq(users.email, email))
          .limit(1);

        expect((updatedUser as any).organizationId).toBe(testOrg.id);
      } catch (error) {
        // Expected to fail in test environment
        expect(error).toBeDefined();
      } finally {
        // Cleanup
        await pgDb.delete(users).where(eq(users.email, email));
      }
    });
  });

  describe('Configuration Validation', () => {
    it('should reject org without SSO config', async () => {
      const [noSsoOrg] = await pgDb.insert(organizations).values({
        name: 'No SSO Org',
        slug: 'no-sso-org',
        ownerId: 'temp-owner',
        billingEmail: 'nosso@example.com',
        plan: 'professional',
        status: 'active',
        maxUsers: 10,
        maxStorage: 1024,
        settings: {},
        metadata: {},
      }).returning();

      await expect(
        ssoService.getSamlSpMetadata(noSsoOrg.slug, 'https://example.com')
      ).rejects.toThrow('SAML not configured for organization');

      await expect(
        ssoService.buildOidcAuthUrl(noSsoOrg.slug)
      ).rejects.toThrow('OIDC not configured for organization');

      // Cleanup
      await pgDb.delete(organizations).where(eq(organizations.slug, 'no-sso-org'));
    });

    it('should handle malformed SAML metadata', async () => {
      const [malformedOrg] = await pgDb.insert(organizations).values({
        name: 'Malformed SAML Org',
        slug: 'malformed-saml-org',
        ownerId: 'temp-owner',
        billingEmail: 'malformed@example.com',
        plan: 'enterprise',
        status: 'active',
        maxUsers: 10,
        maxStorage: 1024,
        settings: {
          sso: {
            saml: {
              idpMetadataXml: 'invalid-xml',
            },
          },
        },
        metadata: {},
      }).returning();

      await expect(
        ssoService.getSamlSpMetadata(malformedOrg.slug, 'https://example.com')
      ).rejects.toThrow();

      // Cleanup
      await pgDb.delete(organizations).where(eq(organizations.slug, 'malformed-saml-org'));
    });
  });
});

describe('Enterprise API Endpoints', () => {
  let app: Hono;
  let authToken: string;

  beforeAll(async () => {
    app = new Hono();

    // Setup enterprise routes
    app.get('/api/enterprise/analytics', async (c) => {
      return c.json({ metrics: { users: 100, activeUsers: 75 } });
    });

    app.get('/api/enterprise/usage-metrics', async (c) => {
      return c.json({ 
        apiCalls: 10000, 
        storage: 5000, 
        bandwidth: 2000 
