            expect(org.billing.currency).toMatch(/^(usd|eur|gbp)$/);

            return true;
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should enforce plan-based feature limits', () => {
      fc.assert(
        fc.property(
          enterpriseGenerators.multiTenantOrg,
