// Property test utilities
export const propertyTestUtils = {
  // Test round-trip serialization
  testRoundTrip: <T>(
    generator: fc.Arbitrary<T>,
    serialize: (obj: T) => string,
    deserialize: (str: string) => T,
    options?: fc.Parameters<[T]>
  ) => {
    fc.assert(
      fc.property(generator, (obj) => {
        const serialized = serialize(obj);
        const deserialized = deserialize(serialized);
        return JSON.stringify(obj) === JSON.stringify(deserialized);
      }),
      options
    );
  },

  // Test idempotent operations
  testIdempotency: <T>(
    generator: fc.Arbitrary<T>,
    operation: (obj: T) => T,
    options?: fc.Parameters<[T]>
  ) => {
    fc.assert(
      fc.property(generator, (obj) => {
        const result1 = operation(obj);
        const result2 = operation(result1);
        return JSON.stringify(result1) === JSON.stringify(result2);
      }),
      options
    );
  },

  // Test commutative operations
  testCommutativity: <T>(
    generator: fc.Arbitrary<[T, T]>,
    operation: (a: T, b: T) => T,
    options?: fc.Parameters<[T, T]>
  ): void => {
    fc.assert(
      fc.property(generator, ([a, b]) => {
        const result1 = operation(a, b);
        const result2 = operation(b, a);
        return JSON.stringify(result1) === JSON.stringify(result2);
      }),
      options
    );
  }
};

import { describe, it, expect } from '@jest/globals';
import * as fc from 'fast-check';
import { z } from 'zod';

// Payment processing property-based tests
describe('Payment Processing Properties', () => {
  // Payment amount validation schema
  const paymentAmountSchema = z.number().positive().max(999999.99).multipleOf(0.01);

  describe('Amount Validation', () => {
    it('should validate payment amounts correctly', () => {
      fc.assert(
        fc.property(
          fc.float({ min: 0.01, max: 999999.99 }),
          (amount) => {
            const roundedAmount = Math.round(amount * 100) / 100;
            const result = paymentAmountSchema.safeParse(roundedAmount);

            if (roundedAmount > 0 && roundedAmount <= 999999.99) {
              expect(result.success).toBe(true);
            }

            return true;
          }
        ),
        { numRuns: 1000 }
      );
    });

    it('should reject invalid payment amounts', () => {
      fc.assert(
        fc.property(
          fc.oneof(
            fc.float({ max: 0 }), // Zero or negative
            fc.float({ min: 1000000 }), // Too large
            fc.constant(NaN), // NaN
            fc.constant(Infinity) // Infinity
          ),
          (invalidAmount) => {
            const result = paymentAmountSchema.safeParse(invalidAmount);
            expect(result.success).toBe(false);
            return true;
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('Currency Conversion', () => {
    const supportedCurrencies = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD'];

    it('should maintain precision during currency conversion', () => {
      fc.assert(
        fc.property(
          fc.float({ min: 0.01, max: 10000 }),
          fc.constantFrom(...supportedCurrencies),
          fc.constantFrom(...supportedCurrencies),
          (amount, fromCurrency, toCurrency) => {
            if (fromCurrency === toCurrency) return true;

            // Mock conversion rates (in real implementation, these would come from an API)
            const mockRates: Record<string, number> = {
              'USD-EUR': 0.85,
              'USD-GBP': 0.73,
              'USD-JPY': 110.0,
              'USD-CAD': 1.25,
              'USD-AUD': 1.35,
              'EUR-USD': 1.18,
              'EUR-GBP': 0.86,
              'EUR-JPY': 129.0,
              'EUR-CAD': 1.47,
              'EUR-AUD': 1.59,
              'GBP-USD': 1.37,
              'GBP-EUR': 1.16,
              'GBP-JPY': 151.0,
              'GBP-CAD': 1.71,
              'GBP-AUD': 1.85,
              'JPY-USD': 0.0091,
              'JPY-EUR': 0.0077,
              'JPY-GBP': 0.0066,
              'JPY-CAD': 0.011,
              'JPY-AUD': 0.012,
              'CAD-USD': 0.80,
              'CAD-EUR': 0.68,
              'CAD-GBP': 0.58,
              'CAD-JPY': 88.0,
              'CAD-AUD': 1.08,
              'AUD-USD': 0.74,
              'AUD-EUR': 0.63,
              'AUD-GBP': 0.54,
              'AUD-JPY': 81.0,
              'AUD-CAD': 0.93
            };

            const rateKey = `${fromCurrency}-${toCurrency}`;
            const rate = mockRates[rateKey];

            if (!rate) return true;

            const convertedAmount = Math.round(amount * rate * 100) / 100;

            // Verify conversion maintains reasonable precision
            expect(convertedAmount).toBeGreaterThan(0);
            expect(convertedAmount).toBeLessThan(999999.99);
            expect(Number.isFinite(convertedAmount)).toBe(true);

            return true;
          }
        ),
        { numRuns: 500 }
      );
    });
  });

  describe('Payment Method Validation', () => {
    const paymentMethodGenerators = {
      creditCard: fc.record({
        type: fc.constant('credit_card'),
        cardNumber: fc.string({ minLength: 13, maxLength: 19 }).map(s => 
          s.replace(/\D/g, '').slice(0, 16)
        ),
        expiryMonth: fc.integer({ min: 1, max: 12 }),
        expiryYear: fc.integer({ min: new Date().getFullYear(), max: new Date().getFullYear() + 10 }),
        cvv: fc.string({ minLength: 3, maxLength: 4 }).map(s => s.replace(/\D/g, '')),
        holderName: fc.string({ minLength: 2, maxLength: 50 })
      }),

      bankTransfer: fc.record({
        type: fc.constant('bank_transfer'),
        accountNumber: fc.string({ minLength: 8, maxLength: 17 }).map(s => s.replace(/\D/g, '')),
        routingNumber: fc.string({ minLength: 9, maxLength: 9 }).map(s => s.replace(/\D/g, '')),
        accountHolderName: fc.string({ minLength: 2, maxLength: 50 }),
        bankName: fc.string({ minLength: 2, maxLength: 50 })
      }),

      digitalWallet: fc.record({
        type: fc.constant('digital_wallet'),
        provider: fc.constantFrom('paypal', 'apple_pay', 'google_pay', 'stripe'),
        walletId: fc.uuid(),
        email: fc.emailAddress()
      })
    };

    it('should validate credit card Luhn algorithm', () => {
      fc.assert(
        fc.property(
          paymentMethodGenerators.creditCard,
          (paymentMethod) => {
            const { cardNumber } = paymentMethod;

            // Skip if card number doesn't have enough digits
            if (cardNumber.length < 13 || cardNumber.length > 19) return true;

            // Implement Luhn algorithm
            const digits = cardNumber.split('').map(Number);
            let sum = 0;
            let isEven = false;

            for (let i = digits.length - 1; i >= 0; i--) {
              let digit = digits[i];

              if (isEven) {
                digit *= 2;
                if (digit > 9) {
                  digit -= 9;
                }
              }

              sum += digit;
              isEven = !isEven;
            }

            const isValid = sum % 10 === 0;

            // For testing purposes, we'll accept both valid and invalid cards
            // In production, you'd want to enforce validity
            return true;
          }
        ),
        { numRuns: 200 }
      );
    });

    it('should validate expiry dates', () => {
      fc.assert(
        fc.property(
          paymentMethodGenerators.creditCard,
          (paymentMethod) => {
            const { expiryMonth, expiryYear } = paymentMethod;
            const now = new Date();
            const currentYear = now.getFullYear();
            const currentMonth = now.getMonth() + 1;

            // Check if expiry date is in the future
            const isValidExpiry = 
              expiryYear > currentYear || 
              (expiryYear === currentYear && expiryMonth >= currentMonth);

            // For testing, we accept both valid and expired dates
            // In production, you'd want to enforce validity
            expect(expiryMonth).toBeGreaterThanOrEqual(1);
            expect(expiryMonth).toBeLessThanOrEqual(12);
            expect(expiryYear).toBeGreaterThanOrEqual(currentYear);

            return true;
          }
        ),
        { numRuns: 100 }
      );
    });
  });

  describe('Transaction Processing', () => {
    const transactionGenerators = {
      transaction: fc.record({
        id: fc.uuid(),
        amount: fc.float({ min: 0.01, max: 999999.99 }),
        currency: fc.constantFrom('USD', 'EUR', 'GBP', 'JPY'),
        status: fc.constantFrom('pending', 'processing', 'completed', 'failed', 'refunded'),
        paymentMethod: fc.oneof(
          fc.constant('credit_card'),
          fc.constant('bank_transfer'),
          fc.constant('digital_wallet')
        ),
        createdAt: fc.date(),
        updatedAt: fc.date(),
        metadata: fc.record({
          ipAddress: fc.internetIp(),
          userAgent: fc.string(),
          deviceId: fc.uuid()
        })
      })
    };

    it('should maintain transaction state consistency', () => {
      fc.assert(
        fc.property(
          transactionGenerators.transaction,
          fc.constantFrom('pending', 'processing', 'completed', 'failed', 'refunded'),
          (transaction, newStatus) => {
            // Simulate state transition
            const updatedTransaction = {
              ...transaction,
              status: newStatus,
              updatedAt: new Date()
            };

            // Verify invariants
            expect(updatedTransaction.id).toBe(transaction.id);
            expect(updatedTransaction.amount).toBe(transaction.amount);
            expect(updatedTransaction.currency).toBe(transaction.currency);
            expect(updatedTransaction.paymentMethod).toBe(transaction.paymentMethod);
            expect(updatedTransaction.metadata).toEqual(transaction.metadata);

            // Verify timestamp updated
            expect(updatedTransaction.updatedAt.getTime()).toBeGreaterThanOrEqual(
              transaction.updatedAt.getTime()
            );

            return true;
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should prevent invalid state transitions', () => {
      fc.assert(
        fc.property(
          transactionGenerators.transaction,
          (transaction) => {
            const { status } = transaction;

            // Define valid transitions
            const validTransitions: Record<string, string[]> = {
              'pending': ['processing', 'failed'],
              'processing': ['completed', 'failed'],
              'completed': ['refunded'],
              'failed': [], // Failed transactions cannot transition
              'refunded': [] // Refunded transactions cannot transition
            };

            const allowedNextStates = validTransitions[status] || [];

            // Verify that the transition rules are logical
            expect(Array.isArray(allowedNextStates)).toBe(true);

            return true;
          }
        ),
        { numRuns: 50 }
      );
    });
  });

  describe('Refund Processing', () => {
    it('should validate refund amounts', () => {
      fc.assert(
        fc.property(
          fc.record({
            originalAmount: fc.float({ min: 0.01, max: 999999.99 }),
            refundAmount: fc.float({ min: 0.01, max: 999999.99 })
          }),
          ({ originalAmount, refundAmount }) => {
            // Refund amount should not exceed original amount
            const isValidRefund = refundAmount <= originalAmount;

            if (isValidRefund) {
              expect(refundAmount).toBeGreaterThan(0);
              expect(refundAmount).toBeLessThanOrEqual(originalAmount);
            }

            return true;
          }
        ),
        { numRuns: 200 }
      );
    });

    it('should handle partial refunds correctly', () => {
      fc.assert(
        fc.property(
          fc.record({
            originalAmount: fc.float({ min: 10, max: 1000 }),
            refundPercentage: fc.integer({ min: 1, max: 100 })
          }),
          ({ originalAmount, refundPercentage }) => {
            const refundAmount = Math.round((originalAmount * refundPercentage / 100) * 100) / 100;
            const remainingAmount = Math.round((originalAmount - refundAmount) * 100) / 100;

            // Verify calculations
            expect(refundAmount).toBeGreaterThanOrEqual(0);
            expect(refundAmount).toBeLessThanOrEqual(originalAmount);
            expect(remainingAmount).toBeGreaterThanOrEqual(0);
            expect(remainingAmount).toBeLessThanOrEqual(originalAmount);

            // Verify that refund + remaining equals original (within rounding precision)
            const total = Math.round((refundAmount + remainingAmount) * 100) / 100;
            expect(Math.abs(total - originalAmount)).toBeLessThan(0.01);

            return true;
          }
        ),
        { numRuns: 100 }
      );
    });
  });
});

import { describe, it, expect, beforeEach } from '@jest/globals';
import * as fc from 'fast-check';
import { RBACService } from '../../backend/lib/rbac';
import { generators, propertyTestUtils } from './generators';

describe('RBAC Property-Based Tests', () => {
  let rbacService: RBACService;

  beforeEach(() => {
    rbacService = new RBACService();
  });

  describe('Permission Verification Properties', () => {
    it('should maintain permission consistency across role hierarchy', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.constantFrom('admin', 'user', 'viewer'),
          fc.constantFrom('read', 'write', 'delete', 'admin'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, role, action, resource) => {
            // Set up user with role
            user.role = role;

            // Test permission verification
            const hasPermission = await rbacService.hasPermission(
              user,
              action,
              resource.resource,
              resource.resourceId
            );

            // Admin should have all permissions
            if (role === 'admin') {
              expect(hasPermission).toBe(true);
            }

            // Viewer should only have read permissions
            if (role === 'viewer' && action !== 'read') {
              expect(hasPermission).toBe(false);
            }

            // Permission should be deterministic
            const hasPermission2 = await rbacService.hasPermission(
              user,
              action,
              resource.resource,
              resource.resourceId
            );
            expect(hasPermission).toBe(hasPermission2);
          }
        ),
        { numRuns: 100 }
      );
    });

    it('should handle role inheritance correctly', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.array(fc.constantFrom('read', 'write', 'delete')),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, permissions, resource) => {
            // Grant permissions to user
            for (const permission of permissions) {
              await rbacService.grantPermission(user.id, permission, resource.resource, resource.resourceId);
            }

            // Check that granted permissions are recognized
            for (const permission of permissions) {
              const hasPermission = await rbacService.hasPermission(
                user,
                permission,
                resource.resource,
                resource.resourceId
              );
              expect(hasPermission).toBe(true);
            }

            // Check that non-granted permissions are not recognized
            const allPermissions = ['read', 'write', 'delete', 'admin'];
            const nonGrantedPermissions = allPermissions.filter(p => !permissions.includes(p));

            for (const permission of nonGrantedPermissions) {
              if (user.role !== 'admin') { // Admin bypasses explicit permissions
                const hasPermission = await rbacService.hasPermission(
                  user,
                  permission,
                  resource.resource,
                  resource.resourceId
                );
                expect(hasPermission).toBe(false);
              }
            }
          }
        ),
        { numRuns: 50 }
      );
    });
  });

  describe('Permission Management Properties', () => {
    it('should maintain idempotency in permission grants', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.constantFrom('read', 'write', 'delete'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, action, resource) => {
            // Grant permission twice
            await rbacService.grantPermission(user.id, action, resource.resource, resource.resourceId);
            await rbacService.grantPermission(user.id, action, resource.resource, resource.resourceId);

            // Should still have permission (idempotent)
            const hasPermission = await rbacService.hasPermission(
              user,
              action,
              resource.resource,
              resource.resourceId
            );
            expect(hasPermission).toBe(true);
          }
        ),
        { numRuns: 50 }
      );
    });

    it('should handle permission revocation correctly', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.constantFrom('read', 'write', 'delete'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, action, resource) => {
            // Grant permission
            await rbacService.grantPermission(user.id, action, resource.resource, resource.resourceId);

            // Verify permission exists
            let hasPermission = await rbacService.hasPermission(
              user,
              action,
              resource.resource,
              resource.resourceId
            );
            expect(hasPermission).toBe(true);

            // Revoke permission
            await rbacService.revokePermission(user.id, action, resource.resource, resource.resourceId);

            // Verify permission is revoked (unless admin)
            if (user.role !== 'admin') {
              hasPermission = await rbacService.hasPermission(
                user,
                action,
                resource.resource,
                resource.resourceId
              );
              expect(hasPermission).toBe(false);
            }
          }
        ),
        { numRuns: 50 }
      );
    });
  });

  describe('Role-Based Access Properties', () => {
    it('should maintain role hierarchy consistency', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.constantFrom('read', 'write', 'delete'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, action, resource) => {
            const roles = ['viewer', 'user', 'admin'];

            for (let i = 0; i < roles.length; i++) {
              user.role = roles[i] as any;
              const currentRolePermission = await rbacService.hasPermission(
                user,
                action,
                resource.resource,
                resource.resourceId
              );

              // Admin should have equal or more permissions than lower roles
              if (roles[i] === 'admin' && i > 0) {
                user.role = roles[i - 1] as any;
                const lowerRolePermission = await rbacService.hasPermission(
                  user,
                  action,
                  resource.resource,
                  resource.resourceId
                );
                expect(currentRolePermission).toBeGreaterThanOrEqual(lowerRolePermission);
              }
            }
          }
        ),
        { numRuns: 30 }
      );
    });

    it('should handle cross-organization permission isolation', () => {
      fc.assert(
        fc.property(
          generators.user,
          generators.user,
          fc.constantFrom('read', 'write', 'delete'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user1, user2, action, resource) => {
            // Ensure different organizations
            if (user1.organizationId === user2.organizationId) {
              user2.organizationId = fc.uuid().generate();
            }

            // Grant permission to user1 only
            await rbacService.grantPermission(user1.id, action, resource.resource, resource.resourceId);

            // User1 should have permission
            const user1HasPermission = await rbacService.hasPermission(
              user1,
              action,
              resource.resource,
              resource.resourceId
            );
            expect(user1HasPermission).toBe(true);

            // User2 should not have permission (unless admin)
            const user2HasPermission = await rbacService.hasPermission(
              user2,
              action,
              resource.resource,
              resource.resourceId
            );
            if (user2.role !== 'admin') {
              expect(user2HasPermission).toBe(false);
            }
          }
        ),
        { numRuns: 30 }
      );
    });
  });

  describe('Permission Consistency Properties', () => {
    it('should maintain permission state consistency', () => {
      fc.assert(
        fc.property(
          generators.user,
          fc.array(fc.constantFrom('read', 'write', 'delete')),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (user, permissions, resource) => {
            // Grant all permissions
            for (const permission of permissions) {
              await rbacService.grantPermission(user.id, permission, resource.resource, resource.resourceId);
            }

            // Check all granted permissions exist
            for (const permission of permissions) {
              const hasPermission = await rbacService.hasPermission(
                user,
                permission,
                resource.resource,
                resource.resourceId
              );
              expect(hasPermission).toBe(true);
            }

            // Get user permissions and verify consistency
            const userPermissions = await rbacService.getUserPermissions(
              user.id,
              resource.resource,
              resource.resourceId
            );

            // All granted permissions should be in the user's permission list
            for (const permission of permissions) {
              expect(userPermissions).toContain(permission);
            }
          }
        ),
        { numRuns: 30 }
      );
    });

    it('should handle permission inheritance from organization settings', () => {
      fc.assert(
        fc.property(
          generators.organization,
          generators.user,
          fc.constantFrom('read', 'write', 'delete'),
          fc.record({
            resource: fc.constantFrom('users', 'leads', 'campaigns', 'agents'),
            resourceId: fc.uuid()
          }),
          async (org, user, action, resource) => {
            // Set user organization
            user.organizationId = org.id;

            // Test organization-level permissions
            const orgHasPermission = await rbacService.hasOrganizationPermission(
              org.id,
              action,
              resource.resource
            );

            // User permissions should be consistent with organization permissions
            const userHasPermission = await rbacService.hasPermission(
              user,
              action,
              resource.resource,
              resource.resourceId
            );

            // If organization doesn't have permission, user shouldn't either (unless admin)
            if (!orgHasPermission && user.role !== 'admin') {
              expect(userHasPermission).toBe(false);
            }
          }
        ),
        { numRuns: 30 }
      );
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';
import request from 'supertest';
import { app } from '../../backend/server';
import { db } from '../../backend/db/connection';

describe('Advanced Security Tests', () => {
  let organizationId: string;
  let userId: string;
  let authToken: string;
  let adminToken: string;

  beforeEach(async () => {
    // Create test organization
    const orgResult = await db.insert({
      into: 'organizations',
      values: {
        name: 'Advanced Security Test Organization',
        domain: 'advanced-security-test.com',
        plan: 'enterprise',
        settings: {
          enforce_mfa: true,
          session_timeout: 3600,
          ip_whitelist: ['127.0.0.1', '::1'],
        },
        created_at: new Date(),
        updated_at: new Date(),
      },
      returning: ['id'],
    });

    organizationId = orgResult[0].id;

    // Create regular user
    const userResult = await db.insert({
      into: 'users',
      values: {
        organization_id: organizationId,
        email: 'user@advanced-security.com',
        name: 'Regular User',
        role: 'user',
        is_active: true,
        mfa_enabled: true,
        created_at: new Date(),
        updated_at: new Date(),
      },
      returning: ['id'],
    });

    userId = userResult[0].id;

    // Create admin user
    const adminResult = await db.insert({
      into: 'users',
      values: {
        organization_id: organizationId,
        email: 'admin@advanced-security.com',
        name: 'Admin User',
        role: 'admin',
        is_active: true,
        mfa_enabled: true,
        created_at: new Date(),
        updated_at: new Date(),
      },
      returning: ['id'],
    });

    const adminId = adminResult[0].id;

    // Get auth tokens
    const userLoginResponse = await request(app)
      .post('/api/auth/login')
      .send({
        email: 'user@advanced-security.com',
        password: 'testpassword',
        mfa_code: '123456',
      });

    authToken = userLoginResponse.body.token;

    const adminLoginResponse = await request(app)
      .post('/api/auth/login')
      .send({
        email: 'admin@advanced-security.com',
        password: 'adminpassword',
        mfa_code: '123456',
      });

    adminToken = adminLoginResponse.body.token;
  });

  afterEach(async () => {
    // Clean up test data
    await db.delete().from('audit_trail').where('organization_id', '=', organizationId);
    await db.delete().from('users').where('organization_id', '=', organizationId);
    await db.delete().from('organizations').where('id', '=', organizationId);
  });

  describe('Multi-Factor Authentication Security', () => {
    it('should enforce MFA for sensitive operations', async () => {
      // Test sensitive operations without MFA
      const sensitiveOperations = [
        { method: 'post', path: '/api/users', data: { email: 'new@example.com', name: 'New User' } },
        { method: 'put', path: `/api/users/${userId}`, data: { role: 'admin' } },
        { method: 'delete', path: `/api/users/${userId}` },
        { method: 'post', path: '/api/payments/refund', data: { amount: 1000 } },
      ];

      for (const operation of sensitiveOperations) {
        await request(app)[operation.method](operation.path)
          .set('Authorization', `Bearer ${authToken}`)
          .send(operation.data)
          .expect(401); // Should require MFA
      }

      // Test with MFA token
      const mfaTokenResponse = await request(app)
        .post('/api/auth/mfa/verify')
        .send({
          email: 'user@advanced-security.com',
          mfa_code: '123456',
        })
        .expect(200);

      const mfaAuthToken = mfaTokenResponse.body.mfa_token;

      // Should succeed with MFA token
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${mfaAuthToken}`)
        .expect(200);
    });

    it('should handle MFA backup codes', async () => {
      // Generate backup codes
      const backupCodesResponse = await request(app)
        .post('/api/auth/mfa/backup-codes')
        .set('Authorization', `Bearer ${authToken}`)
        .expect(200);

      expect(backupCodesResponse.body).toMatchObject({
        backup_codes: expect.arrayContaining([expect.stringMatching(/^\d{6}$/)]),
        generated_at: expect.any(String),
      });

      const backupCode = backupCodesResponse.body.backup_codes[0];

      // Test login with backup code
      const backupLoginResponse = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'user@advanced-security.com',
          password: 'testpassword',
          backup_code: backupCode,
        })
        .expect(200);

      expect(backupLoginResponse.body).toHaveProperty('token');
      expect(backupLoginResponse.body.auth_method).toBe('backup_code');
    });

    it('should detect and prevent MFA bypass attempts', async () => {
      const bypassAttempts = [
        { mfa_code: '000000' }, // Invalid code
        { mfa_code: '1234567' }, // Wrong length
        { mfa_code: 'abcdef' }, // Non-numeric
        { backup_code: 'invalid' }, // Invalid backup code
        { mfa_code: null }, // Missing MFA
      ];

      for (const attempt of bypassAttempts) {
        await request(app)
          .post('/api/auth/login')
          .send({
            email: 'user@advanced-security.com',
            password: 'testpassword',
            ...attempt,
          })
          .expect(401);
      }

      // Check for account lockout after multiple failed attempts
      await request(app)
        .post('/api/auth/login')
        .send({
          email: 'user@advanced-security.com',
          password: 'testpassword',
          mfa_code: '000000',
        })
        .expect(423); // Account locked
    });
  });

  describe('Session Security', () => {
    it('should enforce session timeout', async () => {
      // Create a session
      const sessionResponse = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'user@advanced-security.com',
          password: 'testpassword',
          mfa_code: '123456',
        })
        .expect(200);

      const sessionToken = sessionResponse.body.token;

      // Simulate session expiration by manipulating token
      const expiredToken = sessionToken.replace(/exp:\d+/, `exp:${Math.floor(Date.now() / 1000) - 3600}`);

      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${expiredToken}`)
        .expect(401); // Session expired
    });

    it('should handle concurrent session limits', async () => {
      // Create multiple sessions
      const sessions = [];
      for (let i = 0; i < 5; i++) {
        const response = await request(app)
          .post('/api/auth/login')
          .send({
            email: 'user@advanced-security.com',
            password: 'testpassword',
            mfa_code: '123456',
          })
          .expect(200);
        sessions.push(response.body.token);
      }

      // Should only allow configured number of concurrent sessions
      const activeSessionsResponse = await request(app)
        .get('/api/auth/sessions')
        .set('Authorization', `Bearer ${sessions[0]}`)
        .expect(200);

      expect(activeSessionsResponse.body.sessions.length).toBeLessThanOrEqual(3); // Assuming 3 session limit
    });

    it('should invalidate all sessions on password change', async () => {
      // Create initial session
      const sessionResponse = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'user@advanced-security.com',
          password: 'testpassword',
          mfa_code: '123456',
        })
        .expect(200);

      const sessionToken = sessionResponse.body.token;

      // Change password
      await request(app)
        .put('/api/auth/password')
        .set('Authorization', `Bearer ${sessionToken}`)
        .send({
          current_password: 'testpassword',
          new_password: 'newpassword',
        })
        .expect(200);

      // Previous session should be invalidated
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${sessionToken}`)
        .expect(401); // Session invalidated
    });
  });

  describe('IP and Geolocation Security', () => {
    it('should enforce IP whitelist restrictions', async () => {
      // Test from whitelisted IP
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${authToken}`)
        .set('X-Forwarded-For', '127.0.0.1')
        .expect(200);

      // Test from non-whitelisted IP
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${authToken}`)
        .set('X-Forwarded-For', '192.168.1.100')
        .expect(403); // IP not whitelisted
    });

    it('should detect suspicious login patterns', async () => {
      // Simulate rapid login attempts from different locations
      const locations = ['US', 'CN', 'RU', 'BR', 'IN'];
      
      for (const location of locations) {
        await request(app)
          .post('/api/auth/login')
          .set('X-Forwarded-For', `1.2.3.${Math.floor(Math.random() * 255)}`)
          .set('X-Country-Code', location)
          .send({
            email: 'user@advanced-security.com',
            password: 'wrongpassword',
          })
          .expect(401);
      }

      // Should trigger security alert
      const securityAlertsResponse = await request(app)
        .get('/api/security/alerts')
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(securityAlertsResponse.body.alerts).toEqual(
        expect.arrayContaining([
          expect.objectContaining({
            type: 'suspicious_login_pattern',
            severity: 'high',
          }),
        ])
      );
    });

    it('should handle geolocation-based access control', async () => {
      // Restrict access to certain countries
      await request(app)
        .put('/api/organizations/security')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          allowed_countries: ['US', 'CA', 'GB'],
          block_high_risk_countries: true,
        })
        .expect(200);

      // Test from allowed country
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${authToken}`)
        .set('X-Country-Code', 'US')
        .expect(200);

      // Test from blocked country
      await request(app)
        .get('/api/users/profile')
        .set('Authorization', `Bearer ${authToken}`)
        .set('X-Country-Code', 'KP') // North Korea - high risk
        .expect(403); // Country blocked
    });
  });

  describe('Advanced Input Validation', () => {
    it('should prevent LDAP injection attacks', async () => {
      const ldapPayloads = [
        '*)(&',
        '*)(|(objectClass=*)',
        '*)(|(password=*',
        '*))%00',
        'admin)(&(password=*))',
      ];

      for (const payload of ldapPayloads) {
        await request(app)
          .post('/api/auth/login')
          .send({
            email: payload,
            password: 'anypassword',
          })
          .expect(401);
      }
    });

    it('should prevent XXE (XML External Entity) attacks', async () => {
      const maliciousXML = `<?xml version="1.0" encoding="ISO-8859-1"?>
        <!DOCTYPE foo [
          <!ELEMENT foo ANY >
          <!ENTITY xxe SYSTEM "file:///etc/passwd" >]>
        <foo>&xxe;</foo>`;

      await request(app)
        .post('/api/import/xml')
        .set('Authorization', `Bearer ${authToken}`)
        .set('Content-Type', 'application/xml')
        .send(maliciousXML)
        .expect(400); // Should reject XXE attempts
    });

    it('should prevent deserialization attacks', async () => {
      const maliciousPayloads = [
        'O:8:"stdClass":0:{}',
        'a:1:{i:0;O:8:"stdClass":0:{}}',
        '{"__proto__":{"admin":true}}',
        '{"constructor":{"prototype":{"admin":true}}}',
      ];

      for (const payload of maliciousPayloads) {
        await request(app)
          .post('/api/data/process')
          .set('Authorization', `Bearer ${authToken}`)
          .send({ data: payload })
