              password: 'wrongpassword',
            })
        );
      }

      const suspiciousResults = await Promise.allSettled(suspiciousPromises);
      const rejected = suspiciousResults.filter(r => r.status === 'rejected' || (r.status === 'fulfilled' && r.value.status >= 400));
      
