      const data = {
        'user:1': { name: 'John' },
        'user:2': { name: 'Jane' }
      };

      const result = await service.setWithPattern('user:*', data, 1800);

      expect(result).toBe(true);
      expect((service as any).redis.set).toHaveBeenCalledTimes(2);
      expect((service as any).redis.expire).toHaveBeenCalledTimes(2);
