        .mockResolvedValueOnce(JSON.stringify({ name: 'Jane' }));

      const result = await service.getWithPattern('user:*');

      expect(result).toEqual({
        'user:1': { name: 'John' },
        'user:2': { name: 'Jane' }
      });
