    });
  });

  describe('listGetRange', () => {
    it('should get range from list', async () => {
      (service as any).redis.get.mockResolvedValue(JSON.stringify(['item1', 'item2', 'item3', 'item4']));

      const result = await service.listGetRange('mylist', 1, 2);

