        id: 'key-123',
        organizationId,
        status: 'active',
        hashedKey
      };

      mockDb.select.mockResolvedValue([mockRecord]);
      mockDb.update.mockResolvedValue({});

      const result = await validateApiKey(apiKey, organizationId);

      expect(result.valid).toBe(true);
      expect(result.record?.organizationId).toBe(organizationId);
    });

    it('should reject API keys from different organizations', async () => {
      const apiKey = generateApiKey();
      const hashedKey = hashApiKey(apiKey);
      const mockRecord = {
        id: 'key-123',
        organizationId: 'org-456', // Different org
        status: 'active',
        hashedKey
      };

      mockDb.select.mockResolvedValue([]);

      const result = await validateApiKey(apiKey, 'org-123');

      expect(result.valid).toBe(false);
      expect(result.record).toBeUndefined();
    });
  });

  describe('Security Edge Cases', () => {
    it('should handle very long API keys', () => {
      const longKey = 'api_' + 'a'.repeat(1000);

      expect(() => generateApiKey()).not.toThrow();
      expect(() => hashApiKey(longKey)).not.toThrow();
    });

    it('should handle API keys with special characters', () => {
      const specialKey = 'api_!@#$%^&*()_+-=[]{}|;:,.<>?';

      expect(() => hashApiKey(specialKey)).not.toThrow();
    });

    it('should maintain consistency across multiple hashing operations', () => {
      const apiKey = generateApiKey();
      const hashes: string[] = [];

      // Hash the same key multiple times
      for (let i = 0; i < 100; i++) {
        hashes.push(hashApiKey(apiKey));
      }

      // All hashes should be identical
      expect(hashes.every(hash => hash === hashes[0])).toBe(true);
    });

    it('should generate keys with sufficient entropy', () => {
      const keys = Array.from({ length: 100 }, () => generateApiKey());
      const uniquePrefixes = new Set(keys.map(key => key.substring(0, 16)));

      // With high probability, the first 16 characters should be unique
      expect(uniquePrefixes.size).toBeGreaterThan(90);
    });
  });

  describe('Performance Considerations', () => {
    it('should hash keys efficiently', () => {
      const apiKey = generateApiKey();
      const iterations = 1000;

      const start = process.hrtime.bigint();

      for (let i = 0; i < iterations; i++) {
        hashApiKey(apiKey);
      }

      const duration = Number(process.hrtime.bigint() - start) / 1000000; // Convert to ms

      // Should complete 1000 hash operations in reasonable time (less than 1 second)
      expect(duration).toBeLessThan(1000);
    });

    it('should verify keys efficiently', () => {
      const apiKey = generateApiKey();
      const hashedKey = hashApiKey(apiKey);
      const iterations = 1000;

      const start = process.hrtime.bigint();

      for (let i = 0; i < iterations; i++) {
        verifyApiKey(apiKey, hashedKey);
      }

      const duration = Number(process.hrtime.bigint() - start) / 1000000; // Convert to ms

      // Should complete 1000 verifications in reasonable time
      expect(duration).toBeLessThan(1000);
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';
import { 
  validateAndProcessFile,
  generateSecureFilename,
  scanFileForMalware,
  fileUploadSchema,
  MAX_FILE_SIZE,
  ALLOWED_MIME_TYPES
} from '../../../backend/middleware/file-upload';

describe('File Upload Security', () => {
  describe('generateSecureFilename', () => {
    it('should generate a secure filename with timestamp and random string', () => {
      const filename = generateSecureFilename('test.jpg');
      expect(filename).toMatch(/^\d+_[a-f0-9]{16}\.jpg$/);
    });

    it('should handle different extensions', () => {
      const pdfFilename = generateSecureFilename('document.pdf');
      const txtFilename = generateSecureFilename('notes.txt');

      expect(pdfFilename).toMatch(/^\d+_[a-f0-9]{16}\.pdf$/);
      expect(txtFilename).toMatch(/^\d+_[a-f0-9]{16}\.txt$/);
    });

    it('should handle uppercase extensions', () => {
      const filename = generateSecureFilename('IMAGE.JPG');
      expect(filename).toMatch(/^\d+_[a-f0-9]{16}\.jpg$/);
    });
  });

  describe('scanFileForMalware', () => {
    it('should detect executable files', async () => {
      // Create a mock file with PE executable signature
      const peSignature = new Uint8Array([0x4D, 0x5A, 0x90, 0x00]);
      const mockFile = new File([peSignature], 'malware.exe', { type: 'application/octet-stream' });

      // Mock the slice method to return our signature
      const originalSlice = mockFile.slice;
      mockFile.slice = jest.fn(() => ({
        arrayBuffer: jest.fn().mockResolvedValue(peSignature.buffer)
      }));

      const result = await scanFileForMalware(mockFile);
      expect(result.safe).toBe(false);
      expect(result.threats).toContain('Executable file detected');

      // Restore original method
      mockFile.slice = originalSlice;
    });

    it('should allow clean image files', async () => {
      const mockFile = new File(['fake image data'], 'image.jpg', { type: 'image/jpeg' });

      // Mock the slice method to return clean data
      const originalSlice = mockFile.slice;
      mockFile.slice = jest.fn(() => ({
        arrayBuffer: jest.fn().mockResolvedValue(new ArrayBuffer(20))
      }));

      const result = await scanFileForMalware(mockFile);
      expect(result.safe).toBe(true);
      expect(result.threats).toBeUndefined();

      // Restore original method
      mockFile.slice = originalSlice;
    });

    it('should detect script content in non-script files', async () => {
      const scriptContent = '<script>alert("xss")</script>';
      const mockFile = new File([scriptContent], 'image.jpg', { type: 'image/jpeg' });

      // Mock the slice method to return script content
      const originalSlice = mockFile.slice;
      mockFile.slice = jest.fn(() => ({
        arrayBuffer: jest.fn().mockResolvedValue(new TextEncoder().encode(scriptContent).buffer),
        text: jest.fn().mockResolvedValue(scriptContent)
      }));

      const result = await scanFileForMalware(mockFile);
      expect(result.safe).toBe(false);
      expect(result.threats).toContain('Script content detected in non-script file');

      // Restore original method
      mockFile.slice = originalSlice;
    });
  });

  describe('validateAndProcessFile', () => {
    it('should reject oversized files', async () => {
      const oversizedContent = new Array(MAX_FILE_SIZE + 1).fill('a').join('');
      const mockFile = new File([oversizedContent], 'large.txt', { type: 'text/plain' });

      const result = await validateAndProcessFile(mockFile);
      expect(result.valid).toBe(false);
      expect(result.errors).toContain(`File size must be less than ${MAX_FILE_SIZE / 1024 / 1024}MB`);
    });

    it('should reject disallowed file types', async () => {
      const mockFile = new File(['content'], 'script.js', { type: 'application/javascript' });

      const result = await validateAndProcessFile(mockFile);
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('File type not allowed');
    });

    it('should reject disallowed extensions', async () => {
      const mockFile = new File(['content'], 'script.exe', { type: 'application/octet-stream' });

      const result = await validateAndProcessFile(mockFile);
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('File extension not allowed');
    });

    it('should accept valid files', async () => {
      const mockFile = new File(['valid content'], 'document.pdf', { type: 'application/pdf' });

      const result = await validateAndProcessFile(mockFile);
      expect(result.valid).toBe(true);
      expect(result.filename).toMatch(/^\d+_[a-f0-9]{16}\.pdf$/);
      expect(result.buffer).toBeInstanceOf(ArrayBuffer);
    });

    it('should reject files with malware', async () => {
      const peSignature = new Uint8Array([0x4D, 0x5A, 0x90, 0x00]);
      const mockFile = new File([peSignature], 'malware.pdf', { type: 'application/pdf' });

      const result = await validateAndProcessFile(mockFile);
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Executable file detected');
    });
  });

  describe('fileUploadSchema', () => {
    it('should validate file size', () => {
      const oversizedContent = new Array(MAX_FILE_SIZE + 1).fill('a').join('');
      const mockFile = new File([oversizedContent], 'large.txt', { type: 'text/plain' });

      const result = fileUploadSchema.safeParse({ file: mockFile });
      expect(result.success).toBe(false);
    });

    it('should validate file type', () => {
      const mockFile = new File(['content'], 'script.js', { type: 'application/javascript' });

      const result = fileUploadSchema.safeParse({ file: mockFile });
      expect(result.success).toBe(false);
    });

    it('should validate file extension', () => {
      const mockFile = new File(['content'], 'script.exe', { type: 'application/octet-stream' });

      const result = fileUploadSchema.safeParse({ file: mockFile });
      expect(result.success).toBe(false);
    });

    it('should accept valid files', () => {
      const mockFile = new File(['content'], 'document.pdf', { type: 'application/pdf' });

      const result = fileUploadSchema.safeParse({ file: mockFile });
      expect(result.success).toBe(true);
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';
import { 
  calculateEntropy, 
  validatePasswordStrength 
} from '../../../backend/lib/auth';

describe('Password Security Enhancements', () => {
  describe('calculateEntropy', () => {
    it('should calculate low entropy for simple passwords', () => {
      const entropy = calculateEntropy('password');
      expect(entropy).toBeLessThan(50);
    });

    it('should calculate higher entropy for complex passwords', () => {
      const entropy = calculateEntropy('MyP@ssw0rd!123');
      expect(entropy).toBeGreaterThan(60);
    });

    it('should give bonus for character variety', () => {
      const simpleEntropy = calculateEntropy('aaaaaaaa');
      const variedEntropy = calculateEntropy('aA1!aA1!');
      expect(variedEntropy).toBeGreaterThan(simpleEntropy);
    });
  });

  describe('validatePasswordStrength', () => {
    it('should reject passwords shorter than 12 characters', () => {
      const result = validatePasswordStrength('Short1!');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must be at least 12 characters long');
    });

    it('should reject passwords with low entropy', () => {
      const result = validatePasswordStrength('aaaaaaaaaaaa');
      expect(result.valid).toBe(false);
      expect(result.errors.some(e => e.includes('Password is too weak'))).toBe(true);
    });

    it('should reject passwords without uppercase letters', () => {
      const result = validatePasswordStrength('mypassword123!');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must contain at least one uppercase letter');
    });

    it('should reject passwords without lowercase letters', () => {
      const result = validatePasswordStrength('MYPASSWORD123!');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must contain at least one lowercase letter');
    });

    it('should reject passwords without numbers', () => {
      const result = validatePasswordStrength('MyPassword!');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must contain at least one number');
    });

    it('should reject passwords without special characters', () => {
      const result = validatePasswordStrength('MyPassword123');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password must contain at least one special character');
    });

    it('should reject passwords with repeated characters', () => {
      const result = validatePasswordStrength('MyPassword!!!123');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password cannot contain 3 or more repeated characters');
    });

    it('should reject passwords with sequential characters', () => {
      const result = validatePasswordStrength('MyPassword123abc');
      expect(result.valid).toBe(false);
      expect(result.errors).toContain('Password cannot contain sequential characters');
    });

    it('should reject common password patterns', () => {
      const result = validatePasswordStrength('MyPassword123!');
      expect(result.valid).toBe(false);
      expect(result.errors.some(e => e.includes('common patterns'))).toBe(true);
    });

    it('should accept strong passwords', () => {
      const result = validatePasswordStrength('Tr0ub4dor&3!');
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });
});

